"use client"

import * as React from "react"
import {
  CircleAlert as CircleAlertIcon,
  LoaderCircle as LoaderCircleIcon,
  Maximize2 as MaximizeIcon,
} from "honestui/icons"

import { cn } from "@/lib/utils"
import {
  Dialog,
  DialogBody,
  DialogHeader,
  DialogPopup,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog"

export type AgentScreenStatus = "connecting" | "live" | "offline"

export type AgentScreenLabels = {
  open: string
  connecting: string
  offline: string
}

export const defaultAgentScreenLabels: AgentScreenLabels = {
  open: "Open",
  connecting: "Connecting to the agent's screen…",
  offline: "The agent's screen is not available.",
}

export type AgentScreenProps = Omit<React.ComponentProps<"div">, "children" | "title"> & {
  /** Names the screen, such as "Research agent's screen". */
  title: string
  /** Defaults to "live". The media is shown only while live. */
  status?: AgentScreenStatus
  /** The capture or stream URL. */
  src?: string
  /** Set to "video" when `src` is a video. */
  mediaType?: "image" | "video"
  /** Describes what is on the screen, for people who cannot see it. */
  alt: string
  /** Controls shown in the viewer's header, such as a button to take over. */
  actions?: React.ReactNode
  labels?: Partial<AgentScreenLabels>
}

function ScreenMedia({
  src,
  mediaType,
  alt,
  isPreview = false,
  className,
}: Pick<AgentScreenProps, "src" | "mediaType" | "alt"> & {
  /** A still, unlabelled copy for the card. The viewer holds the real one. */
  isPreview?: boolean
  className?: string
}) {
  if (mediaType === "video") {
    // No autoplay: motion the person did not ask for should not start by itself.
    return isPreview ? (
      <video src={src} aria-hidden="true" muted playsInline preload="metadata" className={className} />
    ) : (
      <video src={src} aria-label={alt} controls muted playsInline className={className} />
    )
  }

  // A plain img keeps the copied component free of a framework image loader.
  // eslint-disable-next-line @next/next/no-img-element
  return <img src={src} alt={isPreview ? "" : alt} className={className} />
}

/**
 * A framed view of what an agent sees, which opens in a larger viewer. It
 * shows the image or video you pass; connecting to the agent is your
 * application's work, reported through `status`.
 */
function AgentScreen({
  title,
  status = "live",
  src,
  mediaType = "image",
  alt,
  actions,
  labels: labelsProp,
  className,
  ...props
}: AgentScreenProps) {
  const labels = { ...defaultAgentScreenLabels, ...labelsProp }
  const isLive = status === "live" && Boolean(src)

  const frame =
    "relative block aspect-video w-full overflow-hidden rounded-[var(--hui-radius-4)] border-[0.5px] border-[var(--hui-color-border-base-primary)] bg-[var(--hui-color-background-base-secondary)] p-0"

  return (
    <div
      data-slot="agent-screen"
      data-status={status}
      className={cn(
        "flex w-full min-w-0 flex-col gap-[var(--hui-space-3)] text-[var(--hui-color-foreground-base-primary)] [font-size:var(--hui-font-size-small)] [line-height:var(--hui-line-height-small)]",
        className
      )}
      {...props}
    >
      {isLive ? (
        <Dialog>
          <DialogTrigger
            aria-label={`${labels.open}: ${title}`}
            className={cn(
              frame,
              "group/screen cursor-pointer outline-none motion-safe:[transition:var(--hui-transition-interactive)] hover:shadow-[var(--hui-shadow-lifted)] focus-visible:[outline:var(--hui-focus-ring)] focus-visible:outline-offset-[var(--hui-focus-ring-offset-accent)]"
            )}
          >
            <ScreenMedia
              src={src}
              mediaType={mediaType}
              alt={alt}
              isPreview
              className="absolute inset-0 size-full object-cover"
            />
            {/* Always visible, so opening does not depend on hover. */}
            <span className="absolute end-[var(--hui-space-3)] bottom-[var(--hui-space-3)] inline-flex items-center gap-[var(--hui-space-2)] rounded-[var(--hui-radius-2)] bg-[var(--hui-color-background-base-primary)] px-[var(--hui-space-3)] py-[var(--hui-space-2)] shadow-[var(--hui-shadow-soft)] [font-weight:var(--hui-font-weight-medium)]">
              <MaximizeIcon aria-hidden="true" className="size-3.5" />
              {labels.open}
            </span>
          </DialogTrigger>
          <DialogPopup className="w-[min(960px,90vw)] max-w-[90vw]">
            <DialogHeader className="flex flex-row items-center justify-between gap-[var(--hui-space-4)] pe-[var(--hui-space-10)]">
              <DialogTitle>{title}</DialogTitle>
              {actions && <div className="flex shrink-0 items-center gap-[var(--hui-space-2)]">{actions}</div>}
            </DialogHeader>
            <DialogBody>
              <ScreenMedia
                src={src}
                mediaType={mediaType}
                alt={alt}
                className="block h-auto max-h-[70vh] w-full rounded-[var(--hui-radius-2)] object-contain"
              />
            </DialogBody>
          </DialogPopup>
        </Dialog>
      ) : (
        <div className={cn(frame, "flex items-center justify-center p-[var(--hui-space-5)]")}>
          <p
            role="status"
            className="m-0 flex max-w-full items-center gap-[var(--hui-space-3)] text-center text-[var(--hui-color-foreground-base-secondary)]"
          >
            {status === "connecting" ? (
              <LoaderCircleIcon aria-hidden="true" className="size-4 shrink-0 motion-safe:animate-spin" />
            ) : (
              <CircleAlertIcon strokeWidth={1.5} strokeLinecap="round" aria-hidden="true" className="size-4 shrink-0" />
            )}
            {status === "connecting" ? labels.connecting : labels.offline}
          </p>
        </div>
      )}
      <p className="m-0 truncate [font-weight:var(--hui-font-weight-medium)]">{title}</p>
    </div>
  )
}

export { AgentScreen }

"use client"

import * as React from "react"
import {
  CircleAlert as CircleAlertIcon,
  CircleCheck as CircleCheckIcon,
  LoaderCircle as LoaderCircleIcon,
  X as CloseIcon,
} from "honestui/icons"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import { Input } from "@/components/ui/input"
import { Radio, RadioGroup } from "@/components/ui/radio-group"

export type ApprovalOption = {
  value: string
  label: string
}

export type ApprovalQuestion = {
  id: string
  /** The question, in the agent's words. */
  prompt: string
  /** "single" offers one choice. "multiple" offers any number. */
  type: "single" | "multiple"
  options: ApprovalOption[]
  /** Adds a text field for an answer that is not among the options. */
  allowCustom?: boolean
  /** A required question cannot be skipped, and Send waits for it. */
  required?: boolean
}

export type ApprovalAnswer = {
  /** The `value` of each chosen option. */
  selected: string[]
  /** The typed answer, trimmed. Empty when nothing was typed. */
  custom: string
}

/** Every question's answer, keyed by question `id`. Skipped questions are present and empty. */
export type ApprovalAnswers = Record<string, ApprovalAnswer>

export type ApprovalCardLabels = {
  back: string
  skip: string
  continue: string
  send: string
  sending: string
  dismiss: string
  customAnswer: string
  customPlaceholder: string
  step: (current: number, total: number) => string
  /** Shown beside a disabled Send, so the reason is never a guess. */
  incomplete: string
  submitted: string
  error: string
}

export const defaultApprovalCardLabels: ApprovalCardLabels = {
  back: "Back",
  skip: "Skip",
  continue: "Continue",
  send: "Send",
  sending: "Sending…",
  dismiss: "Dismiss",
  customAnswer: "Another answer",
  customPlaceholder: "Something else…",
  step: (current, total) => `Question ${current} of ${total}`,
  incomplete: "Answer at least one question to send.",
  submitted: "Answers sent.",
  error: "The answers were not sent. Your choices are still here, so you can send again.",
}

const bodyText =
  "[font-size:var(--hui-font-size-small)] [letter-spacing:var(--hui-letter-spacing-small)] [line-height:var(--hui-line-height-small)]"

const emptyAnswer: ApprovalAnswer = { selected: [], custom: "" }

function isAnswered(answer: ApprovalAnswer | undefined) {
  return Boolean(answer && (answer.selected.length > 0 || answer.custom.trim() !== ""))
}

export type ApprovalCardProps = Omit<React.ComponentProps<"div">, "children" | "onSubmit"> & {
  questions: ApprovalQuestion[]
  /**
   * Receives every answer when the person presses Send. Return a promise to
   * show progress; if it rejects, the card keeps the answers and offers Send again.
   */
  onSubmit: (answers: ApprovalAnswers) => void | Promise<void>
  /** Called when the person closes the card. Without it, no close button is shown. */
  onDismiss?: () => void
  labels?: Partial<ApprovalCardLabels>
}

/**
 * Questions an agent asks before it acts, one at a time. Nothing is sent
 * until the person presses Send on the last question.
 */
function ApprovalCard({
  questions,
  onSubmit,
  onDismiss,
  labels: labelsProp,
  className,
  ...props
}: ApprovalCardProps) {
  const labels = React.useMemo(
    () => ({ ...defaultApprovalCardLabels, ...labelsProp }),
    [labelsProp]
  )
  const [index, setIndex] = React.useState(0)
  const [answers, setAnswers] = React.useState<ApprovalAnswers>({})
  const [phase, setPhase] = React.useState<"editing" | "submitting" | "submitted" | "error">(
    "editing"
  )
  const rootRef = React.useRef<HTMLDivElement>(null)
  const promptId = React.useId()

  const question = questions[Math.min(index, questions.length - 1)]
  const isLast = index >= questions.length - 1
  const answer = (question && answers[question.id]) ?? emptyAnswer
  const answered = isAnswered(answer)
  const isSubmitting = phase === "submitting"
  const canSend =
    questions.some((item) => isAnswered(answers[item.id])) &&
    questions.every((item) => !item.required || isAnswered(answers[item.id]))

  // Sending removes the focused button. Hold focus on the card so it does not
  // fall back to the top of the page.
  React.useEffect(() => {
    if (phase === "submitted") rootRef.current?.focus()
  }, [phase])

  if (!question) return null

  const updateAnswer = (next: ApprovalAnswer) => {
    setAnswers((current) => ({ ...current, [question.id]: next }))
    if (phase === "error") setPhase("editing")
  }

  const submit = async () => {
    const result: ApprovalAnswers = {}
    for (const item of questions) {
      const given = answers[item.id] ?? emptyAnswer
      result[item.id] = { selected: given.selected, custom: given.custom.trim() }
    }

    setPhase("submitting")
    try {
      await onSubmit(result)
      setPhase("submitted")
    } catch {
      setPhase("error")
    }
  }

  const cardFrame =
    "w-full min-w-0 rounded-[var(--hui-radius-4)] border-[0.5px] border-[var(--hui-color-border-base-primary)] bg-[var(--hui-color-background-base-primary)] text-[var(--hui-color-foreground-base-primary)] shadow-[var(--hui-shadow-soft)] outline-none focus-visible:[outline:var(--hui-focus-ring)]"

  if (phase === "submitted") {
    return (
      <div
        ref={rootRef}
        tabIndex={-1}
        data-slot="approval-card"
        data-phase={phase}
        className={cn(cardFrame, "p-[var(--hui-space-5)]", bodyText, className)}
        {...props}
      >
        <p role="status" className="m-0 flex items-center gap-[var(--hui-space-3)]">
          <CircleCheckIcon
            aria-hidden="true"
            className="size-4 shrink-0 text-[var(--hui-color-foreground-success-primary)]"
          />
          {labels.submitted}
        </p>
      </div>
    )
  }

  return (
    <div
      ref={rootRef}
      tabIndex={-1}
      data-slot="approval-card"
      data-phase={phase}
      className={cn(cardFrame, bodyText, className)}
      {...props}
    >
      <div className="flex flex-col gap-[var(--hui-space-4)] p-[var(--hui-space-5)]">
        <div className="flex items-start gap-[var(--hui-space-3)]">
          <div className="flex min-w-0 flex-1 flex-col gap-[var(--hui-space-2)]">
            {questions.length > 1 && (
              <p
                aria-live="polite"
                className="m-0 text-[var(--hui-color-foreground-base-secondary)] [font-size:var(--hui-font-size-mini)] [line-height:var(--hui-line-height-mini)]"
              >
                {labels.step(index + 1, questions.length)}
              </p>
            )}
            <p
              id={promptId}
              className="m-0 break-words [font-size:var(--hui-font-size-regular)] [font-weight:var(--hui-font-weight-medium)] [letter-spacing:var(--hui-letter-spacing-regular)] [line-height:var(--hui-line-height-regular)]"
            >
              {question.prompt}
            </p>
          </div>
          {onDismiss && (
            <Button
              variant="link"
              size="icon-sm"
              aria-label={labels.dismiss}
              onClick={onDismiss}
              className="-me-[var(--hui-space-2)] -mt-[var(--hui-space-2)]"
            >
              <CloseIcon aria-hidden="true" />
            </Button>
          )}
        </div>

        {question.type === "single" ? (
          <RadioGroup
            key={`${question.id}-options`}
            aria-labelledby={promptId}
            disabled={isSubmitting}
            value={answer.selected[0] ?? ""}
            onValueChange={(value) => updateAnswer({ selected: [String(value)], custom: "" })}
            className="gap-[var(--hui-space-1)]"
          >
            {question.options.map((option) => (
              <OptionRow key={option.value} label={option.label}>
                {(labelId) => <Radio value={option.value} aria-labelledby={labelId} />}
              </OptionRow>
            ))}
          </RadioGroup>
        ) : (
          <div
            key={`${question.id}-options`}
            role="group"
            aria-labelledby={promptId}
            className="flex flex-col gap-[var(--hui-space-1)]"
          >
            {question.options.map((option) => (
              <OptionRow key={option.value} label={option.label}>
                {(labelId) => (
                  <Checkbox
                    size="small"
                    aria-labelledby={labelId}
                    disabled={isSubmitting}
                    checked={answer.selected.includes(option.value)}
                    onCheckedChange={(checked) =>
                      updateAnswer({
                        ...answer,
                        selected: checked
                          ? [...answer.selected, option.value]
                          : answer.selected.filter((value) => value !== option.value),
                      })
                    }
                  />
                )}
              </OptionRow>
            ))}
          </div>
        )}

        {question.allowCustom && (
          <Input
            key={`${question.id}-custom`}
            size="sm"
            aria-label={labels.customAnswer}
            placeholder={labels.customPlaceholder}
            disabled={isSubmitting}
            value={answer.custom}
            onChange={(event) =>
              updateAnswer({
                // A single-choice question holds one answer: typed or picked, not both.
                selected: question.type === "single" ? [] : answer.selected,
                custom: event.target.value,
              })
            }
          />
        )}

        {phase === "error" && (
          <p role="alert" className="m-0 flex items-start gap-[var(--hui-space-3)]">
            <CircleAlertIcon strokeWidth={1.5} strokeLinecap="round"
              aria-hidden="true"
              className="mt-px size-3.5 shrink-0 text-[var(--hui-color-foreground-danger-primary)]"
            />
            <span className="min-w-0 break-words">{labels.error}</span>
          </p>
        )}
      </div>

      <div className="flex flex-wrap items-center justify-end gap-[var(--hui-space-3)] border-t border-[var(--hui-color-border-base-primary)] px-[var(--hui-space-5)] py-[var(--hui-space-3)]">
        {isLast && !canSend && (
          <p className="m-0 me-auto min-w-0 text-[var(--hui-color-foreground-base-secondary)]">
            {labels.incomplete}
          </p>
        )}
        {index > 0 && (
          <Button
            variant="link"
            size="sm"
            disabled={isSubmitting}
            onClick={() => setIndex(index - 1)}
          >
            {labels.back}
          </Button>
        )}
        {isLast ? (
          <Button size="sm" disabled={!canSend || isSubmitting} onClick={() => void submit()}>
            {isSubmitting && (
              <LoaderCircleIcon aria-hidden="true" className="size-3.5 motion-safe:animate-spin" />
            )}
            {isSubmitting ? labels.sending : labels.send}
          </Button>
        ) : answered || question.required ? (
          <Button size="sm" disabled={!answered} onClick={() => setIndex(index + 1)}>
            {labels.continue}
          </Button>
        ) : (
          <Button variant="secondary" size="sm" onClick={() => setIndex(index + 1)}>
            {labels.skip}
          </Button>
        )}
      </div>
    </div>
  )
}

function OptionRow({
  label,
  children,
}: {
  label: string
  /** Renders the control. It is named by `labelId`, because the label alone does not name it. */
  children: (labelId: string) => React.ReactNode
}) {
  const labelId = React.useId()

  return (
    <label className="-mx-[var(--hui-space-2)] flex min-w-0 cursor-pointer items-center gap-[var(--hui-space-3)] rounded-[var(--hui-radius-2)] px-[var(--hui-space-2)] py-[var(--hui-space-2)] motion-safe:[transition:var(--hui-transition-interactive)] hover:bg-[var(--hui-color-background-base-primary-hover)] has-disabled:cursor-not-allowed has-data-disabled:cursor-not-allowed">
      {children(labelId)}
      <span id={labelId} className="min-w-0 break-words">
        {label}
      </span>
    </label>
  )
}

export { ApprovalCard }

"use client"

import * as React from "react"
import {
  CircleAlert as CircleAlertIcon,
  FileText as FileTextIcon,
  LoaderCircle as LoaderCircleIcon,
  PanelRight as PanelRightIcon,
  X as CloseIcon,
} from "honestui/icons"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"

export type ArtifactStatus = "streaming" | "complete" | "error"

export type ArtifactLabels = {
  open: string
  showing: string
  close: string
  streaming: string
  error: string
  retry: string
}

export const defaultArtifactLabels: ArtifactLabels = {
  open: "Open",
  showing: "Showing",
  close: "Close",
  streaming: "Writing…",
  error: "This stopped before it finished.",
  retry: "Try again",
}

const smallText =
  "[font-size:var(--hui-font-size-small)] [letter-spacing:var(--hui-letter-spacing-small)] [line-height:var(--hui-line-height-small)]"

const miniText =
  "[font-size:var(--hui-font-size-mini)] [letter-spacing:var(--hui-letter-spacing-mini)] [line-height:var(--hui-line-height-mini)]"

export type ArtifactPanelProps = Omit<React.ComponentProps<"section">, "title"> & {
  /** Names the artifact, such as a file name or a document title. */
  title: string
  /** A short note under the title, such as a file type or a version. */
  description?: string
  /** Defaults to "complete". Set "streaming" while the artifact is being written. */
  status?: ArtifactStatus
  /** Controls in the header, such as Copy or Download. */
  actions?: React.ReactNode
  /** Passing it shows Close. */
  onClose?: () => void
  /** Passing it shows Try again when `status` is "error". */
  onRetry?: () => void
  /** Removes the body's padding, for content that reaches the edges, such as an embedded Code View. */
  flush?: boolean
  /** Moves focus to the panel when it mounts. Set it when a person opened the panel, not when a reply did. */
  autoFocus?: boolean
  labels?: Partial<ArtifactLabels>
}

/**
 * A surface for something an agent made, such as a file or a document, that
 * sits beside the conversation. It frames the content you pass and reports the
 * status you give it. Where it sits, and when it shows, are your layout's.
 */
function ArtifactPanel({
  title,
  description,
  status = "complete",
  actions,
  onClose,
  onRetry,
  flush = false,
  autoFocus = false,
  labels: labelsProp,
  className,
  children,
  ...props
}: ArtifactPanelProps) {
  const labels = { ...defaultArtifactLabels, ...labelsProp }
  const rootRef = React.useRef<HTMLElement>(null)
  const titleId = React.useId()

  React.useEffect(() => {
    if (autoFocus) rootRef.current?.focus()
    // Focus moves once, when the panel appears.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  return (
    <section
      ref={rootRef}
      aria-labelledby={titleId}
      aria-busy={status === "streaming"}
      tabIndex={-1}
      data-slot="artifact-panel"
      data-status={status}
      className={cn(
        "flex h-full min-h-0 w-full min-w-0 flex-col overflow-hidden rounded-[var(--hui-radius-5)] border-[0.5px] border-[var(--hui-color-border-base-primary)] bg-[var(--hui-color-background-base-primary)] text-[var(--hui-color-foreground-base-primary)] outline-none focus-visible:[outline:var(--hui-focus-ring)]",
        smallText,
        className
      )}
      {...props}
    >
      <div
        data-slot="artifact-panel-header"
        className="flex min-w-0 shrink-0 items-center gap-[var(--hui-space-3)] border-b-[0.5px] border-[var(--hui-color-border-base-primary)] py-[var(--hui-space-2)] ps-[var(--hui-space-4)] pe-[var(--hui-space-2)]"
      >
        <div className="min-w-0 flex-1">
          <p id={titleId} className="m-0 truncate [font-weight:var(--hui-font-weight-medium)]">
            {title}
          </p>
          {description && (
            <p className={cn("m-0 truncate text-[var(--hui-color-foreground-base-secondary)]", miniText)}>
              {description}
            </p>
          )}
        </div>
        {/* Always mounted, so the change to and from writing is announced. */}
        <span
          role="status"
          className="flex shrink-0 items-center gap-[var(--hui-space-2)] text-[var(--hui-color-foreground-base-secondary)]"
        >
          {status === "streaming" && (
            <>
              <LoaderCircleIcon aria-hidden="true" className="size-3.5 shrink-0 motion-safe:animate-spin" />
              {labels.streaming}
            </>
          )}
        </span>
        {(actions || onClose) && (
          <div className="flex shrink-0 items-center gap-[var(--hui-space-1)]">
            {actions}
            {onClose && (
              <Button variant="link" size="icon-sm" aria-label={labels.close} title={labels.close} onClick={onClose}>
                <CloseIcon aria-hidden="true" />
              </Button>
            )}
          </div>
        )}
      </div>

      {status === "error" && (
        <div
          role="alert"
          className="flex min-w-0 shrink-0 flex-wrap items-center gap-x-[var(--hui-space-3)] gap-y-[var(--hui-space-1)] border-b-[0.5px] border-[var(--hui-color-border-base-primary)] py-[var(--hui-space-2)] ps-[var(--hui-space-4)] pe-[var(--hui-space-2)]"
        >
          <span className="flex min-w-0 flex-1 items-start gap-[var(--hui-space-2)]">
            <CircleAlertIcon
              strokeWidth={1.5}
              strokeLinecap="round"
              aria-hidden="true"
              className="mt-px size-3.5 shrink-0 text-[var(--hui-color-foreground-danger-primary)]"
            />
            <span className="min-w-0 break-words">{labels.error}</span>
          </span>
          {onRetry && (
            <Button variant="link" size="sm" className="shrink-0" onClick={onRetry}>
              {labels.retry}
            </Button>
          )}
        </div>
      )}

      {/* Focusable so the content can be scrolled by keyboard. */}
      <div
        role="group"
        aria-labelledby={titleId}
        tabIndex={0}
        data-slot="artifact-panel-body"
        className={cn(
          "min-h-0 flex-1 overflow-auto outline-none focus-visible:[outline:var(--hui-focus-ring)] focus-visible:outline-offset-[var(--hui-focus-ring-offset-inset)]",
          !flush && "p-[var(--hui-space-4)]"
        )}
      >
        {children}
      </div>
    </section>
  )
}

export type ArtifactCardProps = Omit<React.ComponentProps<"button">, "children" | "title"> & {
  /** The same title as the panel it opens. */
  title: string
  /** A short note under the title. Replaced by the status while the artifact is unfinished. */
  description?: string
  status?: ArtifactStatus
  /** Whether this artifact's panel is showing. */
  isOpen?: boolean
  /** Replaces the document icon. */
  icon?: React.ReactNode
  labels?: Partial<ArtifactLabels>
}

/** The mention of an artifact inside a message. Pressing it is how its panel is opened again. */
function ArtifactCard({
