"use client"

import * as React from "react"
import { TriangleAlert as TriangleAlertIcon } from "honestui/icons"
import { animate, motion, useMotionValue, useReducedMotion, useTransform } from "motion/react"

import { EASE_OUT } from "@/lib/ease"
import { cn } from "@/lib/utils"
import { Popover, PopoverPopup, PopoverTrigger } from "@/components/ui/popover"

export type ContextMeterStatus = "ok" | "near" | "full"

export type ContextMeterPart = {
  /** What these tokens are, such as "Messages" or "Files". */
  label: string
  tokens: number
}

export type ContextMeterLabels = {
  title: string
  /** The trigger's name, such as "42% of context used". */
  summary: (percent: number) => string
  tokens: (used: string, limit: string) => string
  remaining: (tokens: string) => string
  near: string
  full: string
  cost: string
  /** Formats every token count. Replace it to match the person's locale. */
  number: (value: number) => string
}

const numberFormat = new Intl.NumberFormat("en-US")

export const defaultContextMeterLabels: ContextMeterLabels = {
  title: "Context window",
  summary: (percent) => `${percent}% of context used`,
  tokens: (used, limit) => `${used} of ${limit} tokens`,
  remaining: (tokens) => `${tokens} left`,
  near: "Near the limit",
  full: "At the limit",
  cost: "Cost",
  number: (value) => numberFormat.format(value),
}

const RING_RADIUS = 6
const RING_CIRCUMFERENCE = 2 * Math.PI * RING_RADIUS
const CHANGE_SECONDS = 0.6

// The icon's dot is a line too short to see until its ends are rounded.
const warningStroke = { strokeWidth: 1.5, strokeLinecap: "round" } as const

// Round down below the limit, so "100%" is shown only when the window is full.
const toPercent = (ratio: number) => (ratio >= 1 ? Math.round(ratio * 100) : Math.floor(ratio * 100))

const statusTone: Record<ContextMeterStatus, string> = {
  ok: "text-[var(--hui-color-foreground-base-primary)]",
  near: "text-[var(--hui-color-foreground-base-primary)]",
  // The darker danger step, which stays readable as small text.
  full: "text-[var(--hui-color-foreground-danger-primary-hover)]",
}

export type ContextMeterProps = Omit<React.ComponentProps<"button">, "children"> & {
  /** Tokens in the context now. */
  used: number
  /** The size of the model's context window, in tokens. */
  limit: number
  /** What the tokens are made of. Listed in the details. */
  parts?: ContextMeterPart[]
  /** A cost you have already formatted, such as "$0.42". The meter does no pricing. */
  cost?: string
  /** The share of the limit, from 0 to 1, at which the meter says it is near the limit. */
  nearAt?: number
  /** Set false to show the ring without the percentage beside it. */
  showPercent?: boolean
  /** A line under the numbers, such as what your product does when the window fills. */
  note?: React.ReactNode
  labels?: Partial<ContextMeterLabels>
}

/**
 * How full a model's context window is, as a small ring and a percentage that
 * open the exact numbers. It counts nothing itself: `used` and `limit` are the
 * figures your model or tokenizer reported. A change glides from the old
 * figure to the new one.
 */
function ContextMeter({
  used,
  limit,
  parts = [],
  cost,
  nearAt = 0.8,
  showPercent = true,
  note,
  labels: labelsProp,
  className,
  ...props
}: ContextMeterProps) {
  const labels = { ...defaultContextMeterLabels, ...labelsProp }
  const titleId = React.useId()

  const usedTokens = Math.max(used, 0)
  const ratio = limit > 0 ? usedTokens / limit : 0
  const percent = toPercent(ratio)
  const status: ContextMeterStatus = ratio >= 1 ? "full" : ratio >= nearAt ? "near" : "ok"
  const statusLabel = status === "full" ? labels.full : status === "near" ? labels.near : null

  // What the ring, the number, and the bar show while they move to a new figure.
  // The name read by assistive technology changes at once, with no steps between.
  const shouldReduceMotion = useReducedMotion() ?? false
  const shownRatio = useMotionValue(ratio)
  React.useEffect(() => {
    if (shouldReduceMotion) {
      shownRatio.set(ratio)
      return
    }
    const controls = animate(shownRatio, ratio, { duration: CHANGE_SECONDS, ease: EASE_OUT })
    return () => controls.stop()
  }, [ratio, shouldReduceMotion, shownRatio])
  const ringDash = useTransform(
    shownRatio,
    (value) => `${Math.min(value, 1) * RING_CIRCUMFERENCE} ${RING_CIRCUMFERENCE}`
  )
  const shownPercent = useTransform(shownRatio, (value) => `${toPercent(value)}%`)
  const barWidth = useTransform(shownRatio, (value) => `${Math.min(value, 1) * 100}%`)
  const tokensText = labels.tokens(labels.number(usedTokens), labels.number(limit))

  return (
    <Popover>
      <PopoverTrigger
        data-slot="context-meter"
        data-status={status}
        className={cn(
          "inline-flex shrink-0 cursor-pointer items-center gap-[var(--hui-space-2)] rounded-[var(--hui-radius-2)] border-0 bg-transparent px-[var(--hui-space-2)] py-[var(--hui-space-2)] tabular-nums outline-none [font-size:var(--hui-font-size-mini)] [letter-spacing:var(--hui-letter-spacing-mini)] [line-height:var(--hui-line-height-mini)] motion-safe:[transition:var(--hui-transition-interactive)] hover:bg-[var(--hui-color-background-base-primary-hover)] focus-visible:[outline:var(--hui-focus-ring)] data-popup-open:bg-[var(--hui-color-background-base-primary-hover)]",
          statusTone[status],
          className
        )}
        {...props}
      >
        <svg aria-hidden="true" viewBox="0 0 16 16" className="size-4 shrink-0 -rotate-90">
          <circle cx="8" cy="8" r={RING_RADIUS} fill="none" stroke="currentColor" strokeWidth="2" opacity="0.2" />
          <motion.circle
            cx="8"
            cy="8"
            r={RING_RADIUS}
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            style={{ strokeDasharray: ringDash }}
          />
        </svg>
        {showPercent && (
          <motion.span aria-hidden="true" data-slot="context-meter-percent">
            {shownPercent}
          </motion.span>
        )}
        {/* The warning is a shape and a word, so it does not depend on the color. */}
        {statusLabel && <TriangleAlertIcon {...warningStroke} aria-hidden="true" className="size-3.5 shrink-0" />}
        <span className="sr-only">
          {labels.summary(percent)}
          {statusLabel && `. ${statusLabel}`}
        </span>
      </PopoverTrigger>
      <PopoverPopup align="end" aria-labelledby={titleId} className="w-64 max-w-[calc(100vw-2rem)]">
        <div data-slot="context-meter-details" className="flex flex-col gap-[var(--hui-space-3)]">
          <p id={titleId} className="m-0 [font-weight:var(--hui-font-weight-medium)]">
            {labels.title}
          </p>

          <div className="flex flex-col gap-[var(--hui-space-2)]">
            <div
              role="meter"
              aria-labelledby={titleId}
              aria-valuemin={0}
              aria-valuemax={limit}
              aria-valuenow={Math.min(usedTokens, limit)}
              aria-valuetext={tokensText}
              className="h-1.5 w-full overflow-hidden rounded-full bg-[var(--hui-color-background-base-secondary)]"
            >
              {/* A border, not a fill, so the bar survives forced colors. */}
              <motion.div
                className={cn("h-full rounded-full border-t-[6px] border-current", statusTone[status])}
                style={{ width: barWidth }}
              />
            </div>
            <p className="m-0 flex flex-wrap items-baseline justify-between gap-x-[var(--hui-space-3)]">
              <span>{tokensText}</span>
              <span className="text-[var(--hui-color-foreground-base-secondary)]">
                {labels.remaining(labels.number(Math.max(limit - usedTokens, 0)))}
              </span>
            </p>
            {statusLabel && (
              <p className={cn("m-0 flex items-center gap-[var(--hui-space-2)]", statusTone[status])}>
                <TriangleAlertIcon {...warningStroke} aria-hidden="true" className="size-3.5 shrink-0" />
                <span className="[font-weight:var(--hui-font-weight-medium)]">{statusLabel}</span>
              </p>
            )}
          </div>

          {(parts.length > 0 || cost !== undefined) && (
            <dl className="m-0 grid grid-cols-[minmax(0,1fr)_auto] gap-x-[var(--hui-space-4)] gap-y-[var(--hui-space-1)] border-t-[0.5px] border-[var(--hui-color-border-base-primary)] pt-[var(--hui-space-3)]">
              {parts.map((part) => (
                <React.Fragment key={part.label}>
                  <dt className="min-w-0 break-words text-[var(--hui-color-foreground-base-secondary)]">
                    {part.label}
                  </dt>
                  <dd className="m-0 text-end tabular-nums">{labels.number(part.tokens)}</dd>
                </React.Fragment>
              ))}
              {cost !== undefined && (
                <>
                  <dt className="text-[var(--hui-color-foreground-base-secondary)]">{labels.cost}</dt>
                  <dd className="m-0 text-end tabular-nums">{cost}</dd>
                </>
              )}
            </dl>
          )}

          {note && (
            <p className="m-0 break-words text-[var(--hui-color-foreground-base-secondary)]">{note}</p>
          )}
        </div>
      </PopoverPopup>
    </Popover>
  )
}

export { ContextMeter }

"use client"

import * as React from "react"
import {
  CircleAlert as CircleAlertIcon,
  CircleCheck as CircleCheckIcon,
  LoaderCircle as LoaderCircleIcon,
} from "honestui/icons"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"

export type DiffTableColumn = {
  id: string
  header: string
}

export type DiffTableRow = {
  id: string
  /** "added" and "removed" rows are proposed edits. "unchanged" rows give context. */
  change: "unchanged" | "added" | "removed"
  /** Names the row in its checkbox label, such as "Rocky Road". */
  name: string
  /** The cell for each column `id`. */
  cells: Record<string, React.ReactNode>
}

export type DiffTableLabels = {
  change: string
  added: string
  removed: string
  unchanged: string
  includeAdded: (name: string) => string
  includeRemoved: (name: string) => string
  summary: (additions: number, removals: number) => string
  apply: (count: number) => string
  applying: string
  applied: (count: number) => string
  error: string
}

export const defaultDiffTableLabels: DiffTableLabels = {
  change: "Change",
  added: "Add",
  removed: "Remove",
  unchanged: "No change",
  includeAdded: (name) => `Include adding ${name}`,
  includeRemoved: (name) => `Include removing ${name}`,
  summary: (additions, removals) =>
    `${additions} ${additions === 1 ? "addition" : "additions"}, ${removals} ${removals === 1 ? "removal" : "removals"} selected`,
  apply: (count) => (count === 1 ? "Apply 1 change" : `Apply ${count} changes`),
  applying: "Applying…",
  applied: (count) => (count === 1 ? "1 change applied." : `${count} changes applied.`),
  error: "The changes were not applied. Your selection is still here, so you can apply again.",
}

// Table's own header color is too light for small text, so these headers use the secondary foreground.
const headText = "text-[var(--hui-color-foreground-base-secondary)]!"

const smallText =
  "[font-size:var(--hui-font-size-small)] [letter-spacing:var(--hui-letter-spacing-small)] [line-height:var(--hui-line-height-small)]"

export type DiffTableProps = Omit<React.ComponentProps<"div">, "children" | "title"> & {
  /** What the edit is, such as "Proposed menu cleanup". */
  title: string
  columns: DiffTableColumn[]
  rows: DiffTableRow[]
  /**
   * Receives the ids of the changed rows the person kept selected. Return a
   * promise to show progress; if it rejects, the selection is kept.
   */
  onApply: (includedRowIds: string[]) => void | Promise<void>
  labels?: Partial<DiffTableLabels>
}

/**
 * Row-level edits an agent proposes to a table. Every change starts selected;
 * the person clears the ones they do not want and then applies the rest.
 */
function DiffTable({
  title,
  columns,
  rows,
  onApply,
  labels: labelsProp,
  className,
  ...props
}: DiffTableProps) {
  const labels = React.useMemo(
    () => ({ ...defaultDiffTableLabels, ...labelsProp }),
    [labelsProp]
  )
  const [excluded, setExcluded] = React.useState<ReadonlySet<string>>(new Set())
  const [phase, setPhase] = React.useState<"editing" | "applying" | "applied" | "error">("editing")
  const titleId = React.useId()

  const changedRows = rows.filter((row) => row.change !== "unchanged")
  const included = changedRows.filter((row) => !excluded.has(row.id))
  const additions = included.filter((row) => row.change === "added").length
  const removals = included.length - additions
  const isLocked = phase === "applying" || phase === "applied"

  const apply = async () => {
    setPhase("applying")
    try {
      await onApply(included.map((row) => row.id))
      setPhase("applied")
    } catch {
      setPhase("error")
    }
  }

  return (
    <div
      data-slot="diff-table"
      data-phase={phase}
      className={cn(
        "w-full min-w-0 overflow-hidden rounded-[var(--hui-radius-4)] border-[0.5px] border-[var(--hui-color-border-base-primary)] bg-[var(--hui-color-background-base-primary)] text-[var(--hui-color-foreground-base-primary)] shadow-[var(--hui-shadow-feather)]",
        smallText,
        className
      )}
      {...props}
    >
      <p
        id={titleId}
        className="m-0 border-b-[0.5px] border-[var(--hui-color-border-base-primary)] px-[var(--hui-space-4)] py-[var(--hui-space-3)] [font-weight:var(--hui-font-weight-medium)]"
      >
        {title}
      </p>
      <Table aria-labelledby={titleId}>
        <TableHeader>
          <TableRow>
            <TableHead scope="col" className={headText}>{labels.change}</TableHead>
            {columns.map((column) => (
              <TableHead key={column.id} scope="col" className={headText}>
                {column.header}
              </TableHead>
            ))}
          </TableRow>
        </TableHeader>
        <TableBody>
          {rows.map((row) => {
            const isChange = row.change !== "unchanged"
            const isIncluded = isChange && !excluded.has(row.id)
            return (
              <TableRow
                key={row.id}
                data-change={row.change}
                data-included={isIncluded ? "" : undefined}
                className={cn(
                  isIncluded && row.change === "added" && "bg-[var(--hui-color-background-success-primary)]",
                  isIncluded && row.change === "removed" && "bg-[var(--hui-color-background-danger-primary)]"
                )}
              >
                <TableCell>
                  {isChange ? (
                    <label className="flex cursor-pointer items-center gap-[var(--hui-space-3)]">
                      <Checkbox
                        size="small"
                        disabled={isLocked}
                        checked={isIncluded}
                        aria-label={
                          row.change === "added"
                            ? labels.includeAdded(row.name)
                            : labels.includeRemoved(row.name)
                        }
                        onCheckedChange={(checked) => {
                          setExcluded((current) => {
                            const next = new Set(current)
                            if (checked) next.delete(row.id)
                            else next.add(row.id)
                            return next
                          })
                          if (phase === "error") setPhase("editing")
                        }}
                      />
                      {/* The word carries the change, so the row tint is never the only cue. */}
                      <span aria-hidden="true" className="[font-weight:var(--hui-font-weight-medium)]">
                        {row.change === "added" ? `+ ${labels.added}` : `− ${labels.removed}`}
                      </span>
                    </label>
                  ) : (
                    <span className="text-[var(--hui-color-foreground-base-secondary)]">
                      {labels.unchanged}
                    </span>
                  )}
                </TableCell>
                {columns.map((column) => (
                  <TableCell
                    key={column.id}
                    className={cn(isIncluded && row.change === "removed" && "line-through")}
                  >
                    {row.cells[column.id]}
                  </TableCell>
                ))}
              </TableRow>
            )
          })}
        </TableBody>
      </Table>

      <div className="flex flex-wrap items-center justify-end gap-[var(--hui-space-3)] border-t-[0.5px] border-[var(--hui-color-border-base-primary)] px-[var(--hui-space-4)] py-[var(--hui-space-3)]">
        <p
          role={phase === "error" ? "alert" : "status"}
          className="m-0 me-auto flex min-w-0 items-start gap-[var(--hui-space-2)] text-[var(--hui-color-foreground-base-secondary)]"
        >
          {phase === "applied" ? (
            <>
              <CircleCheckIcon
                aria-hidden="true"
                className="mt-px size-3.5 shrink-0 text-[var(--hui-color-foreground-success-primary)]"
              />
              <span className="text-[var(--hui-color-foreground-base-primary)]">
                {labels.applied(included.length)}
              </span>
            </>
          ) : phase === "error" ? (
            <>
              <CircleAlertIcon strokeWidth={1.5} strokeLinecap="round"
                aria-hidden="true"
                className="mt-px size-3.5 shrink-0 text-[var(--hui-color-foreground-danger-primary)]"
              />
              <span className="min-w-0 text-[var(--hui-color-foreground-base-primary)]">{labels.error}</span>
            </>
          ) : (
            labels.summary(additions, removals)
          )}
        </p>
        {(
          <Button size="sm" disabled={included.length === 0 || isLocked} onClick={() => void apply()}>
            {phase === "applying" && (
              <LoaderCircleIcon aria-hidden="true" className="size-3.5 motion-safe:animate-spin" />
            )}
            {phase === "applying" ? labels.applying : labels.apply(included.length)}
          </Button>
        )}
      </div>
    </div>
  )
}

export { DiffTable }

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"

export type FilterTableColumn<Row> = {
  id: string
  header: string
  cell: (row: Row) => React.ReactNode
}

export type FilterTableFilter<Row> = {
  id: string
  label: string
  matches: (row: Row) => boolean
}

export type FilterTableProps<Row> = {
  /** Names the table for screen readers. */
  label: string
  columns: FilterTableColumn<Row>[]
  rows: Row[]
  getRowId: (row: Row) => string
  /** One chip each. A chip shows how many rows it matches. */
  filters: FilterTableFilter<Row>[]
  /** The chip that shows every row. */
  allLabel?: string
  /** The group name read before the chips. */
  filtersLabel?: string
  /** Shown when the chosen filter matches no rows. */
  emptyMessage?: string
  activeFilter?: string | null
  defaultActiveFilter?: string | null
  onActiveFilterChange?: (filterId: string | null) => void
  className?: string
}

const chipText =
  "[font-size:var(--hui-font-size-small)] [letter-spacing:var(--hui-letter-spacing-small)] [line-height:var(--hui-line-height-small)]"

/**
 * A table with a row of filter chips above it. Counts are computed from the
 * rows you pass, so a chip never disagrees with what it shows.
 */
function FilterTable<Row>({
  label,
  columns,
  rows,
  getRowId,
  filters,
  allLabel = "All",
  filtersLabel = "Filter rows",
  emptyMessage = "No rows match this filter.",
  activeFilter: activeFilterProp,
  defaultActiveFilter = null,
  onActiveFilterChange,
  className,
}: FilterTableProps<Row>) {
  const [uncontrolledFilter, setUncontrolledFilter] = React.useState(defaultActiveFilter)
  const activeFilter = activeFilterProp !== undefined ? activeFilterProp : uncontrolledFilter
  const active = filters.find((filter) => filter.id === activeFilter)
  const visibleRows = active ? rows.filter(active.matches) : rows

  const select = (filterId: string | null) => {
    if (activeFilterProp === undefined) setUncontrolledFilter(filterId)
    onActiveFilterChange?.(filterId)
  }

  const chips = [
    { id: null as string | null, label: allLabel, count: rows.length },
    ...filters.map((filter) => ({
      id: filter.id as string | null,
      label: filter.label,
      count: rows.filter(filter.matches).length,
    })),
  ]

  return (
    <div data-slot="filter-table" className={cn("flex w-full min-w-0 flex-col gap-[var(--hui-space-3)]", className)}>
      <div
        role="group"
        aria-label={filtersLabel}
        className="flex min-w-0 flex-wrap items-center gap-[var(--hui-space-2)]"
      >
        {chips.map((chip) => {
          const isActive = chip.id === (active?.id ?? null)
          return (
            <button
              key={chip.id ?? "all"}
              type="button"
              aria-pressed={isActive}
              onClick={() => select(chip.id)}
              className={cn(
                "inline-flex cursor-pointer items-center gap-[var(--hui-space-2)] rounded-[var(--hui-radius-full)] border-[0.5px] border-transparent bg-transparent px-[var(--hui-space-3)] py-[var(--hui-space-2)] text-[var(--hui-color-foreground-base-secondary)] outline-none [font-weight:var(--hui-font-weight-medium)] motion-safe:[transition:var(--hui-transition-interactive)] hover:bg-[var(--hui-color-background-base-primary-hover)] focus-visible:[outline:var(--hui-focus-ring)] aria-pressed:border-[var(--hui-color-border-base-secondary)] aria-pressed:bg-[var(--hui-color-background-base-primary)] aria-pressed:text-[var(--hui-color-foreground-base-primary)] aria-pressed:shadow-[var(--hui-shadow-feather)]",
                chipText
              )}
            >
              {chip.label}
              <span className="tabular-nums text-[var(--hui-color-foreground-base-secondary)]">
                {chip.count}
              </span>
            </button>
          )
        })}
      </div>

      <Table variant="surface" aria-label={label}>
        <TableHeader>
          <TableRow>
            {columns.map((column) => (
              <TableHead key={column.id} scope="col">
                {column.header}
              </TableHead>
            ))}
          </TableRow>
        </TableHeader>
        <TableBody>
          {visibleRows.length === 0 ? (
            <TableRow>
              <TableCell
                colSpan={columns.length}
                className="text-center text-[var(--hui-color-foreground-base-secondary)]"
              >
                {emptyMessage}
              </TableCell>
            </TableRow>
          ) : (
            visibleRows.map((row) => (
              <TableRow key={getRowId(row)}>
                {columns.map((column) => (
                  <TableCell key={column.id}>{column.cell(row)}</TableCell>
                ))}
              </TableRow>
            ))
          )}
        </TableBody>
      </Table>
      <p role="status" className="sr-only">
        {`${visibleRows.length} of ${rows.length}`}
      </p>
    </div>
  )
}

