  "componentGroups": [
    {
      "name": "Content",
      "components": [
        "CardHeader",
        "TextContent",
        "MarkDownRenderer",
        "Callout",
        "TextCallout",
        "Image",
        "ImageBlock",
        "ImageGallery",
        "CodeBlock",
        "Separator",
        "InlineHeader"
