export type SingleDatePickerProps = Omit<React.ComponentProps<typeof Button>, "value" | "defaultValue" | "onChange" | "children"> & {
  /** Calendar date in YYYY-MM-DD form; an empty string means no selection. */
  value: string;
  onValueChange: (value: string) => void;
  placeholder?: string;
  required?: boolean;
};

/** Uses the Honest UI calendar styling with single-day selection. */
export function SingleDatePicker({
  value,
  onValueChange,
  placeholder = "Select date",
  required = false,
  disabled,
  className,
  ...props
}: SingleDatePickerProps) {
  const [open, setOpen] = React.useState(false);
  const parsed = value ? parseISO(value) : undefined;
  const selected = parsed && isValid(parsed) ? parsed : undefined;

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger
        render={
          <Button
            {...props}
            type="button"
            variant="secondary"
            aria-required={required || undefined}
            aria-label={selected ? `${props["aria-label"] ?? "Date"}, ${format(selected, "MMM d, yyyy")}` : props["aria-label"]}
            disabled={disabled}
            className={cn("w-full justify-between text-left", !selected && "text-muted-foreground", className)}
          />
        }
      >
        <span>{selected ? format(selected, "MMM d, yyyy") : placeholder}</span>
        <CalendarIcon aria-hidden="true" className="size-4 shrink-0" />
      </PopoverTrigger>
      <PopoverContent aria-label={`${props["aria-label"] ?? "Date"} calendar`} align="start" className="w-fit max-w-[calc(100vw-2rem)] overflow-y-auto p-3">
        <DayPicker
          mode="single"
          selected={selected}
          defaultMonth={selected}
          numberOfMonths={1}
          autoFocus
          showOutsideDays
          onSelect={(day) => {
            if (!day) return;
            // Keep date-only values local; UTC conversion can shift the day.
            onValueChange(format(day, "yyyy-MM-dd"));
            setOpen(false);
          }}
          components={{ Chevron: ({ orientation }) => orientation === "left" ? <ChevronLeft aria-hidden="true" className="size-4" /> : <ChevronRight aria-hidden="true" className="size-4" /> }}
          classNames={{
            months: "relative flex",
            month: "flex flex-col",
            month_caption: "flex h-9 items-center justify-center text-sm font-medium",
            caption_label: "",
            nav: "absolute inset-x-0 top-0 flex justify-between",
            button_previous: "inline-flex size-8 items-center justify-center rounded-sm hover:bg-accent focus-visible:outline-2 focus-visible:outline-ring",
            button_next: "inline-flex size-8 items-center justify-center rounded-sm hover:bg-accent focus-visible:outline-2 focus-visible:outline-ring",
            month_grid: "border-collapse",
            weeks: "border-collapse",
            weekday: "w-10 pb-2 text-center text-xs font-normal text-muted-foreground",
            day: "size-10 p-0 text-center [&[data-disabled]>button]:text-muted-foreground [&[data-disabled]>button]:opacity-50",
            day_button: "inline-flex size-10 items-center justify-center rounded-sm text-sm outline-none hover:bg-accent focus-visible:outline-2 focus-visible:outline-ring focus-visible:-outline-offset-2",
            selected: "[&>button]:bg-[var(--hui-color-background-accent-emphasis)]! [&>button]:text-[var(--hui-color-foreground-accent-emphasis)]!",
            today: "[&:not([data-selected])>button]:ring-1 [&:not([data-selected])>button]:ring-inset [&:not([data-selected])>button]:ring-ring",
            outside: "[&:not([data-selected])>button]:text-muted-foreground",
          }}
        />
        {!required && selected && (
          <Button
            type="button"
            variant="link"
            size="sm"
            className="mt-2 w-full"
            onClick={() => {
              onValueChange("");
              setOpen(false);
            }}
          >
            Clear date
          </Button>
        )}
      </PopoverContent>
    </Popover>
  );
}

"use client";
import * as React from "react";
import { cn } from "@/lib/utils";
import { InlineText } from "./inline-text";
import { array, nodeProps, text, type Props } from "./shared";

/**
 * Container-query classes for the side-by-side layout. Each set turns on at a
 * width where that many boxes and their arrows still fit; below it, and for
 * longer chains, the boxes stack in a readable column and the arrows point down. Tailwind needs the
 * class names written out, so each set is spelled in full.
 */
const sideBySide = {
  md: {
    list: "@md:max-w-none @md:flex-row",
    node: "@md:flex-1 @md:basis-0",
    connector: "@md:flex @md:w-28 @md:shrink-0 @md:flex-col-reverse @md:items-center @md:justify-center @md:gap-1",
    arrow: "@md:w-full @md:flex-row",
    line: "@md:h-0 @md:w-auto @md:flex-1 @md:border-l-0 @md:border-t-2",
    head: "@md:mt-0 @md:-ml-[9px] @md:-rotate-90",
    label: "@md:text-center",
  },
  "2xl": {
    list: "@2xl:max-w-none @2xl:flex-row",
    node: "@2xl:flex-1 @2xl:basis-0",
    connector: "@2xl:flex @2xl:w-28 @2xl:shrink-0 @2xl:flex-col-reverse @2xl:items-center @2xl:justify-center @2xl:gap-1",
    arrow: "@2xl:w-full @2xl:flex-row",
    line: "@2xl:h-0 @2xl:w-auto @2xl:flex-1 @2xl:border-l-0 @2xl:border-t-2",
    head: "@2xl:mt-0 @2xl:-ml-[9px] @2xl:-rotate-90",
    label: "@2xl:text-center",
  },
};

function layoutFor(count: number) {
  if (count <= 2) return sideBySide.md;
  if (count === 3) return sideBySide["2xl"];
  return undefined;
}

/**
 * A chain of boxes joined by labeled arrows. The boxes are an ordered list, and
 * each one names its outgoing arrow for screen readers, so the drawn arrows are
 * hidden from assistive technology. Lines are borders and the arrowhead uses
 * currentColor, so both stay visible in forced colors.
 */
export function GeneratedDiagram({ props }: { props: Props }) {
  // While a reply streams, later nodes may not have arrived yet.
  const nodes: Props[] = [];
  for (const value of array(props.nodes)) {
    const node = nodeProps(value);
    if (!text(node.title)) break;
    nodes.push(node);
  }
  if (nodes.length === 0) return null;
  const arrows = array(props.arrows).map(text);
  const layout = layoutFor(nodes.length);
  const caption = text(props.caption);

  return (
    <figure className="@container m-0 grid gap-3">
      <ol className={cn("m-0 mx-auto flex w-full max-w-md list-none flex-col p-0", layout?.list)}>
        {nodes.map((node, i) => {
          const next = nodes[i + 1];
          const label = arrows[i] ?? "";
          return (
            <React.Fragment key={i}>
              <li className={cn("flex min-w-0", layout?.node)}>
                <div className="flex min-w-0 flex-1 flex-col items-center justify-center gap-1 rounded-[var(--hui-radius-2)] border border-[var(--hui-color-border-base-primary)] bg-[var(--hui-color-background-base-secondary)] px-4 py-4 text-center">
                  <strong className="text-sm font-semibold">
                    <InlineText value={text(node.title)} />
                  </strong>
                  {!!text(node.value) && (
                    <span className="font-mono text-2xl font-semibold [overflow-wrap:anywhere]">
                      {text(node.value)}
                    </span>
                  )}
                  {!!text(node.detail) && (
                    <span className="text-sm text-muted-foreground">
                      <InlineText value={text(node.detail)} />
                    </span>
                  )}
                </div>
                {next && (
                  <span className="sr-only">
                    {label ? <InlineText value={label} /> : "Leads to"}{" "}
                    <InlineText value={text(next.title)} />.
                  </span>
                )}
              </li>
              {next && (
                <li
                  aria-hidden
                  className={cn(
                    "grid min-h-12 grid-cols-[1fr_auto_1fr] items-center gap-2 py-1",
                    layout?.connector,
                  )}
                >
                  <span
                    className={cn(
                      "col-start-2 flex flex-col items-center text-[var(--hui-color-foreground-accent-primary)]",
                      layout?.arrow,
                    )}
                  >
                    <span className={cn("h-6 w-0 border-l-2 border-current", layout?.line)} />
                    <svg
                      viewBox="0 0 12 12"
                      className={cn("-mt-[9px] size-3 shrink-0", layout?.head)}
                      fill="none"
                      stroke="currentColor"
                      strokeWidth="2"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    >
                      <path d="M2 4.5 6 9l4-4.5" />
                    </svg>
                  </span>
                  {!!label && (
                    <span className={cn("col-start-3 text-sm text-muted-foreground", layout?.label)}>
                      <InlineText value={label} />
                    </span>
                  )}
                </li>
              )}
            </React.Fragment>
          );
        })}
      </ol>
      {!!caption && (
        <figcaption className="text-center text-sm text-muted-foreground">
          <InlineText value={caption} />
        </figcaption>
      )}
    </figure>
  );
}

"use client";
import * as React from "react";
import {
  DataGrid,
  type DataGridColumn,
} from "@/components/ui/data-grid/data-grid";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  useStateField,
  useIsStreaming,
  useTriggerAction,
  useFormName,
} from "../runtime/react";
import { array, record, text, type Props } from "./shared";
export function GeneratedEditableTable({ props }: { props: Props }) {
  const field = useStateField<unknown>(text(props.name));
  const streaming = useIsStreaming();
  const trigger = useTriggerAction();
  const formName = useFormName();
  const source = array(field.value ?? props.data).map(record);
  const definitions = array(props.columns).map(record);
  const rows = source.map((row) =>
    Object.fromEntries([
      ["id", row.id],
      ...definitions.map((column, i) => [
        text(column.key),
        array(row.values)[i],
      ]),
    ]),
  );
  const columns: DataGridColumn<Props>[] = definitions.map((column) => ({
    accessorKey: text(column.key),
    header: text(column.header),
    editable: !streaming,
    edit: ({ value, onChange, onCommit }) =>
      column.type === "select" ? (
        <select
          autoFocus
          onKeyDown={(event) => {
            if (event.key === "Enter") {
              event.preventDefault();
              onCommit();
            }
          }}
          aria-label={text(column.header)}
          value={text(value)}
          onChange={(event) => onChange(event.target.value)}
        >
          {array(column.options)
            .map(record)
            .map((option) => (
              <option key={text(option.value)} value={text(option.value)}>
                {text(option.label)}
              </option>
            ))}
        </select>
      ) : (
        <Input
          autoFocus
          onKeyDown={(event) => {
            if (event.key === "Enter") {
              event.preventDefault();
              onCommit();
            }
          }}
          aria-label={text(column.header)}
          type={
            column.type === "number"
              ? "number"
              : column.type === "date-single"
                ? "date"
                : column.type === "url"
                  ? "url"
                  : "text"
          }
          value={text(value)}
          onChange={(event) =>
            onChange(
              column.type === "number"
                ? Number(event.target.value)
                : event.target.value,
            )
          }
        />
      ),
  }));
  return (
    <div className="grid gap-3">
      <DataGrid
        data={rows}
        columns={columns}
        caption={text(props.name) || "Editable table"}
        getRowId={(row) => text(row.id)}
        onCellEdit={({ row: editedRow, columnId, value }) => {
          field.setValue(
            source.map((row) =>
              text(row.id) === editedRow.id
                ? {
                    ...row,
                    values: definitions.map((column, i) =>
                      text(column.key) === columnId
                        ? value
                        : array(row.values)[i],
                    ),
                  }
                : row,
            ),
          );
        }}
      />
      <Button
        disabled={streaming || field.value === undefined}
        onClick={() => trigger("Save Changes", formName)}
      >
        Save changes
      </Button>
    </div>
  );
}

"use client";
import * as React from "react";
import { isValid, parseISO } from "date-fns";
import { SingleDatePicker } from "./date-picker";
import { DateRangePicker } from "@/components/ui/date-range-picker/date-range-picker";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Checkbox } from "@/components/ui/checkbox";
import { Switch } from "@/components/ui/switch";
import { Slider } from "@/components/ui/slider";
import {
  Select,
  SelectTrigger,
  SelectValue,
  SelectContent,
  SelectItem,
} from "@/components/ui/select";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import {
  useStateField,
  useIsStreaming,
  useFormValidation,
  parseStructuredRules,
} from "../runtime/react";
import { array, nodeProps, record, text, type Props } from "./shared";
/**
 * True inside a Calculator, where results update as inputs change, so each
 * input checks its rules whenever its value changes rather than on submit.
 */
export const LiveValidationContext = React.createContext(false);

export const FieldLabelContext = React.createContext<{
  id: string;
  label: string;
  hintId?: string;
} | null>(null);
/**
 * A slider's thumbs. State holds [n], but a program may declare a bare number
 * ($amount = 300); with no usable value the thumb starts at min.
 */
function sliderValues(value: unknown, min: unknown): number[] {
  const values = (Array.isArray(value) ? value : [value])
    .map(Number)
    .filter(Number.isFinite);
  return values.length ? values : [Number(min) || 0];
}

export function GeneratedField({
  name,
  props,
  renderNode,
}: {
  name: string;
  props: Props;
  renderNode: (value: unknown) => React.ReactNode;
}) {
  const field = useStateField(text(props.name), props.value);
  const streaming = useIsStreaming();
  const validation = useFormValidation();
  const live = React.useContext(LiveValidationContext);
  const label = React.useContext(FieldLabelContext);
  const fallbackId = React.useId();
  const items = array(props.items).map(nodeProps);
  const defaults = React.useMemo(
    () =>
      props.defaultValue ??
      (name === "Slider"
        ? [props.min ?? 0]
        : name === "CheckBoxGroup" || name === "SwitchGroup"
          ? Object.fromEntries(
              array(props.items)
                .map(nodeProps)
                .map((item) => [text(item.name), item.defaultChecked === true]),
            )
          : name === "Chips" || name === "OptionCards"
            ? props.type === "multiple"
              ? []
              : ""
            : ""),
    [props.defaultValue, props.min, props.items, props.type, name],
  );
  const value = field.value ?? defaults;
  const rules = React.useMemo(
    () =>
      parseStructuredRules(
        props.rules as Parameters<typeof parseStructuredRules>[0],
      ),
    [props.rules],
  );
  React.useEffect(() => {
    if (!streaming && field.value === undefined && defaults !== "")
      field.setValue(defaults);
  }, [streaming, field, defaults]);
  React.useEffect(() => {
    if (streaming || !validation || !rules.length) return;
    validation.registerField(field.name, rules, () => value);
    return () => validation.unregisterField(field.name);
  }, [streaming, validation, rules, field.name, value]);
  // A value can arrive after the field first renders (a declared $variable
  // the store has not applied yet), so this runs on every change, not once.
  React.useEffect(() => {
    if (live && !streaming && validation && rules.length)
      validation.validateField(field.name, value, rules);
  }, [live, streaming, validation, rules, field.name, value]);
  const error = validation?.getFieldError(field.name);
  const id = label?.id ?? fallbackId;
  const common = {
    id,
    name: field.name,
    disabled: streaming,
    "aria-label": label?.label ?? text(props.label ?? props.name),
    "aria-describedby":
      [label?.hintId, error && `${id}-error`].filter(Boolean).join(" ") ||
      undefined,
    "aria-invalid": !!error,
  };
  const change = (next: unknown) => {
    field.setValue(next);
    if (rules.length) validation?.validateField(field.name, next, rules);
  };
  let control: React.ReactNode;
  switch (name) {
    case "Input":
      control = (
        <Input
          {...common}
          type={text(props.type) || "text"}
          placeholder={text(props.placeholder)}
          value={text(value)}
          onChange={(event) => change(event.target.value)}
        />
      );
      break;
    case "TextArea":
      control = (
        <Textarea
          {...common}
          rows={typeof props.rows === "number" ? props.rows : 3}
          placeholder={text(props.placeholder)}
          value={text(value)}
          onChange={(event) => change(event.target.value)}
        />
      );
      break;
    case "DatePicker": {
      const date = record(value);
      const parseDate = (value: unknown) => {
        if (!value) return undefined;
        const parsed = parseISO(text(value));
        return isValid(parsed) ? parsed : undefined;
      };
      control =
        props.mode === "range" ? (
          <DateRangePicker
            {...common}
            value={{ from: parseDate(date.from), to: parseDate(date.to) }}
            onValueChange={(range) =>
              change(
                range
                  ? {
                      from: range.from?.toISOString(),
                      to: range.to?.toISOString(),
                    }
                  : undefined,
              )
            }
          />
        ) : (
          <SingleDatePicker
            {...common}
            required={record(props.rules).required === true}
            value={text(value)}
            onValueChange={change}
          />
        );
      break;
    }
    case "Slider":
      control = (
        <Slider
          {...common}
          min={Number(props.min)}
          max={Number(props.max)}
          step={Number(props.step ?? 1)}
          value={sliderValues(value, props.min)}
          // A drag reports a bare number; store [n] like every other slider value.
          onValueChange={(next) => change(Array.isArray(next) ? next : [next])}
          getAriaLabel={() => common["aria-label"]}
          // Room for the value bubble, which sits above the thumb, below the label.
          className="mt-[var(--hui-space-8)]"
          showValue
        />
      );
      break;
    case "Select":
      control = (
        <Select value={text(value)} onValueChange={change} disabled={streaming}>
          <SelectTrigger {...common}>
            <SelectValue
              placeholder={text(props.placeholder) || "Select an option"}
            />
          </SelectTrigger>
          <SelectContent>
            {items.map((item) => (
              <SelectItem key={text(item.value)} value={text(item.value)}>
                {text(item.label)}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      );
      break;
    case "RadioGroup":
      control = (
        <RadioGroup {...common} value={text(value)} onValueChange={change}>
          {items.map((item, index) => (
            <label key={text(item.value)} className="flex items-center gap-3">
              <RadioGroupItem
                id={`${id}-${index}`}
                value={text(item.value)}
                aria-label={text(item.label)}
                aria-describedby={item.description ? `${id}-${index}-description` : undefined}
              />
              <span>
                {text(item.label)}
                {item.description ? (
                  <span id={`${id}-${index}-description`} className="block text-muted-foreground">
                    {text(item.description)}
                  </span>
                ) : null}
              </span>
            </label>
          ))}
        </RadioGroup>
      );
      break;
    case "CheckBoxGroup":
    case "SwitchGroup":
      control = (
        <fieldset
          id={id}
          disabled={streaming}
          aria-label={common["aria-label"]}
          aria-describedby={common["aria-describedby"]}
          aria-invalid={common["aria-invalid"]}
          className="grid gap-3"
        >
          {items.map((item, index) => {
            const Control = name === "SwitchGroup" ? Switch : Checkbox;
            return (
              <label key={text(item.name)} className="flex items-center gap-3">
                <Control
                  id={`${id}-${index}`}
                  disabled={streaming}
                  aria-label={text(item.label ?? item.name)}
                  aria-describedby={item.description ? `${id}-${index}-description` : undefined}
                  checked={record(value)[text(item.name)] === true}
                  onCheckedChange={(checked) =>
                    change({ ...record(value), [text(item.name)]: checked })
                  }
                />
                <span>
                  {text(item.label ?? item.name)}
                  {item.description ? (
                    <span id={`${id}-${index}-description`} className="block text-muted-foreground">
                      {text(item.description)}
                    </span>
                  ) : null}
                </span>
              </label>
            );
          })}
        </fieldset>
      );
      break;
    case "Chips":
    case "OptionCards": {
      const multiple = props.type === "multiple";
      const choices = items.map((item, index) => {
        const selected = multiple
          ? array(value).includes(item.value)
          : value === item.value;
        return (
          <label
            key={text(item.value)}
            className={
              "flex cursor-pointer items-center gap-2 rounded-md border p-3 " +
              (selected ? "bg-accent" : "")
            }
          >
            {multiple ? (
              <Checkbox
                id={`${id}-${index}`}
                aria-label={text(item.title ?? item.label)}
                aria-describedby={item.subtitle ? `${id}-${index}-description` : undefined}
                disabled={streaming || item.disabled === true}
                checked={selected}
                onCheckedChange={(checked) =>
                  change(
                    checked
                      ? [...array(value), item.value]
                      : array(value).filter((v) => v !== item.value),
                  )
                }
              />
            ) : (
              <RadioGroupItem
                id={`${id}-${index}`}
                value={text(item.value)}
                aria-label={text(item.title ?? item.label)}
                aria-describedby={item.subtitle ? `${id}-${index}-description` : undefined}
                disabled={streaming || item.disabled === true}
              />
            )}
            {renderNode(item.icon ?? item.topContent)}
            <span>
              {text(item.title ?? item.label)}
              {item.subtitle ? (
                <span id={`${id}-${index}-description`} className="block text-muted-foreground">
                  {text(item.subtitle)}
                </span>
              ) : null}
            </span>
          </label>
        );
      });
      control = multiple ? (
        <fieldset
          id={id}
          disabled={streaming}
          aria-label={common["aria-label"]}
          aria-describedby={common["aria-describedby"]}
          className="flex flex-wrap gap-3"
        >
          {choices}
        </fieldset>
      ) : (
        <RadioGroup
          {...common}
          value={text(value)}
          onValueChange={change}
          className="flex flex-wrap gap-3"
        >
          {choices}
        </RadioGroup>
      );
      break;
    }
    default:
      throw new Error(`Unsupported generated field: ${name}`);
  }
  return (
    <div className="grid gap-2">
      {control}
      {error && (
        <p id={`${id}-error`} role="alert" className="text-sm text-destructive">
          {error}
        </p>
      )}
    </div>
  );
}

