export function GeneratedComponent(
  input: GeneratedComponentProps,
): React.ReactNode {
  const { name, props: p, renderNode: render } = input;
  if (virtual.has(name)) return null;
  if (fields.has(name))
    return <GeneratedField name={name} props={p} renderNode={render} />;
  if (name.endsWith("Chart")) return <GeneratedChart name={name} props={p} />;
  switch (name) {
    case "Form":
      return <GeneratedForm {...input} />;
    case "FormControl":
      return <GeneratedFormControl {...input} />;
    case "Button":
    case "IconButton":
    case "FollowUpItem":
      return <GeneratedAction {...input} />;
    case "Modal":
      return <GeneratedModal {...input} />;
    case "EditableTable":
      return <GeneratedEditableTable props={p} />;
    case "Stack":
    case "Card": {
      const style: React.CSSProperties = {
        display: "flex",
        flexDirection: p.direction === "row" ? "row" : "column",
        flexWrap: p.wrap === true ? "wrap" : "nowrap",
        gap: gaps[text(p.gap)] ?? gaps.m,
        alignItems:
          (
            {
              start: "flex-start",
              end: "flex-end",
              center: "center",
              stretch: "stretch",
              baseline: "baseline",
            } as const
          )[text(p.align) as "start"] ?? "stretch",
        justifyContent:
          (
            {
              start: "flex-start",
              end: "flex-end",
              center: "center",
              between: "space-between",
              around: "space-around",
              evenly: "space-evenly",
            } as const
          )[text(p.justify) as "start"] ?? "flex-start",
        minWidth: 0,
        flex: 1,
      };
      const children = (
        <>
          {render(p.children)}
          {array(p.sources).length > 0 && (
            <ol aria-label="Sources" className="m-0 grid gap-2 p-0 text-sm">
              {array(p.sources).map((source, i) => {
                const item = record(source),
                  url = safeUrl(item.url);
                return (
                  <li key={i} className="list-inside">
                    {url ? (
                      <a
                        href={url}
                        rel="noreferrer"
                        target="_blank"
                        className="underline"
                      >
                        {text(item.title)} (opens in a new tab)
                      </a>
                    ) : (
                      text(item.title)
                    )}
                  </li>
                );
              })}
            </ol>
          )}
        </>
      );
      return name === "Card" && p.variant !== "clear" ? (
        <Card
          style={{ minWidth: 0, flex: 1 }}
          className={cn(flatCard, p.variant === "sunk" && "bg-muted")}
        >
          <CardContent style={style}>
            <InsideCardContext.Provider value>{children}</InsideCardContext.Provider>
          </CardContent>
        </Card>
      ) : (
        <div style={style}>{children}</div>
      );
    }
    case "CardHeader":
      return (
        // It renders inside the Card's content, which already has the inset.
        <CardHeader className="px-0">
          <CardTitle>{text(p.title)}</CardTitle>
          {!!p.subtitle && (
            <CardDescription>{text(p.subtitle)}</CardDescription>
          )}
        </CardHeader>
      );
    case "InlineHeader":
      return (
        <header className="grid gap-1">
          {/* data-slot opts out of the site's page-heading size for bare h2s. */}
          <h2 data-slot="inline-header-title" className="m-0 text-base font-semibold">{text(p.heading)}</h2>
          {!!p.description && (
            <p className="m-0 text-sm text-muted-foreground">
              {text(p.description)}
            </p>
          )}
        </header>
      );
    case "TextContent":
      return (
        <Markdown style={textColorStyle(p.color)}>{text(p.text)}</Markdown>
      );
    case "MarkDownRenderer":
      return <Markdown>{text(p.textMarkdown)}</Markdown>;
    case "CodeBlock":
      return <HighlightedCode language={text(p.language)} code={text(p.codeString)} />;
    case "Text":
    case "BoldText":
      return (
        <span className="grid gap-1">
          {name === "BoldText" ? (
            <strong style={textColorStyle(p.color)}>
              {text(p.value)}
            </strong>
          ) : (
            <span style={textColorStyle(p.color)}>{text(p.value)}</span>
          )}
          {!!p.subtext && (
            <small className="text-muted-foreground">{text(p.subtext)}</small>
          )}
        </span>
      );
    case "Callout":
    case "TextCallout":
      return p.visible === false ? null : (
        <Alert
          variant={
            p.variant === "error" || p.variant === "danger"
              ? "error"
              : "default"
          }
        >
          <AlertTitle>{text(p.title)}</AlertTitle>
          <AlertDescription>{text(p.description)}</AlertDescription>
        </Alert>
      );
    case "Label":
      return <Label>{text(p.text)}</Label>;
    case "Image":
    case "ImageBlock":
      return <Image src={p.src} alt={p.alt} />;
    case "ImageGallery":
      return (
        <div className="flex flex-wrap gap-3">
          {array(p.images).map((image, i) => {
            const item = record(image);
            return (
              <figure key={i} className="m-0">
                <Image src={item.src} alt={item.alt} />
                {!!item.details && (
                  <figcaption>{text(item.details)}</figcaption>
                )}
              </figure>
            );
          })}
        </div>
      );
    case "Icon": {
      const key = text(p.name)
        .split("-")
        .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
        .join("");
      const Icon = (
        Icons as unknown as Record<
          string,
          React.ComponentType<{ className?: string; "aria-hidden"?: boolean }>
        >
      )[key];
      return Icon ? <Icon className="size-5" aria-hidden /> : null;
    }
    case "IconText":
    case "ImageText":
    case "ImageTextLarge":
      return (
        <div className="flex items-center gap-3">
          {name === "IconText" ? (
            render(p.icon)
          ) : (
            <Image src={p.src} alt={p.alt} />
          )}
          <span className="grid gap-1">
            <strong>{text(p.title)}</strong>
            {!!p.subtitle && (
              <small className="text-muted-foreground">
                {text(p.subtitle)}
              </small>
            )}
          </span>
        </div>
      );
    case "Tag": {
      const tone = tones[text(p.variant)] ?? "neutral";
      return p.fill === "solid" ? (
        <Badge variant="neutral" className={solidTags[tone]}>
          {render(p.icon)}
          {text(p.text)}
        </Badge>
      ) : p.fill === "outline" ? (
        <Badge
          variant="outline"
          className={tone === "neutral" ? undefined : "border-current"}
          style={
            tone === "neutral" ? undefined : { color: toneTextColor(tone) }
          }
        >
          {render(p.icon)}
          {text(p.text)}
        </Badge>
      ) : (
        <Badge variant={tone}>
          {render(p.icon)}
          {text(p.text)}
        </Badge>
      );
    }
    case "TagBlock":
      return (
        <div className="flex flex-wrap gap-2">
          {array(p.tags).map((tag, i) => (
            <Badge key={i} variant="neutral">
              {text(tag)}
            </Badge>
          ))}
        </div>
      );
    case "Separator":
      return (
        <Separator
          orientation={p.orientation === "vertical" ? "vertical" : "horizontal"}
        />
      );
    case "Buttons":
      return (
        <div
          className={
            p.direction === "column" ? "grid gap-2" : "flex flex-wrap gap-2"
          }
        >
          {render(p.buttons)}
        </div>
      );
    case "Tabs": {
      const items = array(p.items).map(nodeProps);
      return (
        <Tabs defaultValue={text(items[0]?.value)}>
          <TabsList>
            {items.map((item, i) => (
              <TabsTrigger key={i} value={text(item.value)}>
                {text(item.trigger)}
              </TabsTrigger>
            ))}
          </TabsList>
          {items.map((item, i) => (
            <TabsContent
              key={i}
              value={text(item.value)}
              className="grid gap-4 pt-4"
            >
              {render(item.content)}
            </TabsContent>
          ))}
        </Tabs>
      );
    }
    case "SectionBlock":
      return <GeneratedSections {...input} />;
    case "Accordion": {
      const items = array(p.items).map(nodeProps);
      return (
        <Accordion>
          {items.map((item, i) => (
            <AccordionItem key={i} value={text(item.value) || String(i)}>
              <AccordionTrigger>{text(item.trigger)}</AccordionTrigger>
              <AccordionContent>{render(item.content)}</AccordionContent>
            </AccordionItem>
          ))}
        </Accordion>
      );
    }
    case "Carousel":
      return <GeneratedCarousel {...input} />;
    case "Table": {
      const columns = array(p.columns).map(nodeProps);
      const length = Math.max(
        0,
        ...columns.map((column) => array(column.data).length),
      );
      return (
        <RecordsTable
          label="Generated table"
          columns={columns.map((column, i) => ({
            id: String(i),
            header: text(column.label),
          }))}
          rows={Array.from({ length }, (_, index) => ({
            id: String(index),
            name: String(index + 1),
            cells: Object.fromEntries(
              columns.map((column, i) => {
                const value = array(column.data)[index];
                return [
                  String(i),
                  value && typeof value === "object"
                    ? render(value)
                    : text(value),
                ];
              }),
            ),
          }))}
        />
      );
    }
    case "EntityList":
      return (
        <dl className="m-0 grid gap-2">
          {[p.header, ...array(p.rows), p.footer]
            .filter(Boolean)
            .map((row, i) => {
              const item = record(row);
              return (
                <div
                  key={i}
                  className="flex justify-between gap-4 border-b pb-2"
                >
                  <dt>{text(item.left)}</dt>
                  <dd className="m-0 tabular-nums">{text(item.right)}</dd>
                </div>
              );
            })}
        </dl>
      );
    case "Map":
      return <GeneratedMap props={p} />;
    case "PartsDiagram":
      return <GeneratedPartsDiagram props={p} />;
    case "Quiz":
      return <GeneratedQuiz props={p} />;
    case "Calculator":
      return <GeneratedCalculator props={p} renderNode={render} />;
    case "Result":
      return <GeneratedResult props={p} />;
    case "Diagram":
      return <GeneratedDiagram props={p} />;
    case "Steps":
      return (
        <ol className="grid gap-4">
          {array(p.items).map((value, i) => {
            const item = nodeProps(value);
            return (
              <li key={i}>
                <strong>{text(item.title)}</strong>
                <p>{text(item.details)}</p>
              </li>
            );
          })}
        </ol>
      );
    case "ListBlock":
      return (
        <ol className="grid gap-3">
          {array(p.items).map((item, i) => (
            <li key={i}>{render(item)}</li>
          ))}
        </ol>
      );
    case "ListItem":
      return (
        <div className="grid gap-2">
          <strong>{text(p.title)}</strong>
          {!!p.subtitle && (
            <p className="m-0 text-muted-foreground">{text(p.subtitle)}</p>
          )}
          {!!p.image && (
            <Image src={record(p.image).src} alt={record(p.image).alt} />
          )}
          {!!p.action && (
            <GeneratedAction
              {...input}
              props={{ ...p, label: p.actionLabel ?? p.title }}
            />
          )}
        </div>
      );
    case "FollowUpBlock":
      return <div className="flex flex-wrap gap-2">{render(p.items)}</div>;
    case "MetricIndicatorInline":
    case "MetricIndicatorWithStrikethrough":
      return (
        <div className="flex flex-wrap items-baseline gap-2">
          <strong className="tabular-nums">{text(p.value)}</strong>
          {!!p.previousValue && (
            <del className="text-muted-foreground">{text(p.previousValue)}</del>
          )}
          {!!p.subtext && <small>{text(p.subtext)}</small>}
          {!!p.trend && (
            <span>
              {record(p.trend).direction === "up" ? "Increase" : "Decrease"}{" "}
              {text(record(p.trend).value)}
            </span>
          )}
        </div>
      );
    case "ContextCardBlock":
      return (
        <ContextCards
          title="Context"
          chunks={array(p.items).map((value, i) => {
            const item = nodeProps(value);
            return {
              id: text(item.id) || String(i),
              title:
                typeof item.title === "string"
                  ? item.title
                  : text(nodeProps(item.title).text),
              body: text(item.body),
            };
          })}
        />
      );
    case "SnippetCardBlock":
    case "OverviewCardBlock":
    case "CompositeCardBlock":
    case "VisualCardBlock":
      return (
        <div
          className={
            p.layout === "carousel"
              ? "flex gap-4 overflow-x-auto"
              : "grid gap-4 sm:grid-cols-2"
          }
        >
          {render(p.items)}
        </div>
      );
    case "SnippetCardItem":
    case "OverviewCardItem":
    case "CompositeCardItem":
    case "VisualCardItem":
    case "ContextCardItem":
      return (
        <Card className={flatCard}>
          <CardContent className="grid gap-3">
            <Image src={p.bgImageSrc} alt={p.bgImageAlt} />
            {render(p.lhs ?? p.top ?? p.header)}
            {render(p.rhs ?? p.bottom ?? p.body)}
            {!!p.title && <strong>{text(p.title)}</strong>}
            {render(p.tag)}
            {!!p.footer && (
              <footer className="flex items-center justify-between gap-3">
                {render(record(p.footer).price)}
                {render(record(p.footer).button)}
              </footer>
            )}
          </CardContent>
        </Card>
      );
    default:
      throw new Error(`No Honest renderer for ${name}`);
  }
}

"use client";
import * as React from "react";

const code =
  "mx-0.5 rounded-[var(--hui-radius-1)] border border-[var(--hui-color-border-base-primary)] bg-[var(--hui-color-background-base-primary)] px-[0.3rem] py-px font-mono text-[0.85em] text-[var(--prose-code-color,inherit)]";

// Emphasis follows Markdown's flanking rule: the inside of a delimiter never
// touches a space, and a single * never sits against a letter or another *.
// So **bold** and *italic* render, while code-like text such as `int **pp`,
// `*p = 20; *q` or `a * b * c` stays as typed.
const emphasis = /\*\*(?=\S)([^*]+?)(?<=\S)\*\*|(?<![*\w])\*(?=[^\s*])([^*]+?)(?<=[^\s*])\*(?![*\w])/g;

function Emphasis({ value }: { value: string }) {
  const parts: React.ReactNode[] = [];
  let last = 0;
  for (const match of value.matchAll(emphasis)) {
    if (match.index > last) parts.push(value.slice(last, match.index));
    parts.push(
      match[1] !== undefined ? (
        <strong key={match.index} className="font-semibold">
          {match[1]}
        </strong>
      ) : (
        <em key={match.index}>{match[2]}</em>
      ),
    );
    last = match.index + match[0].length;
  }
  if (last < value.length) parts.push(value.slice(last));
  return <>{parts}</>;
}

/**
 * Generated text with Markdown's inline code, bold and italic rendered. Code
 * spans are found first, so nothing inside them is read as emphasis. Other
 * Markdown, and an unpaired delimiter, stays as typed.
 */
export function InlineText({ value }: { value: string }) {
  return value.split(/(`[^`]+`)/).map((part, i) =>
    part.length > 2 && part.startsWith("`") && part.endsWith("`") ? (
      <code key={i} className={code}>
        {part.slice(1, -1)}
      </code>
    ) : (
      <Emphasis key={i} value={part} />
    ),
  );
}

"use client";
// Loaded only when a reply contains a map, so MapLibre's code and styles stay
// off every other page.
import * as React from "react";
import * as maplibregl from "maplibre-gl";
import "maplibre-gl/dist/maplibre-gl.css";
import { useTheme } from "next-themes";
import { cn } from "@/lib/utils";
import type { MapServices } from "./map";

type Point = { lat: number; lon: number; mark?: string };
type View = "satellite" | "map";
type Visibility = "visible" | "none";

// Close enough to show a town; a single place is never shown at street level.
const SINGLE_PLACE_ZOOM = 11;
// Near places, such as buildings on one campus, can be told apart at this zoom.
const MAX_FIT_ZOOM = 16;
const IMAGERY = "imagery";

/**
 * Adds the imagery just above the style's background. Changing the style drops
 * added layers, so this runs on every style load.
 */
function addImagery(instance: maplibregl.Map, imagery: NonNullable<MapServices["imagery"]>) {
  if (!instance.getSource(IMAGERY)) {
    instance.addSource(IMAGERY, {
      type: "raster",
      tiles: imagery.tiles,
      tileSize: 256,
      maxzoom: imagery.maxzoom,
      attribution: imagery.attribution,
    });
  }
  if (!instance.getLayer(IMAGERY)) {
    const aboveBackground = instance.getStyle().layers.find((layer) => layer.type !== "background")?.id;
    instance.addLayer({ id: IMAGERY, type: "raster", source: IMAGERY }, aboveBackground);
  }
}

/**
 * Satellite shows the imagery and the style's labels only: drawn buildings,
 * roads and land would hide the photo. Map restores each layer as the style
 * set it. Where the imagery has no tile, the background shows through.
 */
function applyView(instance: maplibregl.Map, satellite: boolean, original: Map<string, Visibility>) {
  for (const layer of instance.getStyle().layers) {
    if (layer.id === IMAGERY) {
      instance.setLayoutProperty(IMAGERY, "visibility", satellite ? "visible" : "none");
      continue;
    }
    if (layer.type === "symbol" || layer.type === "background") continue;
    if (!original.has(layer.id))
      original.set(layer.id, instance.getLayoutProperty(layer.id, "visibility") === "none" ? "none" : "visible");
    instance.setLayoutProperty(layer.id, "visibility", satellite ? "none" : original.get(layer.id));
  }
}

function markerElement(mark: string | undefined) {
  const element = document.createElement("div");
  // The list under the map names every place, so markers are not read twice.
  element.setAttribute("aria-hidden", "true");
  element.className = mark
    ? "flex size-7 items-center justify-center rounded-full border-2 border-white bg-[var(--hui-color-background-accent-emphasis)] text-xs font-semibold text-[var(--hui-color-foreground-accent-emphasis)] shadow-[var(--hui-shadow-soft)]"
    : "size-4 rounded-full border-2 border-white bg-[var(--hui-color-background-accent-emphasis)] shadow-[var(--hui-shadow-soft)]";
  element.textContent = mark ?? "";
  return element;
}

export default function MapCanvas({
  services,
  points,
  label,
  imageryCovers,
  onFail,
}: {
  services: MapServices;
  /** Whether the imagery has tiles at every place; without them, satellite would be blank. */
  imageryCovers: boolean;
  points: Point[];
  label: string;
  onFail: () => void;
}) {
  const container = React.useRef<HTMLDivElement>(null);
  const map = React.useRef<maplibregl.Map | null>(null);
  const { resolvedTheme } = useTheme();
  const imagery = imageryCovers ? services.imagery : undefined;
  // Satellite first when the app provides imagery; the reader can switch.
  const [view, setView] = React.useState<View>(imagery ? "satellite" : "map");
  const satellite = view === "satellite" && !!imagery;
  // Over imagery, the dark style's light labels with dark halos read best.
  const style = satellite || resolvedTheme === "dark" ? services.styles.dark : services.styles.light;
  const satelliteRef = React.useRef(satellite);
  const originalVisibility = React.useRef(new Map<string, Visibility>());
  React.useEffect(() => {
    satelliteRef.current = satellite;
  });
  const failRef = React.useRef(onFail);
  React.useEffect(() => {
    failRef.current = onFail;
  });

  // One map for the component's life; markers and style follow below.
  React.useEffect(() => {
    if (!container.current) return;
    maplibregl.setWorkerUrl(services.workerUrl);
    let instance: maplibregl.Map;
    try {
      instance = new maplibregl.Map({
        container: container.current,
        style,
        center: [0, 20],
        zoom: 1,
        attributionControl: { compact: true },
        // Scrolling the conversation should scroll it, not zoom the map.
        cooperativeGestures: true,
        fadeDuration: 0,
      });
    } catch {
      // WebGL is unavailable or failed to start.
      failRef.current();
      return;
    }
    instance.addControl(new maplibregl.NavigationControl({ showCompass: false }), "top-right");
    if (imagery)
      instance.on("style.load", () => {
        // A new style has its own layers, so their original visibility is read afresh.
        originalVisibility.current.clear();
        addImagery(instance, imagery);
        applyView(instance, satelliteRef.current, originalVisibility.current);
      });
    instance.on("error", (event: maplibregl.ErrorEvent) => {
      // A failed style or WebGL context leaves nothing to look at; a single
      // missing tile does not, so only those failures replace the map.
      const message = String(event.error?.message ?? "");
      if (!instance.isStyleLoaded() && /style|webgl|context/i.test(message)) failRef.current();
    });
    map.current = instance;
    return () => {
      instance.remove();
      map.current = null;
    };
    // The style is applied by the effect below; recreating the map would lose the view.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [services.workerUrl]);

  React.useEffect(() => {
    map.current?.setStyle(style);
  }, [style]);

  React.useEffect(() => {
    const instance = map.current;
    if (instance?.getLayer(IMAGERY)) applyView(instance, satellite, originalVisibility.current);
  }, [satellite]);

  const key = JSON.stringify(points);
  React.useEffect(() => {
    const instance = map.current;
    if (!instance) return;
    const list = JSON.parse(key) as Point[];
    const markers = list.map((point) =>
      new maplibregl.Marker({ element: markerElement(point.mark) })
        .setLngLat([point.lon, point.lat])
        .addTo(instance),
    );
    // No fly-in: the view jumps straight to the places.
    if (list.length === 1) {
      instance.jumpTo({ center: [list[0].lon, list[0].lat], zoom: SINGLE_PLACE_ZOOM });
    } else if (list.length > 1) {
      const bounds = new maplibregl.LngLatBounds();
      list.forEach((point) => bounds.extend([point.lon, point.lat]));
      // Room on the right for the zoom buttons and below for the attribution.
      instance.fitBounds(bounds, {
        padding: { top: 48, right: 72, bottom: 56, left: 48 },
        maxZoom: MAX_FIT_ZOOM,
        duration: 0,
      });
    }
    return () => markers.forEach((marker) => marker.remove());
  }, [key]);

  return (
    <div className="relative">
      {imagery && (
        <div
          role="group"
          aria-label="Map view"
          className="absolute top-2.5 left-2.5 z-10 flex gap-0.5 rounded-[var(--hui-radius-2)] border border-[var(--hui-color-border-base-primary)] bg-[var(--hui-color-background-base-primary)] p-0.5 shadow-[var(--hui-shadow-soft)]"
        >
          {(["satellite", "map"] as const).map((option) => (
            <button
              key={option}
              type="button"
              aria-pressed={view === option}
              onClick={() => setView(option)}
              className={cn(
                "rounded-[var(--hui-radius-1)] px-2.5 py-1 text-xs font-medium outline-none focus-visible:[outline:var(--hui-focus-ring)]",
                view === option
                  ? "bg-[var(--hui-color-background-neutral-secondary)] text-[var(--hui-color-foreground-base-primary)]"
                  : "text-[var(--hui-color-foreground-base-secondary)] hover:text-[var(--hui-color-foreground-base-primary)]",
              )}
            >
              {option === "satellite" ? imagery.label : "Map"}
            </button>
          ))}
        </div>
      )}
      <div
        ref={container}
        role="region"
        aria-label={label}
        className="aspect-[4/3] max-h-96 w-full bg-[var(--hui-color-background-base-secondary)] sm:aspect-[16/9]"
      />
    </div>
  );
}

"use client";
import * as React from "react";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import { useIsStreaming } from "../runtime/react";
import { InsideCardContext, array, nodeProps, text, type Props } from "./shared";

export type GeocodedPlace = { lat: number; lon: number; label: string };

/**
 * What a host app provides for generated maps. The model only names places;
 * `geocode` finds them, so coordinates always come from a lookup service the
 * app chose. Without these services, a Map shows its places as a list.
 */
export type MapServices = {
  /** Resolves to the best match, or null when there is none. Rejects on failure. */
  geocode: (query: string, signal: AbortSignal) => Promise<GeocodedPlace | null>;
  /** MapLibre's worker, served by the app (see scripts/copy-maplibre-worker.mjs). */
  workerUrl: string;
  /** MapLibre style URLs for each theme. */
  styles: { light: string; dark: string };
  /** Credit for the place data, shown under the list. */
  placeAttribution: React.ReactNode;
  /**
   * Aerial or satellite tiles. When present, maps open on this view and the
   * reader can switch to the drawn map. Where it has no tile, the map shows.
   */
  imagery?: {
    /** Raster tile URLs with {z}, {x} and {y}. */
    tiles: string[];
    /** The highest zoom with tiles; MapLibre enlarges past it. */
    maxzoom: number;
    /** Credit shown in the map's attribution, as HTML. */
    attribution: string;
    /** The toggle's name for this view, such as "Satellite". */
    label: string;
  };
};

export const MapServicesContext = React.createContext<MapServices | null>(null);

const MapCanvas = React.lazy(() => import("./map-canvas"));

// Coarse enough that one tile covers a place's surroundings.
const COVERAGE_ZOOM = 12;

/** The imagery tile that contains a place, at the coverage zoom. */
function tileUrl(template: string, lat: number, lon: number) {
  const n = 2 ** COVERAGE_ZOOM;
  const x = Math.floor(((lon + 180) / 360) * n);
  const radians = (lat * Math.PI) / 180;
  const y = Math.floor(((1 - Math.log(Math.tan(radians) + 1 / Math.cos(radians)) / Math.PI) / 2) * n);
  return template
    .replace("{z}", String(COVERAGE_ZOOM))
    .replace("{x}", String(x))
    .replace("{y}", String(y));
}

/**
 * Whether the imagery has a tile at every place, found by asking for one tile
 * each. Imagery such as US aerial photography stops at a border that no simple
 * box describes, so this asks rather than guesses. Undefined while checking.
 */
function useImageryCoverage(imagery: MapServices["imagery"], places: GeocodedPlace[]) {
  const key = JSON.stringify(places.map(({ lat, lon }) => [lat, lon]));
  const [coverage, setCoverage] = React.useState<{ key: string; covers: boolean }>();
  React.useEffect(() => {
    if (!imagery || key === "[]") return;
    const controller = new AbortController();
    const points = JSON.parse(key) as [number, number][];
    Promise.all(
      points.map(([lat, lon]) =>
        fetch(tileUrl(imagery.tiles[0], lat, lon), { signal: controller.signal }).then(
          (response) => response.ok,
          () => false,
        ),
      ),
    ).then((found) => {
      if (!controller.signal.aborted) setCoverage({ key, covers: found.every(Boolean) });
    });
    return () => controller.abort();
  }, [imagery, key]);
  if (!imagery) return false;
  return coverage?.key === key ? coverage.covers : undefined;
}

type PlaceInput = { name: string; query: string; note: string };
type Lookup =
  | { status: "pending" }
  | { status: "found"; place: GeocodedPlace }
  | { status: "missing" }
  | { status: "failed"; message: string };

function readPlaces(value: unknown): PlaceInput[] {
  return array(value)
    .map(nodeProps)
    .filter((place) => text(place.name))
    .map((place) => ({
      name: text(place.name),
      query: text(place.query) || text(place.name),
      note: text(place.note),
    }));
}

/** Looks every place up once the reply is complete, and again on retry. */
function useLookups(places: PlaceInput[], services: MapServices | null, ready: boolean) {
  const queries = places.map((place) => place.query);
  const key = JSON.stringify(queries);
  const [attempt, setAttempt] = React.useState(0);
  const [lookups, setLookups] = React.useState<{ key: string; results: Lookup[] }>({
    key: "",
    results: [],
  });

  React.useEffect(() => {
    if (!services || !ready) return;
    const controller = new AbortController();
    const list = JSON.parse(key) as string[];
    // Every lookup resolves on its own, so places appear as they are found.
    list.forEach((query, index) => {
      services
        .geocode(query, controller.signal)
        .then(
          (place): Lookup => (place ? { status: "found", place } : { status: "missing" }),
          (error: unknown): Lookup => ({
            status: "failed",
            message: error instanceof Error ? error.message : "The place lookup failed.",
          }),
        )
        .then((result) => {
          if (controller.signal.aborted) return;
          setLookups((previous) => {
            const results =
              previous.key === `${key}#${attempt}`
                ? [...previous.results]
                : list.map((): Lookup => ({ status: "pending" }));
            results[index] = result;
            return { key: `${key}#${attempt}`, results };
          });
        });
    });
    return () => controller.abort();
  }, [key, services, ready, attempt]);

  const current = lookups.key === `${key}#${attempt}` ? lookups.results : [];
  const results = queries.map((_, index): Lookup => current[index] ?? { status: "pending" });
  return { results, retry: () => setAttempt((value) => value + 1) };
}

export function GeneratedMap({ props }: { props: Props }) {
  const services = React.useContext(MapServicesContext);
  // In a Card, the Card is the frame: the map becomes a rounded image and the
  // list lines up with the Card's content.
  const inCard = React.useContext(InsideCardContext);
  const streaming = useIsStreaming();
  const places = readPlaces(props.places);
  const numbered = props.kind === "route";
  const caption = text(props.caption);
  const { results, retry } = useLookups(places, services, !streaming);
  const [canvasFailed, setCanvasFailed] = React.useState(false);

  const found = results.flatMap((result, index) =>
    result.status === "found" ? [{ ...result.place, index }] : [],
  );
  const imageryCovers = useImageryCoverage(services?.imagery, found);

  if (places.length === 0) return null;

  const failure = results.find(
    (result): result is Extract<Lookup, { status: "failed" }> => result.status === "failed",
  );
  const pending = results.some((result) => result.status === "pending");
  const notice = !services
    ? "Maps aren't set up in this app, so the places are listed instead."
    : streaming
      ? "The map appears when the reply is complete."
      : canvasFailed
        ? "The map couldn't load in this browser. The places are listed below."
        : !pending && found.length === 0 && !failure
          ? "None of these places could be found, so there is nothing to map."
          : undefined;

  const List = numbered ? "ol" : "ul";
  return (
    <figure className="m-0 grid gap-3">
      <div
        data-frame={inCard ? undefined : ""}
        className={cn(
          inCard
            ? "grid gap-3"
            : "overflow-hidden rounded-[var(--hui-radius-2)] border border-[var(--hui-color-border-base-primary)]",
        )}
      >
        <div
          className={cn(
            "empty:hidden",
            inCard
              ? "overflow-hidden rounded-[var(--hui-radius-2)] border border-[var(--hui-color-border-base-primary)]"
              : "border-b border-[var(--hui-color-border-base-primary)]",
          )}
        >
        {services && !streaming && !canvasFailed && found.length > 0 && imageryCovers === undefined && (
          <MapPlaceholder text="Loading the map…" />
        )}
        {services && !streaming && !canvasFailed && found.length > 0 && imageryCovers !== undefined && (
          <React.Suspense fallback={<MapPlaceholder text="Loading the map…" />}>
            <MapCanvas
              services={services}
              imageryCovers={imageryCovers}
              points={found.map(({ lat, lon, index }) => ({
                lat,
                lon,
                mark: numbered ? String(index + 1) : undefined,
              }))}
              label={`Map of ${found.length} ${found.length === 1 ? "place" : "places"}. The same places are listed below.`}
              onFail={() => setCanvasFailed(true)}
            />
          </React.Suspense>
        )}
        {services && !streaming && !canvasFailed && found.length === 0 && pending && (
          <MapPlaceholder text="Finding places…" />
        )}
        </div>
        {notice && (
          <p
            className={cn(
              "m-0 bg-[var(--hui-color-background-base-secondary)] text-sm text-muted-foreground",
              inCard
                ? "rounded-[var(--hui-radius-2)] px-3 py-2"
                : "border-b border-[var(--hui-color-border-base-primary)] px-5 py-3",
            )}
          >
            {notice}
          </p>
        )}
        {failure && (
          <div
            role="alert"
            className={cn(
              "flex flex-wrap items-center justify-between gap-3 text-sm",
              !inCard && "border-b border-[var(--hui-color-border-base-primary)] px-5 py-3",
            )}
          >
            <span>{`Some places couldn't be looked up. ${failure.message}`}</span>
            <Button variant="secondary" size="sm" onClick={retry}>
              Try again
            </Button>
          </div>
        )}
        <List className={cn("m-0 grid list-none gap-3", inCard ? "p-0" : "p-5")}>
          {places.map((place, index) => {
            const result = results[index];
            return (
              <li key={index} className="flex gap-3">
                <span
                  aria-hidden="true"
                  className={
                    numbered
                      ? "mt-0.5 flex size-6 shrink-0 items-center justify-center rounded-full bg-[var(--hui-color-background-accent-emphasis)] text-xs font-semibold text-[var(--hui-color-foreground-accent-emphasis)]"
                      : "mt-1.5 size-3 shrink-0 rounded-full bg-[var(--hui-color-background-accent-emphasis)]"
                  }
                >
                  {numbered ? index + 1 : ""}
                </span>
                <span className="grid min-w-0 gap-0.5">
                  <span className="font-medium">{place.name}</span>
                  {!!place.note && <span className="text-sm">{place.note}</span>}
                  <span className="text-xs text-muted-foreground [overflow-wrap:anywhere]">
                    {!services || streaming
                      ? null
                      : result.status === "found"
                        ? `Matched: ${result.place.label}`
                        : result.status === "missing"
                          ? "Not found, so it isn't on the map."
                          : result.status === "failed"
                            ? "Couldn't be looked up."
                            : "Finding…"}
                  </span>
                </span>
              </li>
            );
          })}
        </List>
        {services && (
          <p
            className={cn(
              "m-0 border-t border-[var(--hui-color-border-base-primary)] text-xs text-muted-foreground",
              inCard ? "pt-2" : "px-5 py-2",
            )}
          >
            {services.placeAttribution}
          </p>
        )}
      </div>
      {!!caption && <figcaption className="text-sm text-muted-foreground">{caption}</figcaption>}
    </figure>
  );
}

function MapPlaceholder({ text: message }: { text: string }) {
  return (
    <div className="flex aspect-[4/3] max-h-96 w-full items-center justify-center bg-[var(--hui-color-background-base-secondary)] text-sm text-muted-foreground sm:aspect-[16/9]">
      {message}
    </div>
  );
}

"use client";
import * as React from "react";
import { InlineText } from "./inline-text";
import { array, nodeProps, text, type Props } from "./shared";

type Part = { label: string; value: string; detail: string; size: number };

type Arrangement = "row" | "stack" | "nested";

// Past this many parts a single bar is too cramped to read, so the row is
// drawn as lines instead. Every part is always shown.
const MAX_BAR_PARTS = 8;

function readParts(value: unknown): Part[] {
  const parts: Part[] = [];
  // While a reply streams, later parts may not have arrived yet.
  for (const item of array(value)) {
    const part = nodeProps(item);
    if (!text(part.label)) break;
    const size = Number(part.size);
    parts.push({
      label: text(part.label),
      value: text(part.value),
      detail: text(part.detail),
      size: Number.isFinite(size) && size > 0 ? size : 1,
    });
  }
  return parts;
}

const surface =
  "border border-[var(--hui-color-border-base-primary)] bg-[var(--hui-color-background-base-secondary)]";

function Value({ value, className }: { value: string; className?: string }) {
  return (
    <span className={`font-mono font-medium [overflow-wrap:anywhere] ${className ?? ""}`}>
      {value}
    </span>
  );
}

/**
 * Parts side by side, as one bar with each label under its segment. Narrow, or
 * with many parts, each part becomes a line: its value beside its label.
 */
function RowParts({ parts }: { parts: Part[] }) {
  const asBar = parts.length <= MAX_BAR_PARTS;
  const columns = parts.map((part) => `minmax(0, ${part.size}fr)`).join(" ");
  return (
    <ol
      data-layout={asBar ? "bar" : "lines"}
      // As lines, a shared value column lines every label up; as a bar, each
      // part takes its share of the width.
      className="group/row m-0 grid list-none grid-cols-[auto_minmax(0,1fr)] gap-x-3 gap-y-3 p-0 @2xl:data-[layout=bar]:grid-cols-[var(--parts-columns)] @2xl:data-[layout=bar]:gap-0"
      style={{ "--parts-columns": columns } as React.CSSProperties}
    >
      {parts.map((part, i) => (
        <li key={i} className="group/part col-span-2 grid min-w-0 grid-cols-subgrid items-start @2xl:group-data-[layout=bar]/row:col-span-1 @2xl:group-data-[layout=bar]/row:flex @2xl:group-data-[layout=bar]/row:flex-col @2xl:group-data-[layout=bar]/row:gap-2">
          <span
            className={`${surface} flex min-h-9 shrink-0 items-center justify-start @2xl:group-data-[layout=bar]/row:justify-center rounded-[var(--hui-radius-2)] px-3 py-1.5 text-sm @2xl:group-data-[layout=bar]/row:min-h-14 @2xl:group-data-[layout=bar]/row:w-full @2xl:group-data-[layout=bar]/row:rounded-none @2xl:group-data-[layout=bar]/row:border-l-0 @2xl:group-data-[layout=bar]/row:px-2 @2xl:group-data-[layout=bar]/row:group-first/part:rounded-l-[var(--hui-radius-2)] @2xl:group-data-[layout=bar]/row:group-first/part:border-l @2xl:group-data-[layout=bar]/row:group-last/part:rounded-r-[var(--hui-radius-2)]`}
          >
            <Value value={part.value || part.label} />
          </span>
          <span className="grid min-w-0 gap-0.5 pt-1.5 @2xl:group-data-[layout=bar]/row:pt-0 @2xl:group-data-[layout=bar]/row:pr-3">
            {/* The accent tick ties a label to the segment above it. */}
            <span
              aria-hidden="true"
              className="mb-1 hidden h-0.5 w-6 rounded-full bg-[var(--hui-color-foreground-accent-primary)] @2xl:group-data-[layout=bar]/row:block"
            />
            {!!part.value && (
              <span className="text-sm font-medium">
                <InlineText value={part.label} />
              </span>
            )}
            {!!part.detail && (
              <span className="text-sm text-muted-foreground">
                <InlineText value={part.detail} />
              </span>
            )}
          </span>
        </li>
      ))}
    </ol>
  );
}

/** Layers, top first, as one column of bands. */
function StackParts({ parts }: { parts: Part[] }) {
  return (
    <ol className="m-0 list-none p-0">
      {parts.map((part, i) => (
        <li
          key={i}
          className="grid gap-1 border border-t-0 border-[var(--hui-color-border-base-primary)] px-4 py-3 first:rounded-t-[var(--hui-radius-2)] first:border-t last:rounded-b-[var(--hui-radius-2)] even:bg-[var(--hui-color-background-base-secondary)] @xl:grid-cols-[minmax(0,14rem)_minmax(0,1fr)] @xl:items-baseline @xl:gap-4"
        >
          <span className="flex min-w-0 flex-wrap items-baseline gap-x-2">
            <span className="font-medium">
              <InlineText value={part.label} />
            </span>
            {!!part.value && <Value value={part.value} className="text-sm" />}
          </span>
          {!!part.detail && (
            <span className="text-sm text-muted-foreground">
              <InlineText value={part.detail} />
            </span>
          )}
        </li>
      ))}
    </ol>
  );
}

/**
 * Each part inside the one before. Real nested lists carry the containment to
 * screen readers; each inner list is named for the part that holds it.
 */
function NestedParts({ parts, depth = 0 }: { parts: Part[]; depth?: number }) {
  const part = parts[depth];
  const inner = depth + 1 < parts.length;
  return (
    <li
      className={`grid gap-3 rounded-[var(--hui-radius-2)] border border-[var(--hui-color-border-base-primary)] p-3 @md:p-4 ${
        depth % 2 === 0
          ? "bg-[var(--hui-color-background-base-secondary)]"
          : "bg-[var(--hui-color-background-base-primary)]"
      }`}
    >
      <span className={`grid gap-0.5 ${inner ? "" : "justify-items-center py-3 text-center"}`}>
        <span className="flex flex-wrap items-baseline gap-x-2 text-sm">
          <span className="font-medium">
            <InlineText value={part.label} />
          </span>
          {!!part.value && inner && <Value value={part.value} />}
        </span>
        {!!part.value && !inner && <Value value={part.value} className="text-xl" />}
        {!!part.detail && (
          <span className="text-sm text-muted-foreground">
            <InlineText value={part.detail} />
          </span>
        )}
      </span>
      {inner && (
        <ul className="m-0 list-none p-0" aria-label={`Inside ${part.label.replaceAll("`", "")}`}>
          <NestedParts parts={parts} depth={depth + 1} />
        </ul>
      )}
    </li>
  );
}

export function GeneratedPartsDiagram({ props }: { props: Props }) {
  const arrangement: Arrangement =
    props.arrangement === "stack" || props.arrangement === "nested" ? props.arrangement : "row";
  const parts = readParts(props.parts);
  if (parts.length === 0) return null;
  const caption = text(props.caption);
  return (
    <figure className="@container m-0 grid gap-3">
      {arrangement === "row" && <RowParts parts={parts} />}
      {arrangement === "stack" && <StackParts parts={parts} />}
      {arrangement === "nested" && (
        <ul className="m-0 list-none p-0">
          <NestedParts parts={parts} />
        </ul>
      )}
      {!!caption && (
        <figcaption className="text-sm text-muted-foreground">
          <InlineText value={caption} />
        </figcaption>
      )}
    </figure>
  );
}

"use client";
import * as React from "react";
import { Check as CheckIcon, X as XIcon } from "honestui/icons";
import { Button } from "@/components/ui/button";
import { Radio, RadioGroup } from "@/components/ui/radio-group";
import { cn } from "@/lib/utils";
import { useIsStreaming, useTriggerAction } from "../runtime/react";
import { InlineText } from "./inline-text";
import { InsideCardContext, array, nodeProps, text, type Props } from "./shared";

type Question = {
  question: string;
  options: string[];
  answer: string;
  explanation: string;
  /** False when the answer is not one of the options, so it cannot be marked. */
  gradable: boolean;
};

function readQuestions(value: unknown): Question[] {
  // While a reply streams, a question may arrive before its options.
  return array(value)
    .map(nodeProps)
    .filter((item) => text(item.question))
    .map((item) => {
      const options = array(item.options).map(text).filter(Boolean);
      const answer = text(item.answer);
      return {
        question: text(item.question),
        options,
        answer,
        explanation: text(item.explanation),
        gradable: options.includes(answer),
      };
    });
}

/** The quiz's own frame, or none inside a Card, whose edge and padding take over. */
function frameClasses(inCard: boolean) {
  return {
    frame: inCard
      ? ""
      : "overflow-hidden rounded-[var(--hui-radius-2)] border border-[var(--hui-color-border-base-primary)]",
    pad: inCard ? "" : "px-5",
    footer: cn(
      "flex flex-wrap items-center justify-between gap-3 border-t border-[var(--hui-color-border-base-primary)]",
      inCard ? "pt-3" : "bg-[var(--hui-color-background-base-secondary)] px-5 py-3",
    ),
  };
}

/**
 * Questions with known answers, one at a time. Answers can change until the
 * reader submits; only then are they marked, scored and explained. The answer
 * key comes from the reply itself, and the reader's choices stay on the page
 * unless they ask the assistant to explain what they missed.
 */
export function GeneratedQuiz({ props }: { props: Props }) {
  const streaming = useIsStreaming();
  const trigger = useTriggerAction();
  const questions = readQuestions(props.questions);
  const [chosen, setChosen] = React.useState<Record<number, string>>({});
  const [step, setStep] = React.useState(0);
  const [submitted, setSubmitted] = React.useState(false);
  const [needsAnswer, setNeedsAnswer] = React.useState(false);
  const focusPending = React.useRef(false);
  const heading = React.useRef<HTMLHeadingElement>(null);
  const hintId = React.useId();
  const { frame, pad, footer } = frameClasses(React.useContext(InsideCardContext));

  // After a step or a submit, the new heading takes focus, so a screen reader
  // announces where the reader now is.
  React.useEffect(() => {
    if (!focusPending.current) return;
    focusPending.current = false;
    heading.current?.focus();
  });

  if (questions.length === 0) return null;

  const current = Math.min(step, questions.length - 1);
  const isLast = current === questions.length - 1;
  const scored = questions.filter((item) => item.gradable);
  const correct = questions.filter((item, i) => item.gradable && chosen[i] === item.answer).length;
  const missed = questions
    .map((item, i) => ({ item, choice: chosen[i] }))
    .filter(({ item, choice }) => item.gradable && choice !== item.answer);

  const goTo = (next: number) => {
    setNeedsAnswer(false);
    setStep(next);
    focusPending.current = true;
  };
  const forward = () => {
    if (chosen[current] === undefined) {
      setNeedsAnswer(true);
      return;
    }
    if (isLast) {
      setSubmitted(true);
      focusPending.current = true;
    } else goTo(current + 1);
  };
  const tryAgain = () => {
    setChosen({});
    setSubmitted(false);
    goTo(0);
  };
  const explainMissed = () =>
    trigger("Explain the quiz questions I missed", undefined, {
      steps: [
        {
          type: "continue_conversation",
          message: "Explain the quiz questions I missed",
          context: missed.map(({ item, choice }) => ({
            question: item.question,
            chosen: choice,
            answer: item.answer,
          })),
        },
      ],
    });

  if (submitted) {
    return (
      <div data-frame={frame ? "" : undefined} className={frame}>
        <div className={cn("grid gap-1 border-b border-[var(--hui-color-border-base-primary)] pb-4", pad, !!pad && "pt-4")}>
          {/* data-slot opts out of the site's page-heading size for bare h2s. */}
          <h2 ref={heading} tabIndex={-1} data-slot="quiz-score" className="m-0 text-2xl font-semibold tracking-tight outline-none">
            {scored.length > 0 ? `${correct} of ${scored.length} correct` : "Answers submitted"}
          </h2>
          <p className="m-0 text-sm text-muted-foreground">
            {scored.length > 0 && missed.length === 0
              ? "You got every question right."
              : "Review each answer below."}
          </p>
        </div>
        <ol className={cn("m-0 grid list-none gap-7 py-5", pad)}>
          {questions.map((item, i) => (
            <li key={i}>
              <QuestionView
                number={i + 1}
                total={questions.length}
                question={item}
                choice={chosen[i]}
                reviewing
              />
            </li>
          ))}
        </ol>
        <div className={cn(footer, "justify-end")}>
          {missed.length > 0 && (
            <Button variant="secondary" size="sm" onClick={explainMissed}>
              Explain what I missed
            </Button>
          )}
          <Button variant="ghost" size="sm" onClick={tryAgain}>
            Try again
          </Button>
        </div>
      </div>
    );
  }

  const answered = questions.filter((_, i) => chosen[i] !== undefined).length;
  return (
    <div data-frame={frame ? "" : undefined} className={frame}>
      <div className={cn("grid gap-2", pad, !!pad && "pt-4")}>
        <p className="m-0 text-sm text-muted-foreground" aria-hidden="true">
          Question {current + 1} of {questions.length}
        </p>
        <div
          role="progressbar"
          aria-label="Questions answered"
          aria-valuemin={0}
          aria-valuemax={questions.length}
          aria-valuenow={answered}
          className="h-1 overflow-hidden rounded-full bg-[var(--hui-color-background-neutral-secondary)]"
        >
          <div
            className="h-full rounded-full bg-[var(--hui-color-background-accent-emphasis)] motion-safe:transition-[width] motion-safe:duration-200"
            style={{ width: `${(answered / questions.length) * 100}%` }}
          />
        </div>
      </div>
      <div className={cn("py-5", pad)}>
        <QuestionView
          key={current}
          number={current + 1}
          total={questions.length}
          question={questions[current]}
          choice={chosen[current]}
          headingRef={heading}
          disabled={streaming}
          describedBy={needsAnswer ? hintId : undefined}
          onChoose={(choice) => {
            setNeedsAnswer(false);
            setChosen((previous) => ({ ...previous, [current]: choice }));
          }}
        />
      </div>
      <div className={footer}>
        <p id={hintId} className="m-0 text-sm" aria-live="polite">
          {needsAnswer ? (isLast ? "Choose an answer to submit." : "Choose an answer to continue.") : ""}
        </p>
        <div className="flex flex-wrap gap-2">
          {current > 0 && (
            <Button variant="ghost" size="sm" onClick={() => goTo(current - 1)}>
              Back
            </Button>
          )}
          {/* The last questions may still be arriving. */}
          <Button size="sm" onClick={forward} disabled={streaming && isLast}>
            {isLast ? "Submit answers" : "Next"}
          </Button>
        </div>
      </div>
    </div>
  );
}

function QuestionView({
  number,
  total,
  question,
  choice,
  reviewing = false,
  disabled = false,
  headingRef,
  describedBy,
  onChoose,
}: {
  number: number;
  total: number;
  question: Question;
  choice: string | undefined;
  /** After submitting: answers are marked and locked. */
  reviewing?: boolean;
  disabled?: boolean;
  headingRef?: React.Ref<HTMLHeadingElement>;
  describedBy?: string;
  onChoose?: (choice: string) => void;
}) {
  const id = React.useId();
  const isRight = question.gradable && choice === question.answer;

  return (
    <div className="grid gap-3">
      <h2
        ref={headingRef}
        id={`${id}-question`}
        data-slot="quiz-question"
        tabIndex={headingRef ? -1 : undefined}
        className="m-0 text-base font-medium outline-none"
      >
        <span className="sr-only">{`Question ${number} of ${total}: `}</span>
        {reviewing && <span aria-hidden="true">{number}. </span>}
        <InlineText value={question.question} />
      </h2>
      <RadioGroup
        aria-labelledby={`${id}-question`}
        aria-describedby={reviewing ? `${id}-feedback` : describedBy}
        value={choice ?? ""}
        onValueChange={(value) => {
          if (!reviewing) onChoose?.(String(value));
        }}
        // In review the answers are locked but still focusable and read out.
        // Base UI's readOnly puts aria-readonly on each radio, where ARIA does
        // not allow it, so the group carries it and changes are ignored above.
        aria-readonly={reviewing || undefined}
        disabled={disabled}
        className="gap-2"
      >
        {question.options.map((option, j) => {
          const isAnswer = reviewing && question.gradable && option === question.answer;
          const isWrongChoice = reviewing && question.gradable && option === choice && !isAnswer;
          return (
            <label
              key={j}
              className={cn(
                "flex items-center gap-3 rounded-[var(--hui-radius-2)] border border-[var(--hui-color-border-base-primary)] px-3 py-2.5",
                !reviewing && "cursor-pointer hover:bg-[var(--hui-color-background-base-secondary)]",
                reviewing && !isAnswer && !isWrongChoice && "text-muted-foreground",
                isAnswer &&
                  "border-[var(--hui-color-foreground-success-primary)] bg-[var(--hui-color-background-success-primary)]",
                isWrongChoice &&
                  "border-[var(--hui-color-border-danger-primary)] bg-[var(--hui-color-background-danger-primary)]",
              )}
            >
              <Radio
                value={option}
                // The radio is a span, which the wrapping label does not name.
                aria-labelledby={`${id}-option-${j}`}
                aria-describedby={isAnswer || isWrongChoice ? `${id}-mark-${j}` : undefined}
                className={cn(reviewing && "cursor-default")}
              />
              <span id={`${id}-option-${j}`} className="min-w-0 flex-1">
                <InlineText value={option} />
              </span>
              {isAnswer && (
                <span id={`${id}-mark-${j}`} className="flex shrink-0 items-center gap-1 text-sm font-medium">
                  <CheckIcon aria-hidden="true" className="size-4" />
                  {choice === option ? "Your answer" : "Answer"}
                </span>
              )}
              {isWrongChoice && (
                <span id={`${id}-mark-${j}`} className="flex shrink-0 items-center gap-1 text-sm font-medium">
                  <XIcon aria-hidden="true" className="size-4" />
                  Your answer
                </span>
              )}
            </label>
          );
        })}
      </RadioGroup>
      {reviewing && (
        <p id={`${id}-feedback`} className="m-0 text-sm">
          {!question.gradable ? (
            "This question has no answer key, so it isn't scored."
          ) : (
            <>
              <strong className="font-semibold">
                {isRight ? (
                  "Correct."
                ) : (
                  <>
                    Not quite. The answer is <InlineText value={question.answer} />.
                  </>
                )}
              </strong>
              {question.explanation && (
                <>
                  {" "}
                  <InlineText value={question.explanation} />
                </>
              )}
            </>
          )}
        </p>
      )}
    </div>
  );
}

import * as React from "react";

export type Props = Record<string, unknown>;
export function record(value: unknown): Props {
  return value && typeof value === "object" && !Array.isArray(value)
    ? (value as Props)
    : {};
}
export function array(value: unknown): unknown[] {
  return Array.isArray(value) ? value : [];
}
export function nodeProps(value: unknown): Props {
  const item = record(value);
  return record(item.props ?? item);
}
export function text(value: unknown): string {
  return value == null ? "" : String(value);
}
/** Model-generated URLs are never used as script or data URLs. */
export function safeUrl(value: unknown): string | undefined {
  if (typeof value !== "string") return;
  try {
    const url = new URL(value);
    if (url.protocol === "https:" || url.protocol === "http:") return url.href;
  } catch {
    /* Invalid model output has no link. */
  }
}

export type NumberFormat = "number" | "currency" | "percent";

/**
 * A number in the viewer's locale, or undefined when it is not a finite number.
 * Percent takes the percentage itself (5 → 5%). Currency shows cents below
 * 1,000 when the amount has them ($411.50) and drops them above, where they are
 * false precision in an estimate ($46,585); pass decimals to choose.
 */
export function formatNumber(
  value: unknown,
  format: NumberFormat = "number",
  decimals?: number,
  currency = "USD",
): string | undefined {
  if (value == null || value === "") return;
  const number = Number(value);
  if (!Number.isFinite(number)) return;
  const fractionDigits =
    decimals ??
    (format === "currency"
      ? Number.isInteger(number) || Math.abs(number) >= 1000
        ? 0
        : 2
      : undefined);
  const options: Intl.NumberFormatOptions = {
    style: format === "number" ? "decimal" : format,
    minimumFractionDigits: fractionDigits ?? 0,
    maximumFractionDigits: fractionDigits ?? (format === "percent" ? 1 : 2),
  };
  const input = format === "percent" ? number / 100 : number;
  try {
    return new Intl.NumberFormat(undefined, {
      ...options,
      ...(format === "currency" ? { currency } : {}),
    }).format(input);
  } catch {
    // An unknown currency code still shows the amount.
    return new Intl.NumberFormat(undefined, { ...options, style: "decimal" }).format(input);
  }
}

/**
 * True inside a generated Card. Components that draw their own frame (Map,
 * Calculator, Quiz) drop it there, so the Card's edge is the only one.
 */
export const InsideCardContext = React.createContext(false);

"use client";
import * as React from "react";
import * as echarts from "echarts/core";
import { RadarChart, BarChart } from "echarts/charts";
import {
  RadarComponent,
  PolarComponent,
  TooltipComponent,
  LegendComponent,
  AriaComponent,
} from "echarts/components";
import { SVGRenderer } from "echarts/renderers";
import { useTheme } from "next-themes";
import { array, nodeProps, text, type Props } from "./shared";
// Honest UI provides Cartesian and pie charts; radar and polar bars are additions.
echarts.use([
  RadarChart,
  BarChart,
  RadarComponent,
  PolarComponent,
  TooltipComponent,
  LegendComponent,
  AriaComponent,
  SVGRenderer,
]);
export function SpecializedChart({
  name,
  props,
}: {
  name: string;
  props: Props;
}) {
  const ref = React.useRef<HTMLDivElement>(null);
  const { resolvedTheme } = useTheme();
  const labels = array(props.labels).map(text);
  React.useEffect(() => {
    const element = ref.current;
    if (!element) return;
    const style = getComputedStyle(element);
    const color = style.color;
    const palette = [1, 2, 3, 4, 5].map((i) =>
      style.getPropertyValue(`--chart-${i}`).trim(),
    );
    const chart = echarts.init(element, undefined, { renderer: "svg" });
    const series = array(props.series).map(nodeProps);
    const labels = array(props.labels).map(text);
    const values = array(props.values).map(Number);
    chart.setOption({
      animation: false,
      color: palette,
      textStyle: { color },
      aria: { enabled: true, decal: { show: true } },
      tooltip: {},
      legend: { bottom: 0, textStyle: { color } },
      ...(name === "RadarChart"
        ? {
            radar: { indicator: labels.map((label) => ({ name: label })) },
            series: [
              {
                type: "radar",
                data: series.map((item) => ({
                  name: text(item.category),
                  value: array(item.values),
                })),
              },
            ],
          }
        : {
            angleAxis: { type: "value" },
            radiusAxis: {
              type: "category",
              data: labels,
              axisLabel: { color },
            },
            polar: {},
            series: [{ type: "bar", coordinateSystem: "polar", data: values }],
          }),
    });
    const observer = new ResizeObserver(() => chart.resize());
    observer.observe(element);
    return () => {
      observer.disconnect();
      chart.dispose();
    };
  }, [name, props, resolvedTheme]);
  return (
    <figure className="m-0">
      <div ref={ref} role="img" aria-label={name} className="h-72 w-full" />
      <details>
        <summary className="cursor-pointer text-sm underline">
          View chart data
        </summary>
        <table className="w-full text-sm">
          <thead>
            <tr>
              <th>Category</th>
              {array(props.series).map((series, i) => (
                <th key={i}>{text(nodeProps(series).category)}</th>
              ))}
              {!!props.values && <th>Value</th>}
            </tr>
          </thead>
          <tbody>
            {labels.map((label, i) => (
              <tr key={i}>
                <th>{label}</th>
                {array(props.series).map((series, j) => (
                  <td key={j}>{text(array(nodeProps(series).values)[i])}</td>
                ))}
                {!!props.values && <td>{text(array(props.values)[i])}</td>}
              </tr>
            ))}
          </tbody>
        </table>
      </details>
    </figure>
  );
}

