import type {
  Handler,
  Observability,
  ObservabilityDetail,
  ObservabilityEvent,
  ObservabilityLevel,
  Remove,
} from "./types";

/**
 * All listeners live in one map keyed by level plus a
 * literal "all" key for `listenAll`. An event at level
 * L is delivered to the L level and "all".
 */
const ALL_KEY = "all";

/** Internal — the package exports a single shared instance, not this factory. */
function createObservability(): Observability {
  const listeners = new Map<string, Set<Handler>>();

  // A throwing listener must not break the emitter or other listeners.
  const deliver = (listener: Handler, event: ObservabilityEvent) => {
    try {
      listener(event);
    } catch (error) {
      console.error("[Honest AI observability] listener threw", error);
    }
  };

  const subscribe = (key: string, handler: Handler): Remove => {
    let set = listeners.get(key);
    if (!set) {
      set = new Set();
      listeners.set(key, set);
    }
    set.add(handler);
    return () => {
      set.delete(handler);
    };
  };

  const emit = (level: ObservabilityLevel, detail: ObservabilityDetail): void => {
    const event: ObservabilityEvent = { level, timestamp: Date.now(), detail };
    const targets = new Set<Handler>();
    listeners.get(level)?.forEach((listener) => targets.add(listener));
    listeners.get(ALL_KEY)?.forEach((listener) => targets.add(listener));
    targets.forEach((listener) => deliver(listener, event));
  };

  // The bus IS the emit function, with the rest of the API attached to it.
  const bus = emit as Observability;

  bus.listen = (level, handler) => {
    const levels = Array.isArray(level) ? level : [level];
    const removers = levels.map((l) => subscribe(l, handler as Handler));
    return () => removers.forEach((remove) => remove());
  };
  bus.listenAll = (handler) => subscribe(ALL_KEY, handler);
  bus.info = (detail) => emit("info", detail);
  bus.warn = (detail) => emit("warning", detail);
  bus.error = (detail) => emit("error", detail);

  return bus;
}

/**
 * The shared observability bus. Keyed on globalThis via `Symbol.for` so
 * duplicate copies of this module (ESM/CJS dual builds, nested package
 * versions) still share one instance.
 */
const BUS_KEY = Symbol.for("honestai.observability");
const store = globalThis as { [BUS_KEY]?: Observability };
export const observability: Observability = (store[BUS_KEY] ??= createObservability());

// Copyright (c) 2011-2024 Thesys Inc. MIT; see the generative source LICENSE.
/** The observability interface */
export interface Observability {
  /** Emit an event at `level` carrying `detail`. */
  (level: ObservabilityLevel, detail: ObservabilityDetail): void;

  /**
   * Listen to one level, or several — every event at that level. Returns a
   * remover.
   */
  listen(
    level: ObservabilityLevel | ObservabilityLevel[],
    handler: (event: ObservabilityEvent) => void,
  ): Remove;
  /** Listen to every event — the attachment point for sinks. Returns a remover. */
  listenAll(handler: (event: ObservabilityEvent) => void): Remove;

  /** Level shortcut — emit `detail` at info level. */
  info(detail: ObservabilityDetail): void;
  /** Level shortcut — emit `detail` at warning level. */
  warn(detail: ObservabilityDetail): void;
  /** Level shortcut — emit `detail` at error level. */
  error(detail: ObservabilityDetail): void;
}

export type Remove = () => void;

export type Handler = (event: ObservabilityEvent) => void;

/**
 * Normalized error, convenient to place on an event's `detail` (e.g.
 * `{ error: ObservabilityErrorInfo }`) so third party sinks
 * can forward it without unwrapping.
 */
export interface ObservabilityErrorInfo {
  /** Error class name, e.g. "TypeError". */
  name?: string;
  message: string;
  stack?: string;
  /** The original thrown value, for listeners that need more than the normalized fields. */
  cause?: unknown;
}

export type ObservabilityLevel = "info" | "warning" | "error";

/**
 * Payload shape for every event. A required `kind` gives each
 * event a machine-readable descriptor (the structured replacement for a
 * top-level type); everything else is optional or free extra fields.
 */
export interface ObservabilityDetail {
  /**
   * Stable identity for successive snapshots of one logical event. Consumers
   * may replace an earlier snapshot when another event uses the same id.
   */
  id?: string;
  /** Short descriptor of what happened, e.g. "fetch:error", "route:change". */
  kind: string;
  /** Optional human-readable message. */
  message?: string;
  /** Present on failures; build it with `toErrorInfo()`. */
  error?: ObservabilityErrorInfo;
  /** Extra structured fields — ids, timings, urls, etc. */
  [key: string]: unknown;
}

/** The fixed envelope every listener receives. */
export interface ObservabilityEvent {
  level: ObservabilityLevel;
  /** Milliseconds since epoch. */
  timestamp: number;
  detail: ObservabilityDetail;
}

// Copyright (c) 2011-2024 Thesys Inc. MIT; see the generative source LICENSE.
import { ObservabilityErrorInfo } from "./types";

/** Normalize any thrown value into the fixed error shape, for placing on `detail`. */
export function toErrorInfo(value: unknown): ObservabilityErrorInfo {
  if (value instanceof Error) {
    return { name: value.name, message: value.message, stack: value.stack, cause: value };
  }
  let message: string;
  if (typeof value === "string") {
    message = value;
  } else {
    try {
      message = JSON.stringify(value) ?? String(value);
    } catch {
      message = String(value);
    }
  }
  return { message, cause: value };
}

