        "- EntityList is a compact two-column list of { left, right } rows (e.g. name / value). size='default' also supports a header and footer row; size='small' does not.",
        "- ListBlock is a numbered or image list of ListItem references. An action on ListItem is optional."
      ]
    },
    {
      "name": "Cards",
      "components": [
        "SnippetCardBlock",
        "SnippetCardItem",
        "OverviewCardBlock",
        "OverviewCardItem",
        "ContextCardBlock",
        "ContextCardItem",
        "CompositeCardBlock",
        "CompositeCardItem",
        "VisualCardBlock",
        "VisualCardItem",
        "Text",
        "BoldText",
        "IconText",
        "ImageText",
        "ImageTextLarge",
        "MetricIndicatorInline",
        "MetricIndicatorWithStrikethrough"
      ],
      "notes": [
        "- Card blocks lay out 2+ items in a responsive grid (or carousel where supported). Every item in a block must have the same structure.",
        "- SnippetCardItem: small card with lhs (IconText | ImageText) and optional rhs (Text | BoldText) — good for key/value facts.",
        "- OverviewCardItem: small card with top (IconText | ImageText | Text) and optional bottom MetricIndicatorInline — good for KPIs.",
        "- ContextCardItem: medium card with a title (string or Tag), body text and optional background image — good for summaries.",
        "- CompositeCardItem: rich card with header, body array (Text, BoldText, MetricIndicatorInline, IconText, Image, charts, ListBlock, TagBlock, EntityList) and footer (price + Button) — good for products/offers.",
        "- VisualCardItem: image-first card with a BoldText body and optional Tag.",
        "- Text / BoldText / IconText / ImageText / ImageTextLarge / MetricIndicator* are the inline building blocks used INSIDE card items; do not place them directly in the root Card."
      ]
    }
  ],
  "functions": {
    "Pow": {
      "signature": "Pow(base: number | string, exponent: number | string) → number",
      "description": "base raised to exponent, e.g. compound growth (1 + rate) ^ years"
    },
    "Format": {
      "signature": "Format(number?: number | string, format?: \"number\" | \"currency\" | \"percent\", decimals?: number | string, currency?: string) → string",
      "description": "A number as text in the reader's locale: \"number\" (default), \"currency\" (code defaults to \"USD\") or \"percent\" (5 shows 5%). Shows \"—\" when the number cannot be calculated."
    },
    "Range": {
      "signature": "Range(start: number | string, end: number | string, step?: number | string) → number[]",
      "description": "Whole numbers from start to end inclusive, by step (default 1), at most 10000, so bound any input that sets end to 10000. Use with @Each for one row or label per year, or with @Sum to count simulated trials."
    },
    "Random": {
      "signature": "Random(seed: any, min?: number | string, max?: number | string) → number",
      "description": "A repeatable random draw: the same seed always gives the same number. With min and max, a whole number from min to max inclusive; without them, a fraction from 0 up to 1. Draw again by changing the seed (a button with @Set($run, $run + 1)); for many draws use a list seed such as [$run, t, \"car\"]."
    }
  },
