import rehypeKatex from "rehype-katex"
import remarkMath from "remark-math"

import type { MarkdownProps } from "@/components/ai/markdown"

type MathPlugins = Required<Pick<MarkdownProps, "remarkPlugins" | "rehypePlugins">>

/**
 * The plugins that typeset math with KaTeX. Spread the result onto Markdown,
 * and import `katex/dist/katex.min.css` once in your app.
 *
 * Math is written between `$$`. A single `$` is left as text unless
 * `singleDollar` is set, so "$5 and $10" stays a pair of prices.
 *
 * Call this once, outside your components, so the plugins keep their identity.
 */
export function createMathPlugins({ singleDollar = false }: { singleDollar?: boolean } = {}): MathPlugins {
  return {
    remarkPlugins: [[remarkMath, { singleDollarTextMath: singleDollar }]],
    rehypePlugins: [rehypeKatex],
  }
}

export const mathPlugins = createMathPlugins()

// Exact backtick runs allow a code span to contain shorter runs of backticks.
const INLINE_CODE = /(?<!`)(`+)(?!`)[\s\S]*?(?<!`)\1(?!`)/g
const FENCE_LINE = /^ {0,3}(?:>[ \t]*)*(?:[-+*] |\d+[.)] )?[ \t]*(`{3,}|~{3,})(.*)$/

// `\[ … \]` that has its lines to itself, behind any list indent or quote marks.
const DISPLAY_MATH = /^([ \t]*(?:>[ \t]*)*)\\\[[ \t]*\r?\n([\s\S]*?)^\1\\\][ \t]*$/gm
const SINGLE_LINE_DISPLAY_MATH = /^([ \t]*(?:>[ \t]*)*)\\\[([^\n]+?)\\\][ \t]*$/gm
const INLINE_MATH = /\\\[(.+?)\\\]|\\\((.+?)\\\)/g

/**
 * Rewrites the LaTeX delimiters models often use, `\[ … \]` and `\( … \)`, as
 * the `$$` the math plugins read. Code is left alone, and so is a delimiter
 * whose closing half has not arrived yet.
 */
export function normalizeMathDelimiters(source: string) {
  function normalizeProse(text: string) {
    return text
      .replace(
        DISPLAY_MATH,
        (_match, prefix: string, math: string) => `${prefix}$$\n${math.trimEnd()}\n${prefix}$$`
      )
      .replace(
        SINGLE_LINE_DISPLAY_MATH,
        (_match, prefix: string, math: string) => `${prefix}$$\n${prefix}${math.trim()}\n${prefix}$$`
      )
      .replace(INLINE_MATH, (_match, bracketed?: string, parenthesized?: string) => {
        return `$$${(bracketed ?? parenthesized ?? "").trim()}$$`
      })
  }

  function normalizeOutsideInlineCode(text: string) {
    let result = ""
    let offset = 0
    for (const match of text.matchAll(INLINE_CODE)) {
      result += normalizeProse(text.slice(offset, match.index)) + match[0]
      offset = match.index + match[0].length
    }
    return result + normalizeProse(text.slice(offset))
  }

  let result = ""
  let proseStart = 0
  let offset = 0
  let fence: string | undefined
  let fenceStart = 0
  for (const line of source.split("\n")) {
    const match = FENCE_LINE.exec(line)
    if (match && fence === undefined) {
      result += normalizeOutsideInlineCode(source.slice(proseStart, offset))
      fence = match[1]
      fenceStart = offset
    } else if (
      match && fence && match[1][0] === fence[0] &&
      match[1].length >= fence.length && match[2].trim() === ""
    ) {
      result += source.slice(fenceStart, offset + line.length)
      proseStart = offset + line.length
      fence = undefined
    }
    offset += line.length + 1
  }

  // An unfinished fence is code through the end of the source.
  return result + (fence ? source.slice(fenceStart) : normalizeOutsideInlineCode(source.slice(proseStart)))
}

"use client"

import * as React from "react"
import type { BundledLanguage, BundledTheme, Highlighter, ThemedToken } from "shiki"

import type { MarkdownCodeLine, MarkdownProps } from "@/components/ai/markdown"

export type ShikiCodeLineOptions = {
  /** The theme for light surfaces. */
  light?: BundledTheme
  /** The theme used under Tailwind's `dark` variant. */
  dark?: BundledTheme
}

// How many highlighted blocks to keep. A block that is still arriving adds one each time it grows.
const CACHED_BLOCKS = 32

function createShikiStore({ light, dark }: Required<ShikiCodeLineOptions>) {
  const listeners = new Set<() => void>()
  const cache = new Map<string, ThemedToken[][]>()
  // Languages that are loaded, are loading, or cannot be loaded.
  const requested = new Set<string>()
  const loaded = new Set<string>()
  let highlighter: Highlighter | undefined
  let highlighterPromise: Promise<Highlighter> | undefined

  const notify = () => listeners.forEach((listener) => listener())

  async function load(language: string) {
    const shiki = await import("shiki")
    highlighterPromise ??= shiki.createHighlighter({ themes: [light, dark], langs: [] })
    const instance = await highlighterPromise

    // An unknown language stays plain text.
    if (!(language in shiki.bundledLanguages)) return
    await instance.loadLanguage(language as BundledLanguage)

    highlighter = instance
    loaded.add(language)
    notify()
  }

  return {
    subscribe(listener: () => void) {
      listeners.add(listener)
      return () => listeners.delete(listener)
    },

    /** Starts loading a language. Call it from an effect. */
    request(language: string) {
      if (requested.has(language)) return
      requested.add(language)
      // A highlighter that fails to load leaves the code as plain text, which is still correct.
      load(language).catch(() => undefined)
    },

    /** The block's tokens by line, or nothing while its language is not loaded. */
    getLines(code: string, language: string) {
      if (!highlighter || !loaded.has(language)) return undefined

      const key = `${language}\n${code}`
      let lines = cache.get(key)
      if (!lines) {
        lines = highlighter.codeToTokens(code, {
          lang: language as BundledLanguage,
          themes: { light, dark },
          defaultColor: false,
        }).tokens
        cache.set(key, lines)
        if (cache.size > CACHED_BLOCKS) cache.delete(cache.keys().next().value as string)
      }
      return lines
    },
  }
}

type ShikiStore = ReturnType<typeof createShikiStore>

function ShikiLine({
  store,
  text,
  language,
  line,
}: {
  store: ShikiStore
  text: string
  language: string
  line: MarkdownCodeLine
}) {
  const lines = React.useSyncExternalStore(
    store.subscribe,
    () => store.getLines(line.code, language),
    () => undefined
  )
  React.useEffect(() => store.request(language), [store, language])

  const tokens = lines?.[line.index]
  if (!tokens) return text

  return tokens.map((token, index) => (
    <span
      key={index}
      style={token.htmlStyle}
      className="text-[var(--shiki-light)] dark:text-[var(--shiki-dark)]"
    >
      {token.content}
    </span>
  ))
}

/**
 * Makes a `renderCodeLine` for Markdown that colors code with Shiki. Shiki and
 * each language load the first time a block needs them; until then, and for a
 * language Shiki does not know, the code is plain text.
 *
 * Call this once, outside your components.
 */
export function createShikiCodeLine({
  light = "github-light-high-contrast",
  dark = "github-dark-high-contrast",
}: ShikiCodeLineOptions = {}): NonNullable<MarkdownProps["renderCodeLine"]> {
  const store = createShikiStore({ light, dark })

  return function renderShikiCodeLine(text, language, line) {
    if (language === undefined) return text
    return <ShikiLine store={store} text={text} language={language} line={line} />
  }
}

