export function PreviewRail({
  items,
  label = "Section navigation",
  orientation = "vertical",
  activeId,
  defaultActiveId,
  onActiveChange,
  onItemSelect,
  renderPreview,
  showPreview = true,
  previewSide = "after",
  highlightActive = false,
  itemSize = 24,
  children,
  className,
  railClassName,
  previewContainerClassName,
  previewClassName,
}: PreviewRailProps) {
  const uid = useId();
  const reduce = useReducedMotion();
  const rootRef = useRef<HTMLDivElement>(null);
  const [internalActiveId, setInternalActiveId] = useState(
    defaultActiveId ?? items[0]?.id ?? "",
  );
  const [hoveredId, setHoveredId] = useState<string | null>(null);
  // A finger cannot hover, so a tap lights the tick instead. Kept apart from
  // the hovered one: they end in different ways, and a stray mouse move must
  // not clear a tick the keyboard or a tap chose.
  const [pinnedId, setPinnedId] = useState<string | null>(null);
  const [focusedId, setFocusedId] = useState<string | null>(null);
  // A click carries no pointerType, so the pointerdown before it is what says
  // whether the activation was a tap. Keyboard activation has none at all.
  const tap = useTapGesture<boolean>();
  const hover = useHoverGesture();

  const clearPinned = useCallback(() => setPinnedId(null), []);

  // The next tap outside the rail stands in for the pointer leaving it. The
  // card is a preview, so that tap passes through to whatever it landed on.
  useDismiss(pinnedId !== null, clearPinned, rootRef);

  const requestedActiveId = activeId ?? internalActiveId;
  const selectedId = items.some((item) => item.id === requestedActiveId)
    ? requestedActiveId
    : (items[0]?.id ?? "");
  const displayedId = hoveredId ?? pinnedId ?? focusedId ?? "";
  const highlightedId = displayedId || (highlightActive ? selectedId : "");
  const displayedIndex = items.findIndex((item) => item.id === highlightedId);
  const rowTemplate = items.length
    ? `repeat(${items.length}, ${itemSize}px)`
    : undefined;
  const isHorizontal = orientation === "horizontal";

  const selectItem = (id: string) => {
    if (activeId === undefined) setInternalActiveId(id);
    onActiveChange?.(id);
  };

  return (
    <motion.div
      layoutRoot
      ref={rootRef}
      onBlur={(event) => {
        // Both tick sources leave with the focus: a tap does not always land
        // focus, but when it does, tabbing away must not strand the card.
        if (!event.currentTarget.contains(event.relatedTarget)) {
          setFocusedId(null);
          setPinnedId(null);
        }
      }}
      className={cn(
        "isolate relative flex w-full overflow-visible",
        isHorizontal
          ? "min-h-64 flex-col items-center justify-center"
          : "min-h-80",
        className,
      )}
    >
      <nav
        aria-label={label}
        onPointerLeave={(event) => {
          // A touch pointer leaves on lift, which would clear the tick the tap
          // just chose — that one is cleared by the outside tap instead.
          if (hover.leave(event)) setHoveredId(null);
        }}
        style={
          isHorizontal
            ? { gridTemplateColumns: rowTemplate }
            : { gridTemplateRows: rowTemplate }
        }
        className={cn(
          "relative z-10 grid shrink-0",
          isHorizontal
            ? "h-12 w-fit max-w-full self-center justify-center"
            : "w-12 content-center",
          railClassName,
        )}
      >
        {items.map((item, index) => {
          const selected = item.id === selectedId;
          const highlighted = item.id === highlightedId;
          const distance =
            displayedIndex < 0 ? Number.POSITIVE_INFINITY : Math.abs(index - displayedIndex);
          const scale = highlighted
            ? 1
            : distance === 1
              ? 0.68
              : distance === 2
                ? 0.44
                : 0.25;

          const itemContent = (
            <>
              <motion.span
                data-slot="preview-rail-tick"
                aria-hidden="true"
                animate={isHorizontal ? { scaleY: scale } : { scaleX: scale }}
                transition={reduce ? { duration: 0 } : SPRING_LAYOUT}
                className={cn(
                  "block bg-current",
                  isHorizontal
                    ? "h-12 w-0.5 origin-bottom"
                    : "h-0.5 w-12 origin-left",
                  highlighted ? "text-foreground" : undefined,
                )}
              />
            </>
          );

          const sharedClassName = cn(
            "relative flex text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
            isHorizontal
              ? "h-12 w-6 items-end justify-center"
              : "h-6 w-12 items-center",
          );
          const sharedStyle = isHorizontal
            ? { width: itemSize }
            : { height: itemSize };
          const handlePointerEnter = (event: PointerEvent<HTMLElement>) => {
            if (hover.enter(event)) setHoveredId(item.id);
          };
          const handlePointerDown = (event: PointerEvent<HTMLElement>) => {
            tap.start(event, pinnedId === item.id);
            setFocusedId(null);
          };
          // A gesture the platform takes away sends no click, and a key press
          // starts an activation that never had a pointer behind it: either
          // one leaves a record the next click would read as a tap of its own.
          const dropGesture = () => tap.drop();
          const handleFocus = (currentTarget: HTMLElement) => {
            if (currentTarget.matches(":focus-visible")) {
              setFocusedId(item.id);
            }
          };
          const handleSelect = (event: MouseEvent<HTMLElement>) => {
            const gesture = tap.take();
            const tapped =
              gesture !== null && gesture.pointerType !== "mouse";

            if (tapped) {
              // A link would otherwise show its preview and leave the page in
              // the same tap, so the card is never read: the first tap lights
              // the tick, the second follows the link.
              if (item.href && !gesture.state) {
                event.preventDefault();
                setPinnedId(item.id);
                return;
              }
              setPinnedId(item.id);
            }

            selectItem(item.id);
            onItemSelect?.(item);
          };

          return item.href ? (
            <a
              key={item.id}
              data-slot="preview-rail-item"
              href={item.href}
              target={item.target}
              rel={
                item.rel ??
                (item.target === "_blank" ? "noreferrer noopener" : undefined)
              }
              aria-label={item.ariaLabel ?? item.label}
              aria-current={selected ? "page" : undefined}
              onPointerEnter={handlePointerEnter}
              onPointerDown={handlePointerDown}
              onPointerCancel={dropGesture}
              onKeyDown={dropGesture}
              onFocus={(event) => handleFocus(event.currentTarget)}
              onClick={handleSelect}
              style={sharedStyle}
              className={sharedClassName}
            >
              {itemContent}
            </a>
          ) : (
            <button
              key={item.id}
              data-slot="preview-rail-item"
              type="button"
              aria-label={item.ariaLabel ?? item.label}
              aria-current={selected ? "location" : undefined}
              onPointerEnter={handlePointerEnter}
              onPointerDown={handlePointerDown}
              onPointerCancel={dropGesture}
              onKeyDown={dropGesture}
              onFocus={(event) => handleFocus(event.currentTarget)}
              onClick={handleSelect}
              style={sharedStyle}
              className={sharedClassName}
            >
              {itemContent}
            </button>
          );
        })}
      </nav>

      {showPreview ? (
        <div
          aria-hidden="true"
          style={
            isHorizontal
              ? { gridTemplateColumns: rowTemplate }
              : { gridTemplateRows: rowTemplate }
          }
          className={cn(
            "pointer-events-none absolute z-50 grid",
            isHorizontal
              ? "top-1/2 left-1/2 h-5 w-fit max-w-full -translate-x-1/2 -translate-y-1/2 justify-center"
              : previewSide === "before"
                ? "inset-y-0 right-16 left-4 content-center"
                : "inset-y-0 right-4 left-16 content-center",
            previewContainerClassName,
          )}
        >
          {items.map((item) => (
            <div
              key={item.id}
              style={
                isHorizontal ? { width: itemSize } : { height: itemSize }
              }
              className={cn(
                "relative flex items-center",
                isHorizontal ? "justify-center" : undefined,
              )}
            >
              {item.id === displayedId ? (
                <div
                  className={cn(
                    isHorizontal
                      ? "absolute bottom-12 left-1/2 w-72 -translate-x-1/2"
                      : cn(
                          "w-full max-w-sm",
                          previewSide === "before" && "ml-auto",
                        ),
                    previewClassName,
                  )}
                >
                  <motion.div
                    layoutId={`preview-rail-card-${uid}`}
                    transition={reduce ? { duration: 0 } : SPRING_LAYOUT}
                  >
                    <AnimatePresence mode="wait" initial={false}>
                      <motion.div
                        key={item.id}
                        initial={
                          reduce
                            ? { opacity: 0 }
                            : { opacity: 0, y: 4, filter: "blur(6px)" }
                        }
                        animate={
                          reduce
                            ? { opacity: 1 }
                            : { opacity: 1, y: 0, filter: "blur(0px)" }
                        }
                        exit={
                          reduce
                            ? { opacity: 0 }
                            : {
                                opacity: 0,
                                y: -2,
                                filter: "blur(4px)",
                                transition: {
                                  duration: 0.12,
                                  ease: EASE_OUT,
                                },
                              }
                        }
                        transition={{
                          duration: reduce ? 0 : 0.18,
                          ease: EASE_OUT,
                        }}
                      >
                        {renderPreview ? (
                          renderPreview(item)
                        ) : (
                          <DefaultPreview item={item} />
                        )}
                      </motion.div>
                    </AnimatePresence>
                  </motion.div>
                </div>
              ) : null}
            </div>
          ))}
        </div>
      ) : null}

      {children ? (
        <div className="min-h-0 min-w-0 flex-1">{children}</div>
      ) : null}
    </motion.div>
  );
}

// beui.dev/components/agents/message-scroller


// React 19 callback refs may return cleanup instead of receiving null.
function assignViewportRef(ref: Ref<HTMLElement> | undefined, node: HTMLElement | null) {
  if (typeof ref === "function") return ref(node);
  if (ref) ref.current = node;
}

const PREVIEW_TITLE_LENGTH = 56;
const PREVIEW_DESCRIPTION_LENGTH = 88;

function truncateMessageText(text: string, limit: number) {
  if (text.length <= limit) return text;
  const excerpt = text.slice(0, limit);
  const boundary = excerpt.lastIndexOf(" ");
  return `${excerpt.slice(0, boundary > limit * 0.65 ? boundary : limit).trim()}…`;
}

function getMessageText(message: HTMLElement) {
  const surface =
    message.querySelector<HTMLElement>('[data-slot="message-bubble-content"]') ??
    message.querySelector<HTMLElement>('[data-slot="message-content"]') ??
    message;
  return (surface.textContent ?? "").replace(/\s+/g, " ").trim();
}

function getMessagePreview(
  message: HTMLElement,
  assistantResponse?: HTMLElement,
) {
  const text = getMessageText(message);
  if (!text) {
    return { label: "Message", description: undefined };
  }

  if (text.length <= PREVIEW_TITLE_LENGTH) {
    const responseText = assistantResponse
      ? getMessageText(assistantResponse)
      : "";
    return {
      label: text,
      description: responseText
        ? truncateMessageText(responseText, PREVIEW_DESCRIPTION_LENGTH)
        : undefined,
    };
  }

  const titleExcerpt = text.slice(0, PREVIEW_TITLE_LENGTH);
  const titleBoundary = titleExcerpt.lastIndexOf(" ");
  const titleEnd =
    titleBoundary > PREVIEW_TITLE_LENGTH * 0.65
      ? titleBoundary
      : PREVIEW_TITLE_LENGTH;
  const label = `${text.slice(0, titleEnd).trim()}…`;
  const responseText = assistantResponse
    ? getMessageText(assistantResponse)
    : text.slice(titleEnd).trim();
  return {
    label,
    description: responseText
      ? truncateMessageText(responseText, PREVIEW_DESCRIPTION_LENGTH)
      : undefined,
  };
}

export interface MessageScrollerProps extends ComponentPropsWithRef<"div"> {
  /** Keep streamed output pinned while the reader remains near the end. */
  followOutput?: boolean;
  /** Distance from the end that still counts as following the output. */
  followThreshold?: number;
  /** Smoothly follow growing content. */
  smooth?: boolean;
  /** Reports when the reader leaves or returns to the live edge. */
  onFollowChange?: (following: boolean) => void;
  /** Accessible label for the scrollable transcript. */
  label?: string;
  /** Marks the transcript as waiting for more streamed content. */
  busy?: boolean;
  /** Adds a compact rail for navigating between rendered Message rows. */
  navigation?: "rail";
  /** Accessible label for the optional message navigation rail. */
  navigationLabel?: string;
  viewportClassName?: string;
  contentClassName?: string;
  railClassName?: string;
  viewportRef?: Ref<HTMLElement>;
  viewportProps?: Omit<
    ComponentPropsWithRef<"section">,
    "children" | "className" | "ref"
  >;
  contentProps?: Omit<
    ComponentPropsWithRef<"div">,
    "children" | "className" | "ref"
  >;
}

export function MessageScroller({
  followOutput = true,
  followThreshold = 56,
  smooth = true,
  onFollowChange,
  label = "Conversation",
  busy,
  navigation,
  navigationLabel = "Message navigation",
  viewportClassName,
  contentClassName,
  railClassName,
  viewportRef: externalViewportRef,
  viewportProps,
  contentProps,
  className,
  children,
  ...props
}: MessageScrollerProps) {
  const reduce = useReducedMotion() ?? false;
  const viewportRef = useRef<HTMLElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);
  const followingRef = useRef(followOutput);
  const programmaticScrollRef = useRef(false);
  const scrollTimerRef = useRef<number | undefined>(undefined);
  const frameRef = useRef<number | undefined>(undefined);
  const railFrameRef = useRef<number | undefined>(undefined);
  const railIdRef = useRef(new WeakMap<HTMLElement, string>());
  const railIdCounterRef = useRef(0);
  const railTargetsRef = useRef(new Map<string, HTMLElement>());
  const [railItems, setRailItems] = useState<PreviewRailItem[]>([]);
  const [activeRailId, setActiveRailId] = useState("");
  const [railOverflowing, setRailOverflowing] = useState(false);
  const {
    onScroll: onViewportScroll,
    onWheel: onViewportWheel,
    onTouchStart: onViewportTouchStart,
    onKeyDown: onViewportKeyDown,
    ...restViewportProps
  } = viewportProps ?? {};

  const setViewportRef = useCallback(
    (node: HTMLElement | null) => {
      viewportRef.current = node;
      const cleanup = assignViewportRef(externalViewportRef, node);
      return () => {
        viewportRef.current = null;
        if (typeof cleanup === "function") cleanup();
        else assignViewportRef(externalViewportRef, null);
      };
    },
    [externalViewportRef],
  );

  const setFollowing = useCallback(
    (next: boolean) => {
      if (followingRef.current === next) return;
      followingRef.current = next;
      onFollowChange?.(next);
    },
    [onFollowChange],
  );

  const updateActiveRailItem = useCallback(() => {
    if (navigation !== "rail") return;
    const viewport = viewportRef.current;
    const targets = [...railTargetsRef.current.entries()];
    if (!viewport || targets.length === 0) return;

    const viewportRect = viewport.getBoundingClientRect();
    if (viewport.scrollTop <= followThreshold) {
      const firstId = targets[0]?.[0] ?? "";
      setActiveRailId((current) => (current === firstId ? current : firstId));
      return;
    }

    const distanceFromEnd =
      viewport.scrollHeight - viewport.scrollTop - viewport.clientHeight;
    if (distanceFromEnd <= followThreshold) {
      const lastId = targets.at(-1)?.[0] ?? "";
      setActiveRailId((current) => (current === lastId ? current : lastId));
      return;
    }

    const viewportCenter = viewportRect.top + viewportRect.height / 2;
    let nearestId = targets[0]?.[0] ?? "";
    let nearestDistance = Number.POSITIVE_INFINITY;

    for (const [id, element] of targets) {
      const rect = element.getBoundingClientRect();
      const messageCenter = rect.top + rect.height / 2;
      const distance = Math.abs(messageCenter - viewportCenter);
      if (distance < nearestDistance) {
        nearestDistance = distance;
        nearestId = id;
      }
    }

    setActiveRailId((current) =>
      current === nearestId ? current : nearestId,
    );
  }, [followThreshold, navigation]);

  const syncRailItems = useCallback(() => {
    if (navigation !== "rail") return;
    const content = contentRef.current;
    const viewport = viewportRef.current;
    if (!content || !viewport) return;

    const messages = Array.from(
      content.querySelectorAll<HTMLElement>('[data-slot="message"]'),
    );
    const targets = new Map<string, HTMLElement>();
    const nextItems = messages.map((message, index) => {
      let id = railIdRef.current.get(message);
      if (!id) {
        railIdCounterRef.current += 1;
        id = `message-rail-${railIdCounterRef.current}`;
        railIdRef.current.set(message, id);
      }
      targets.set(id, message);
      const sender = message.dataset.from ?? "conversation";
      const assistantResponse =
        sender === "user"
          ? messages
              .slice(index + 1)
              .find((candidate) => candidate.dataset.from === "assistant")
          : undefined;
      const preview = getMessagePreview(message, assistantResponse);

      return {
        id,
        label: preview.label,
        description: preview.description,
        ariaLabel: `Go to ${sender} message ${index + 1} of ${messages.length}`,
      };
    });

    railTargetsRef.current = targets;
    setRailItems((current) => {
      const unchanged =
        current.length === nextItems.length &&
        current.every(
          (item, index) =>
            item.id === nextItems[index]?.id &&
            item.label === nextItems[index]?.label &&
            item.description === nextItems[index]?.description &&
            item.ariaLabel === nextItems[index]?.ariaLabel,
        );
      return unchanged ? current : nextItems;
    });
    setRailOverflowing(
      viewport.scrollHeight > viewport.clientHeight + 1 && messages.length > 1,
    );
  }, [navigation]);

  const scheduleRailSync = useCallback(() => {
    if (navigation !== "rail") return;
    if (railFrameRef.current) cancelAnimationFrame(railFrameRef.current);
    railFrameRef.current = requestAnimationFrame(() => {
      syncRailItems();
      updateActiveRailItem();
    });
  }, [navigation, syncRailItems, updateActiveRailItem]);

  const scrollToEnd = useCallback((behavior: ScrollBehavior) => {
    const viewport = viewportRef.current;
    if (!viewport) return;

    programmaticScrollRef.current = true;
    if (typeof viewport.scrollTo === "function") {
      viewport.scrollTo({ top: viewport.scrollHeight, behavior });
    } else {
      viewport.scrollTop = viewport.scrollHeight;
    }
    if (scrollTimerRef.current) window.clearTimeout(scrollTimerRef.current);
    scrollTimerRef.current = window.setTimeout(() => {
      programmaticScrollRef.current = false;
    }, behavior === "smooth" ? 320 : 0);
  }, []);

  const handleScroll = useCallback(() => {
    const viewport = viewportRef.current;
    if (!viewport || programmaticScrollRef.current) return;

    const distance =
      viewport.scrollHeight - viewport.scrollTop - viewport.clientHeight;
    setFollowing(distance <= followThreshold);
    updateActiveRailItem();
  }, [followThreshold, setFollowing, updateActiveRailItem]);

  const leaveLiveEdge = useCallback(() => {
    programmaticScrollRef.current = false;
  }, []);

  useLayoutEffect(() => {
    followingRef.current = followOutput;
    if (!followOutput) return;

    frameRef.current = requestAnimationFrame(() => scrollToEnd("auto"));
    return () => {
      if (frameRef.current) cancelAnimationFrame(frameRef.current);
    };
  }, [followOutput, scrollToEnd]);

  useEffect(() => {
    const content = contentRef.current;
    if (!content || typeof ResizeObserver === "undefined") return;

    const observer = new ResizeObserver(() => {
      scheduleRailSync();
      if (!followOutput || !followingRef.current) return;
      scrollToEnd(reduce || !smooth ? "auto" : "smooth");
    });
    observer.observe(content);

    return () => observer.disconnect();
  }, [followOutput, reduce, scheduleRailSync, scrollToEnd, smooth]);

  useEffect(() => {
    if (navigation !== "rail") {
      railTargetsRef.current.clear();
      return;
    }

    const content = contentRef.current;
    const viewport = viewportRef.current;
    if (!content || !viewport) return;

    scheduleRailSync();
    const mutationObserver =
      typeof MutationObserver === "undefined"
        ? null
        : new MutationObserver(scheduleRailSync);
    mutationObserver?.observe(content, {
      childList: true,
      characterData: true,
      subtree: true,
    });

    const resizeObserver =
      typeof ResizeObserver === "undefined"
        ? null
        : new ResizeObserver(scheduleRailSync);
    resizeObserver?.observe(content);
    resizeObserver?.observe(viewport);

    return () => {
      mutationObserver?.disconnect();
      resizeObserver?.disconnect();
    };
  }, [navigation, scheduleRailSync]);

  useEffect(
    () => () => {
      if (scrollTimerRef.current) window.clearTimeout(scrollTimerRef.current);
      if (frameRef.current) cancelAnimationFrame(frameRef.current);
      if (railFrameRef.current) cancelAnimationFrame(railFrameRef.current);
    },
    [],
  );

  const scrollToRailItem = useCallback(
    (item: PreviewRailItem) => {
      const viewport = viewportRef.current;
      const target = railTargetsRef.current.get(item.id);
      if (!viewport || !target) return;

      const lastItem = railItems.at(-1)?.id === item.id;
      setActiveRailId(item.id);
      if (lastItem) {
        setFollowing(true);
        scrollToEnd(reduce || !smooth ? "auto" : "smooth");
        return;
      }

      setFollowing(false);
      programmaticScrollRef.current = true;
      const viewportRect = viewport.getBoundingClientRect();
      const targetRect = target.getBoundingClientRect();
      const top =
        viewport.scrollTop +
        targetRect.top -
        viewportRect.top -
        (viewport.clientHeight - targetRect.height) / 2;
      const behavior = reduce || !smooth ? "auto" : "smooth";

      if (typeof viewport.scrollTo === "function") {
        viewport.scrollTo({ top, behavior });
      } else {
        viewport.scrollTop = top;
      }
      if (scrollTimerRef.current) window.clearTimeout(scrollTimerRef.current);
      scrollTimerRef.current = window.setTimeout(() => {
        programmaticScrollRef.current = false;
      }, behavior === "smooth" ? 320 : 0);
    },
    [railItems, reduce, scrollToEnd, setFollowing, smooth],
  );

  const viewport = (
    <section
      ref={setViewportRef}
      aria-label={label}
      tabIndex={0}
      {...restViewportProps}
      onScroll={(event) => {
        handleScroll();
        onViewportScroll?.(event);
      }}
      onWheel={(event) => {
        leaveLiveEdge();
        onViewportWheel?.(event);
      }}
      onTouchStart={(event) => {
        leaveLiveEdge();
        onViewportTouchStart?.(event);
      }}
      onKeyDown={(event) => {
        if (["ArrowUp", "PageUp", "Home"].includes(event.key)) {
          leaveLiveEdge();
        }
        onViewportKeyDown?.(event);
      }}
      className={cn(
        "h-full overflow-y-auto overscroll-contain outline-none [overflow-anchor:none] focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring",
        navigation === "rail"
          ? "[-ms-overflow-style:none] [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"
          : "[scrollbar-gutter:stable]",
        viewportClassName,
        navigation === "rail" && railOverflowing && "pr-10",
      )}
    >
      <div
        ref={contentRef}
        role="log"
        aria-live="polite"
        aria-relevant="additions text"
        aria-busy={busy}
        className={contentClassName}
        {...contentProps}
      >
        {children}
      </div>
    </section>
  );

  return (
    <div
      data-slot="message-scroller"
      className={cn("min-h-0", className)}
      {...props}
    >
      {navigation === "rail" ? (
        <PreviewRail
          items={railOverflowing ? railItems : []}
          label={navigationLabel}
          activeId={activeRailId}
          onItemSelect={scrollToRailItem}
          previewSide="before"
          highlightActive
          itemSize={14}
          className="h-full min-h-0 overflow-hidden"
          previewContainerClassName="right-8 left-3"
          previewClassName="mr-1 w-64 max-w-full [&_[data-slot=preview-rail-card]]:h-20 [&_[data-slot=preview-rail-card]]:overflow-hidden [&_[data-slot=preview-rail-card]]:p-3 [&_[data-slot=preview-rail-title]]:line-clamp-1 [&_[data-slot=preview-rail-title]]:text-xs [&_[data-slot=preview-rail-title]]:leading-4 [&_[data-slot=preview-rail-description]]:line-clamp-2 [&_[data-slot=preview-rail-description]]:text-xs [&_[data-slot=preview-rail-description]]:leading-4"
          railClassName={cn(
            "absolute inset-y-3 right-1 w-7 content-center py-1 [&_[data-slot=preview-rail-item]]:w-7 [&_[data-slot=preview-rail-item]]:justify-end [&_[data-slot=preview-rail-tick]]:h-px [&_[data-slot=preview-rail-tick]]:w-4 [&_[data-slot=preview-rail-tick]]:origin-right",
            railOverflowing
              ? "pointer-events-auto opacity-100"
              : "pointer-events-none opacity-0",
            railClassName,
          )}
        >
          {viewport}
        </PreviewRail>
      ) : (
        viewport
      )}
    </div>
  );
}

"use client"

import * as React from "react"
import {
  ArrowUp as ArrowUpIcon,
  ChevronDown as ChevronDownIcon,
  File as FileIcon,
  Paperclip as PaperclipIcon,
  Square as SquareIcon,
  X as CloseIcon,
} from "honestui/icons"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import {
  Menu,
  MenuPopup,
  MenuRadioGroup,
  MenuRadioItem,
  MenuTrigger,
} from "@/components/ui/menu"

export type PromptBarItem = {
  id: string
  /** The text inserted after the trigger character, and matched against what is typed. */
  label: string
  description?: string
  icon?: React.ReactNode
}

export type PromptBarModel = {
  id: string
  label: string
  description?: string
  /** Shown before the label, such as the logo of the model's maker. Decorative: the label names the model. */
  icon?: React.ReactNode
}

export type PromptBarSubmission = {
  /** The prompt, trimmed. */
  text: string
  attachments: File[]
  /** The selected model's `id`, when `models` is passed. */
  model: string | undefined
}

export type PromptBarLabels = {
  prompt: string
  send: string
  stop: string
  attach: string
  attachments: string
  removeAttachment: (name: string) => string
  model: string
  mentions: string
  commands: string
  noMatches: (query: string) => string
  suggestionCount: (count: number) => string
}

export const defaultPromptBarLabels: PromptBarLabels = {
  prompt: "Prompt",
  send: "Send",
  stop: "Stop",
  attach: "Attach files",
  attachments: "Attachments",
  removeAttachment: (name) => `Remove ${name}`,
  model: "Model",
  mentions: "Sources",
  commands: "Commands",
  noMatches: (query) => `No matches for “${query}”.`,
  suggestionCount: (count) => (count === 1 ? "1 suggestion" : `${count} suggestions`),
}

const MAX_INPUT_HEIGHT = 160

const bodyText =
  "[font-size:var(--hui-font-size-regular)] [letter-spacing:var(--hui-letter-spacing-regular)] [line-height:var(--hui-line-height-regular)]"

const smallText =
  "[font-size:var(--hui-font-size-small)] [letter-spacing:var(--hui-letter-spacing-small)] [line-height:var(--hui-line-height-small)]"

type Suggestion = {
  kind: "mention" | "command"
  /** Where the trigger character sits in the text. */
  start: number
  query: string
}

/** Finds an `@word` or `/word` that ends at the caret and starts a word. */
function findSuggestion(text: string, caret: number): Suggestion | null {
  const match = /(^|\s)([@/])([\w-]*)$/.exec(text.slice(0, caret))
  if (!match) return null

  return {
    kind: match[2] === "@" ? "mention" : "command",
    start: match.index + match[1].length,
    query: match[3].toLowerCase(),
  }
}

function useControllableState<T>(
  controlled: T | undefined,
  defaultValue: T,
  onChange: ((value: T) => void) | undefined
) {
  const [uncontrolled, setUncontrolled] = React.useState(defaultValue)
  const value = controlled !== undefined ? controlled : uncontrolled
  const setValue = (next: T) => {
    if (controlled === undefined) setUncontrolled(next)
    onChange?.(next)
  }

  return [value, setValue] as const
}

export type PromptBarProps = Omit<
  React.ComponentProps<"form">,
  "children" | "onSubmit" | "defaultValue"
> & {
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  /** Receives the prompt when the person sends it. The bar then clears. */
  onSubmit: (submission: PromptBarSubmission) => void
  placeholder?: string
  /** Blocks typing and sending, for example while a reply is streaming. */
  disabled?: boolean
  /** Pass it only while a reply is in progress. Stop then takes the place of Send. */
  onStop?: () => void
  /** Offered after the person types `@`. */
  mentions?: PromptBarItem[]
  /** Offered after the person types `/`. */
  commands?: PromptBarItem[]
  /** Called when a suggestion is inserted, so you can track what the text refers to. */
  onItemSelect?: (item: PromptBarItem, kind: "mention" | "command") => void
  /** Passing models adds the model menu. */
  models?: PromptBarModel[]
  model?: string
  defaultModel?: string
  onModelChange?: (model: string) => void
  /** Adds the attach button and the list of chosen files. */
  allowAttachments?: boolean
  attachments?: File[]
  onAttachmentsChange?: (attachments: File[]) => void
  /** Passed to the file input, such as "image/*,.pdf". */
  accept?: string
  /** Extra controls placed before Send, such as a dictation button you wire up. */
  actions?: React.ReactNode
  labels?: Partial<PromptBarLabels>
}

/**
 * A prompt field with optional `@` and `/` suggestions, attachments, a model
 * menu, and a Stop button. It collects the prompt and hands it to `onSubmit`;
 * the request, the reply, and cancelling it are your application's.
 */
function PromptBar({
  value: valueProp,
  defaultValue = "",
  onValueChange,
  onSubmit,
  placeholder,
  disabled = false,
  onStop,
  mentions,
  commands,
  onItemSelect,
  models,
  model: modelProp,
  defaultModel,
  onModelChange,
  allowAttachments = false,
  attachments: attachmentsProp,
  onAttachmentsChange,
  accept,
  actions,
  labels: labelsProp,
  className,
  ...props
}: PromptBarProps) {
  const labels = React.useMemo(
    () => ({ ...defaultPromptBarLabels, ...labelsProp }),
    [labelsProp]
  )
  const [value, setValue] = useControllableState(valueProp, defaultValue, onValueChange)
  const [model, setModel] = useControllableState(
    modelProp,
    defaultModel ?? models?.[0]?.id ?? "",
    onModelChange
  )
  const [attachments, setAttachments] = useControllableState<File[]>(
    attachmentsProp,
    [],
    onAttachmentsChange
  )

  const [caret, setCaret] = React.useState(value.length)
  const [activeIndex, setActiveIndex] = React.useState(0)
  // Escape closes the suggestions until the text changes again.
  const [dismissedAt, setDismissedAt] = React.useState<string | null>(null)

  const inputRef = React.useRef<HTMLTextAreaElement>(null)
  const fileInputRef = React.useRef<HTMLInputElement>(null)
  const sendButtonRef = React.useRef<HTMLButtonElement>(null)
  const shouldRefocusInput = React.useRef(false)
  const pendingCaret = React.useRef<number | null>(null)
  const listId = React.useId()

  const hasSuggestions = Boolean(mentions?.length || commands?.length)
  const suggestion = dismissedAt === value ? null : findSuggestion(value, caret)
  const source = suggestion?.kind === "mention" ? mentions : commands
  const matches = React.useMemo(() => {
    if (!suggestion || !source?.length) return []
    return source.filter((item) => {
      const label = item.label.toLowerCase()
      return suggestion.kind === "mention"
        ? label.includes(suggestion.query)
        : label.startsWith(suggestion.query)
    })
  }, [suggestion, source])
  const isMenuOpen = Boolean(suggestion && source?.length)
  const activeItem = matches[Math.min(activeIndex, matches.length - 1)]

  React.useLayoutEffect(() => {
    const input = inputRef.current
    if (!input) return

    // Grow with the text up to a limit, then scroll.
    input.style.height = "0px"
    input.style.height = `${Math.min(input.scrollHeight, MAX_INPUT_HEIGHT)}px`
    input.style.overflowY = input.scrollHeight > MAX_INPUT_HEIGHT ? "auto" : "hidden"

    if (pendingCaret.current !== null) {
      input.setSelectionRange(pendingCaret.current, pendingCaret.current)
      pendingCaret.current = null
    }
  }, [value])

  const changeValue = (next: string, nextCaret: number) => {
    setValue(next)
    setCaret(nextCaret)
    setActiveIndex(0)
    setDismissedAt(null)
  }

  const insertItem = (item: PromptBarItem) => {
    if (!suggestion) return

    const trigger = suggestion.kind === "mention" ? "@" : "/"
    const inserted = `${trigger}${item.label} `
    const nextCaret = suggestion.start + inserted.length
    pendingCaret.current = nextCaret
    changeValue(value.slice(0, suggestion.start) + inserted + value.slice(caret), nextCaret)
    onItemSelect?.(item, suggestion.kind)
    inputRef.current?.focus()
  }

  const text = value.trim()
  const isStoppable = onStop !== undefined
  const canSend = !disabled && !isStoppable && (text !== "" || attachments.length > 0)

  // Stop becomes Send again, often a disabled one. Hand focus to the field once
  // it can take it, unless the person has already moved somewhere else.
  React.useEffect(() => {
    if (!shouldRefocusInput.current || isStoppable || disabled) return
    shouldRefocusInput.current = false
    if (document.activeElement === sendButtonRef.current) inputRef.current?.focus()
  }, [isStoppable, disabled])

  const send = () => {
    if (!canSend) return
    onSubmit({ text, attachments, model: models?.length ? model : undefined })
    changeValue("", 0)
    setAttachments([])
  }

  const handleKeyDown = (event: React.KeyboardEvent<HTMLTextAreaElement>) => {
    // Enter confirms an in-progress IME composition; it must not send or pick.
    if (event.nativeEvent.isComposing) return

    if (isMenuOpen) {
      if (event.key === "Escape") {
        event.preventDefault()
        setDismissedAt(value)
        return
      }
      if (matches.length > 0) {
        if (event.key === "ArrowDown" || event.key === "ArrowUp") {
          event.preventDefault()
          const step = event.key === "ArrowDown" ? 1 : matches.length - 1
          setActiveIndex((current) => (Math.min(current, matches.length - 1) + step) % matches.length)
          return
        }
        if ((event.key === "Enter" && !event.shiftKey) || event.key === "Tab") {
          event.preventDefault()
          if (activeItem) insertItem(activeItem)
          return
        }
      }
    }

    if (event.key === "Enter" && !event.shiftKey) {
      event.preventDefault()
      send()
    }
  }

  const optionId = (item: PromptBarItem) => `${listId}-${item.id}`
  const selectedModel = models?.find((item) => item.id === model)

  return (
    <form
      data-slot="prompt-bar"
      data-disabled={disabled ? "" : undefined}
      className={cn("relative w-full min-w-0", className)}
      onSubmit={(event) => {
        event.preventDefault()
        send()
      }}
      {...props}
    >
      {isMenuOpen && (
        <div
          data-slot="prompt-bar-suggestions"
          className={cn(
            "absolute inset-x-0 bottom-full z-10 mb-[var(--hui-space-3)] max-h-64 overflow-y-auto rounded-[var(--hui-radius-4)] border-[0.5px] border-[var(--hui-color-border-base-primary)] bg-[var(--hui-color-background-base-primary)] p-[var(--hui-space-2)] text-[var(--hui-color-foreground-base-primary)] shadow-[var(--hui-shadow-lifted)]",
            smallText
          )}
        >
          {matches.length > 0 ? (
            <div
              id={listId}
              role="listbox"
              aria-label={suggestion?.kind === "mention" ? labels.mentions : labels.commands}
            >
              {matches.map((item) => {
                const isActive = item === activeItem
                return (
                  <div
                    key={item.id}
                    id={optionId(item)}
                    role="option"
                    aria-selected={isActive}
                    data-active={isActive ? "" : undefined}
                    // Keep focus in the field, so typing continues after a pick.
                    onMouseDown={(event) => event.preventDefault()}
                    onMouseMove={() => setActiveIndex(matches.indexOf(item))}
                    onClick={() => insertItem(item)}
                    className="flex min-w-0 cursor-pointer items-center gap-[var(--hui-space-3)] rounded-[var(--hui-radius-2)] px-[var(--hui-space-3)] py-[var(--hui-space-3)] data-active:bg-[var(--hui-color-background-base-primary-hover)]"
                  >
                    {item.icon && (
                      <span
                        aria-hidden="true"
                        className="flex size-4 shrink-0 items-center justify-center text-[var(--hui-color-foreground-base-secondary)] [&_svg]:size-4"
                      >
                        {item.icon}
                      </span>
                    )}
                    <span className="shrink-0 [font-weight:var(--hui-font-weight-medium)]">
                      {suggestion?.kind === "command" ? `/${item.label}` : item.label}
                    </span>
                    {item.description && (
                      <span className="min-w-0 truncate text-[var(--hui-color-foreground-base-secondary)]">
                        {item.description}
                      </span>
                    )}
                  </div>
                )
              })}
            </div>
          ) : (
            <p className="m-0 px-[var(--hui-space-3)] py-[var(--hui-space-3)] text-[var(--hui-color-foreground-base-secondary)]">
              {labels.noMatches(suggestion?.query ?? "")}
            </p>
          )}
        </div>
      )}

      {hasSuggestions && (
        <span role="status" className="sr-only">
          {isMenuOpen
            ? matches.length > 0
              ? labels.suggestionCount(matches.length)
              : labels.noMatches(suggestion?.query ?? "")
            : ""}
        </span>
      )}

      <div
        data-slot="prompt-bar-field"
        className="flex flex-col gap-[var(--hui-space-2)] rounded-[var(--hui-radius-5)] border-[0.5px] border-[var(--hui-color-border-base-tertiary)] bg-[var(--hui-color-background-base-primary)] p-[var(--hui-space-3)] shadow-[var(--hui-shadow-soft)] motion-safe:[transition:var(--hui-transition-interactive)] focus-within:border-[var(--hui-color-border-accent-emphasis)] in-data-disabled:opacity-60"
      >
        {attachments.length > 0 && (
          <ul
            role="list"
            aria-label={labels.attachments}
            data-slot="prompt-bar-attachments"
            className="m-0 flex list-none flex-wrap gap-[var(--hui-space-2)] p-0"
          >
            {attachments.map((file, index) => (
              <li
                key={`${file.name}-${file.size}-${file.lastModified}-${index}`}
                className={cn(
                  "flex min-w-0 max-w-full items-center gap-[var(--hui-space-2)] rounded-[var(--hui-radius-2)] bg-[var(--hui-color-background-base-secondary)] py-[var(--hui-space-1)] ps-[var(--hui-space-3)] pe-[var(--hui-space-1)] text-[var(--hui-color-foreground-base-secondary)]",
                  smallText
                )}
              >
                <FileIcon aria-hidden="true" className="size-3.5 shrink-0" />
                <span className="min-w-0 truncate">{file.name}</span>
                <Button
                  variant="link"
                  size="icon-sm"
                  disabled={disabled}
                  aria-label={labels.removeAttachment(file.name)}
                  onClick={() => {
                    setAttachments(attachments.filter((_, position) => position !== index))
                    inputRef.current?.focus()
                  }}
                >
                  <CloseIcon aria-hidden="true" className="size-3" />
                </Button>
              </li>
            ))}
          </ul>
        )}

        <textarea
          ref={inputRef}
          rows={1}
          data-slot="prompt-bar-input"
          value={value}
          disabled={disabled}
          placeholder={placeholder}
          aria-label={labels.prompt}
          // A textarea cannot take the combobox role, so it stays a text box that
          // points at the list and its active option.
          {...(hasSuggestions && {
            "aria-autocomplete": "list" as const,
            "aria-haspopup": "listbox" as const,
            "aria-controls": isMenuOpen && matches.length > 0 ? listId : undefined,
            "aria-activedescendant": isMenuOpen && activeItem ? optionId(activeItem) : undefined,
          })}
          onChange={(event) => changeValue(event.target.value, event.target.selectionStart)}
          onSelect={(event) => setCaret(event.currentTarget.selectionStart)}
          onKeyDown={handleKeyDown}
          className={cn(
            "m-0 block w-full min-w-0 resize-none border-0 bg-transparent px-[var(--hui-space-2)] py-[var(--hui-space-2)] text-[var(--hui-color-foreground-base-primary)] outline-none [overflow-wrap:anywhere] placeholder:text-[var(--hui-color-foreground-base-tertiary)] disabled:cursor-not-allowed",
            bodyText
          )}
        />

        <div
          data-slot="prompt-bar-controls"
          className="flex min-w-0 flex-wrap items-center gap-[var(--hui-space-2)]"
        >
          {allowAttachments && (
            <>
              <input
                ref={fileInputRef}
                type="file"
                multiple
                hidden
                accept={accept}
                tabIndex={-1}
                onChange={(event) => {
                  const added = Array.from(event.target.files ?? [])
                  if (added.length > 0) setAttachments([...attachments, ...added])
                  // Clear the input so choosing the same file again still fires a change.
                  event.target.value = ""
                  inputRef.current?.focus()
                }}
              />
              <Button
                variant="link"
                size="icon"
                disabled={disabled}
                aria-label={labels.attach}
                onClick={() => fileInputRef.current?.click()}
              >
                <PaperclipIcon aria-hidden="true" />
              </Button>
            </>
          )}

          {models && models.length > 0 && (
            <Menu>
              <MenuTrigger
                disabled={disabled}
                render={
                  <Button variant="link" size="sm" className="max-w-full min-w-0" />
                }
              >
                <span className="sr-only">{labels.model}: </span>
                {selectedModel?.icon}
                <span className="min-w-0 truncate">{selectedModel?.label ?? labels.model}</span>
                <ChevronDownIcon
                  aria-hidden="true"
                  className="size-3 text-[var(--hui-color-foreground-base-tertiary)]"
                />
              </MenuTrigger>
              <MenuPopup align="start" className="min-w-48">
                <MenuRadioGroup value={model} onValueChange={(next) => setModel(String(next))}>
                  {models.map((item) => (
                    <MenuRadioItem key={item.id} value={item.id}>
                      <span className="flex min-w-0 items-center justify-between gap-[var(--hui-space-4)]">
                        <span className="flex min-w-0 items-center gap-[var(--hui-space-2)]">
                          {item.icon}
                          <span className="min-w-0 truncate">{item.label}</span>
                        </span>
                        {item.description && (
                          <span className="shrink-0 text-[var(--hui-color-foreground-base-secondary)] [font-size:var(--hui-font-size-mini)]">
                            {item.description}
                          </span>
                        )}
                      </span>
                    </MenuRadioItem>
                  ))}
                </MenuRadioGroup>
              </MenuPopup>
            </Menu>
          )}

          <div
            data-slot="prompt-bar-actions"
            className="ms-auto flex shrink-0 items-center gap-[var(--hui-space-2)]"
          >
            {actions}
            {/* One button for both, so focus stays put when a reply starts. */}
            <Button
              ref={sendButtonRef}
              type={isStoppable ? "button" : "submit"}
              size="icon"
              disabled={!isStoppable && !canSend}
              aria-label={isStoppable ? labels.stop : labels.send}
              onClick={
                onStop &&
                ((event) => {
                  // The button may be a submit button again by the time the click
                  // finishes. Without this, stopping would also send the draft.
                  event.preventDefault()
                  shouldRefocusInput.current = true
                  onStop()
                })
              }
            >
              {isStoppable ? (
                <SquareIcon aria-hidden="true" fill="currentColor" className="size-3" />
              ) : (
                <ArrowUpIcon aria-hidden="true" strokeWidth={2} />
              )}
            </Button>
          </div>
        </div>
      </div>
    </form>
  )
}

export { PromptBar }

/*
 * Prose styles rendered Markdown and plain HTML: put `class="honest-prose"` on
 * the element that wraps it. It is plain CSS and needs no build step.
 *
 * Set these on `.honest-prose`, or on any ancestor, to change it:
 *
 *   --prose-size      Body text size.
 *   --prose-width     Maximum text width.
 *   --prose-leading   Body line height, as a number.
 *   --prose-flow      Space between blocks.
 *   --prose-heading   Size of first- and second-level headings.
 *   --prose-tracking  Body letter spacing.
 *   --prose-color, --prose-muted, --prose-surface,
 *   --prose-rule, --prose-rule-strong
 *   --prose-font-mono, --prose-radius, --prose-code-color
 *
 * Each one falls back to an Honest UI token, then to a value that works with
 * no tokens at all. Prose never sets them itself, so a value from a utility
 * class or an inline style always applies.
 *
 * Add `class="not-prose"` to anything inside that brings its own styles,
 * such as a component. It keeps its place in the flow and nothing else.
 *
 * Blocks are spaced with a top margin only, and no rule depends on what comes
 * after an element, so text that is still arriving does not move what is
 * already on screen.
 */

.honest-prose {
  --_size: var(--prose-size, var(--hui-font-size-regular, 1em));
  --_leading: var(--prose-leading, 1.6);
  --_flow: var(--prose-flow, var(--hui-space-4, 0.85em));
  --_heading: var(--prose-heading, 1.143em);
  --_color: var(--prose-color, var(--hui-color-foreground-base-primary, currentColor));
  --_muted: var(
    --prose-muted,
    var(--hui-color-foreground-base-secondary, color-mix(in oklab, currentColor 72%, transparent))
  );
  --_surface: var(
    --prose-surface,
    var(--hui-color-background-base-secondary, color-mix(in oklab, currentColor 7%, transparent))
  );
  --_rule: var(
    --prose-rule,
    var(--hui-color-border-base-primary, color-mix(in oklab, currentColor 18%, transparent))
  );
  --_rule-strong: var(
    --prose-rule-strong,
    var(--hui-color-border-base-secondary, color-mix(in oklab, currentColor 34%, transparent))
  );
  --_font-mono: var(
    --prose-font-mono,
    var(--hui-font-mono, ui-monospace, SFMono-Regular, Menlo, Consolas, monospace)
  );
  --_radius: var(--prose-radius, var(--hui-radius-1, 0.25em));

  min-width: 0;
  max-width: var(--prose-width, none);
  overflow-wrap: break-word;
  color: var(--_color);
  font-size: var(--_size);
  line-height: var(--_leading);
  letter-spacing: var(--prose-tracking, var(--hui-letter-spacing-regular, normal));
}

/* Flow */

.honest-prose
  :where(p, ul, ol, dl, blockquote, pre, table, figure, details, hr, .prose-scroll, .not-prose):not(
    :where(.not-prose *)
  ) {
  margin-block: var(--_flow) 0;
}

.honest-prose :where(p, ul, ol, dl, blockquote, pre, figure):not(:where(.not-prose, .not-prose *)) {
  margin-inline: 0;
}

/* Headings */

.honest-prose :where(h1, h2, h3, h4, h5, h6):not(:where(.not-prose, .not-prose *)) {
  margin-block: calc(var(--_flow) * 1.667) 0;
  font-family: inherit;
  font-size: 1em;
  font-weight: var(--hui-font-weight-semibold, 600);
  line-height: 1.43;
  letter-spacing: inherit;
  text-wrap: balance;
}

.honest-prose :where(h1, h2):not(:where(.not-prose, .not-prose *)) {
  font-size: var(--_heading);
  line-height: 1.5;
}

/* A heading and the block under it read as one unit. */
.honest-prose :where(h1, h2, h3, h4, h5, h6):not(:where(.not-prose, .not-prose *)) + * {
  margin-block-start: calc(var(--_flow) * 0.667);
}

/* Inline text */

.honest-prose :where(a):not(:where(.not-prose, .not-prose *)) {
  color: inherit;
  text-decoration: underline;
  text-underline-offset: 2px;
}

.honest-prose :where(strong, b):not(:where(.not-prose, .not-prose *)) {
  font-weight: var(--hui-font-weight-semibold, 600);
}

.honest-prose :where(code, kbd, samp):not(:where(.not-prose, .not-prose *)) {
  font-family: var(--_font-mono);
}

/* Inline code and code blocks set their own sizes, so code is not shrunk twice. */
.honest-prose :where(kbd, samp):not(:where(.not-prose, .not-prose *)) {
  font-size: 0.9em;
}

/* Inline code matches the docs site: a page-colored chip with a rule. */
.honest-prose :where(:not(pre) > code):not(:where(.not-prose, .not-prose *)) {
  margin-inline: 0.25rem;
  border: 1px solid var(--_rule-strong);
  border-radius: var(--_radius);
  background: var(--hui-color-background-base-primary, Canvas);
  padding: 1px 0.3rem;
  color: var(--prose-code-color, inherit);
  font-size: 0.8em;
}

.honest-prose :where(kbd):not(:where(.not-prose, .not-prose *)) {
  border: 0.5px solid var(--_rule-strong);
  border-radius: var(--_radius);
  background: var(--_surface);
  padding-inline: 0.3em;
}

/* Lists */

.honest-prose :where(ul, ol):not(:where(.not-prose, .not-prose *)) {
  padding-inline-start: 1.45em;
}

.honest-prose :where(ul):not(:where(.not-prose, .not-prose *)) {
  list-style: disc;
}

.honest-prose :where(ol):not(:where(.not-prose, .not-prose *)) {
  list-style: decimal;
}

.honest-prose :where(ul ul):not(:where(.not-prose, .not-prose *)) {
  list-style: circle;
}

.honest-prose :where(li):not(:where(.not-prose, .not-prose *)) {
  margin-block: calc(var(--_flow) / 6) 0;
}

.honest-prose :where(li) > :where(ul, ol):not(:where(.not-prose, .not-prose *)) {
  margin-block-start: calc(var(--_flow) / 6);
}

/* A task list's checkboxes stand in for the bullets. */
.honest-prose :where(ul.contains-task-list):not(:where(.not-prose, .not-prose *)) {
  list-style: none;
  padding-inline-start: 0;
}

.honest-prose :where(li.task-list-item input):not(:where(.not-prose, .not-prose *)) {
  margin: 0;
  margin-inline-end: 0.4em;
}

.honest-prose :where(dt):not(:where(.not-prose, .not-prose *)) {
  font-weight: var(--hui-font-weight-medium, 500);
}

.honest-prose :where(dd):not(:where(.not-prose, .not-prose *)) {
  margin: 0;
  color: var(--_muted);
}

/* Quotes and rules */

.honest-prose :where(blockquote):not(:where(.not-prose, .not-prose *)) {
  border-inline-start: 2px solid var(--_rule-strong);
  padding-inline-start: var(--_flow);
  color: var(--_muted);
}

.honest-prose :where(hr):not(:where(.not-prose, .not-prose *)) {
  margin-block-start: calc(var(--_flow) * 1.333);
  border: 0;
  border-block-start: 0.5px solid var(--_rule);
  height: 0;
}

/*
 * Code blocks, for a renderer that does not bring a component for them. The
 * frame matches the docs site: a surface shell around a page-colored panel
 * with a hairline rule. The border is the shell, so it needs no wrapper.
 */

.honest-prose :where(pre):not(:where(.not-prose, .not-prose *)) {
  overflow-x: auto;
  border: 0.25rem solid var(--_surface);
  border-radius: calc(var(--_radius) + 0.25rem);
  background: var(--hui-color-background-base-primary, Canvas);
  box-shadow: inset 0 0 0 0.5px var(--_rule);
  padding: 0.875rem 1rem;
  font-size: 0.8125rem;
  line-height: 1.65;
}

/* Tables */

/* Wrap a table in `.prose-scroll` so a wide one scrolls instead of the page. */
.honest-prose :where(.prose-scroll):not(:where(.not-prose, .not-prose *)) {
  overflow-x: auto;
}

/*
 * The frame is drawn on the table itself, so it needs no wrapper. Separate
 * borders let the corners round; collapsed borders cannot.
 */
.honest-prose :where(table):not(:where(.not-prose, .not-prose *)) {
  width: 100%;
  border: 0.5px solid var(--_rule);
  border-collapse: separate;
  border-spacing: 0;
  border-radius: var(--hui-radius-4, 0.5em);
  box-shadow: var(--hui-shadow-feather, none);
  font-size: 0.857em;
  line-height: 1.34;
}

.honest-prose :where(.prose-scroll) > :where(table) {
  margin-block-start: 0;
}

.honest-prose :where(th, td):not(:where(.not-prose, .not-prose *)) {
  padding: calc(var(--_flow) * 0.667) var(--_flow);
  vertical-align: top;
  text-align: start;
}

.honest-prose :where(th):not(:where(.not-prose, .not-prose *)) {
  font-weight: var(--hui-font-weight-medium, 500);
}

/* Column headers sit on a tinted band. Row headers in the body stay plain. */
.honest-prose :where(thead th):not(:where(.not-prose, .not-prose *)) {
  background: var(--_surface);
  color: var(--_muted);
}

/* Cell backgrounds are not clipped by the table's radius, so the corner cells round themselves. */
.honest-prose :where(thead > tr:first-child > th:first-child):not(:where(.not-prose, .not-prose *)) {
  border-start-start-radius: var(--hui-radius-4, 0.5em);
}

.honest-prose :where(thead > tr:first-child > th:last-child):not(:where(.not-prose, .not-prose *)) {
  border-start-end-radius: var(--hui-radius-4, 0.5em);
}

/* The line is drawn above each body cell, so a row that arrives later needs no restyle. */
.honest-prose :where(td):not(:where(.not-prose, .not-prose *)) {
  border-block-start: 0.5px solid var(--_rule);
}

/* Media */

.honest-prose :where(img, video):not(:where(.not-prose, .not-prose *)) {
  max-width: 100%;
  height: auto;
}

.honest-prose :where(figcaption):not(:where(.not-prose, .not-prose *)) {
  margin-block-start: calc(var(--_flow) / 2);
  color: var(--_muted);
  font-size: 0.857em;
}

/* Last, so it wins over the flow rules above: nothing is pushed off the top of its container. */
.honest-prose > :where(:first-child),
.honest-prose :where(li, blockquote, td, th, dd, figure) > :where(:first-child):not(:where(.not-prose *)) {
  margin-block-start: 0;
}

"use client"

import * as React from "react"
import { Check as CheckIcon, Copy as CopyIcon } from "honestui/icons"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"

export type ProseCodeBlockLabels = {
  copy: string
  copied: string
  copyFailed: string
}

export const defaultProseCodeBlockLabels: ProseCodeBlockLabels = {
  copy: "Copy code",
  copied: "Copied",
  copyFailed: "Copy failed",
}

const COPIED_MILLISECONDS = 1500

export type ProseCodeBlockProps = Omit<React.ComponentProps<"figure">, "children" | "onCopy"> & {
  /** The language or file name, shown in the frame and used to name the code for assistive technology. */
  label: string
  code: string
  /** Colors one line. Without it, lines are plain text. */
  renderLine?: (text: string, index: number) => React.ReactNode
  /** Classes for the code surface, such as `honest-syntax`. */
  codeClassName?: string
  /** Attributes for the code surface, such as `data-syntax-palette`. */
  codeProps?: Omit<React.ComponentProps<"pre">, "children" | "className"> & { [attribute: `data-${string}`]: string | undefined }
  /** Controls placed before Copy. */
  actions?: React.ReactNode
  /** Runs after the text reaches the clipboard. */
  onCopy?: (text: string) => void
  labels?: Partial<ProseCodeBlockLabels>
}

/**
 * Code in a document, framed like the docs' code blocks: a shell with the
 * language and Copy, around a panel with the code. It does not highlight
 * syntax itself; pass `renderLine` and `codeClassName`.
 */
function ProseCodeBlock({
  label,
  code,
  renderLine,
  codeClassName,
  codeProps,
  actions,
  onCopy,
  labels: labelsProp,
  className,
  ...props
}: ProseCodeBlockProps) {
  const labels = { ...defaultProseCodeBlockLabels, ...labelsProp }
  const [copyState, setCopyState] = React.useState<"idle" | "copied" | "failed">("idle")
  const resetTimer = React.useRef<number | undefined>(undefined)
  React.useEffect(() => () => window.clearTimeout(resetTimer.current), [])

  const copy = async () => {
    try {
      await navigator.clipboard.writeText(code)
      setCopyState("copied")
      onCopy?.(code)
    } catch {
      setCopyState("failed")
    }
    window.clearTimeout(resetTimer.current)
    resetTimer.current = window.setTimeout(() => setCopyState("idle"), COPIED_MILLISECONDS)
  }

  const lines = code.split("\n")
  return (
    <figure
      data-slot="prose-code-block"
      // `not-prose` keeps a prose around this figure from restyling its code.
      className={cn("not-prose m-0 w-full min-w-0 rounded-[8px] bg-[var(--hui-color-background-neutral-primary)] p-1 text-[var(--hui-color-foreground-base-primary)]", className)}
      {...props}
    >
      <figcaption className="flex min-w-0 items-center gap-[var(--hui-space-2)] py-0.5 ps-2.5 pe-0.5">
        <span className="min-w-0 truncate font-mono text-xs text-[var(--hui-color-foreground-base-secondary)]">{label}</span>
        <div className="ms-auto flex shrink-0 items-center gap-[var(--hui-space-2)]">
          {actions}
          <Button type="button" variant="ghost" size="icon" className="h-6 w-6 rounded" aria-label={labels.copy} onClick={() => void copy()}>
            {copyState === "copied" ? <CheckIcon aria-hidden="true" /> : <CopyIcon aria-hidden="true" />}
          </Button>
        </div>
        <span role="status" className="sr-only">
          {copyState === "copied" ? labels.copied : copyState === "failed" ? labels.copyFailed : ""}
        </span>
      </figcaption>
      {/* Focusable so a keyboard user can scroll long lines. The shell is the frame, so the panel keeps only its hairline. */}
      <pre
        tabIndex={0}
        aria-label={label}
        {...codeProps}
        className={cn(
          "m-0 mt-1 overflow-x-auto rounded-[5px] bg-[var(--hui-color-background-base-primary)] px-4 py-3.5 font-mono text-[0.8125rem] leading-[1.65] shadow-[inset_0_0_0_0.5px_var(--hui-color-border-base-primary)] outline-none focus-visible:[outline:var(--hui-focus-ring)] focus-visible:outline-offset-[var(--hui-focus-ring-offset-inset)]",
          codeClassName,
          "[&&]:border-0! [&&]:rounded-[5px]!"
        )}
      >
        <code className="block w-max min-w-full">
          {lines.map((line, index) => (
            <React.Fragment key={index}>
              {renderLine ? renderLine(line, index) : line}
              {index < lines.length - 1 ? "\n" : null}
            </React.Fragment>
          ))}
        </code>
      </pre>
      {copyState === "failed" && (
        <p className="m-0 px-2.5 pt-1.5 pb-0.5 text-xs">{labels.copyFailed}</p>
      )}
    </figure>
  )
}

export { ProseCodeBlock }

import { createHighlighterCore } from "shiki/core"
import { createOnigurumaEngine } from "shiki/engine/oniguruma"
import type { GrammarState, HighlighterCore, LanguageInput } from "shiki/core"

import { syntaxRoles, syntaxRoleScopes, normalizeLanguage, plainResult, renderTokens } from "@/lib/prose-syntax-shared"
import type { SyntaxToken, SyntaxResult, SyntaxOptions, SyntaxDiagnostic } from "@/lib/prose-syntax-shared"
export * from "@/lib/prose-syntax-shared"
export type HighlighterOptions = {
  languages?: Record<string, () => Promise<LanguageInput>>
  maxBytes?: number
  onDiagnostic?: (diagnostic: SyntaxDiagnostic) => void
}

export const languageLoaders = {
  javascript: () => import("shiki/langs/javascript.mjs"),
  typescript: () => import("shiki/langs/typescript.mjs"),
  jsx: () => import("shiki/langs/jsx.mjs"),
  tsx: () => import("shiki/langs/tsx.mjs"),
  html: () => import("shiki/langs/html.mjs"),
  css: () => import("shiki/langs/css.mjs"),
  json: () => import("shiki/langs/json.mjs"),
  markdown: () => import("shiki/langs/markdown.mjs"),
  bash: () => import("shiki/langs/bash.mjs"),
  python: () => import("shiki/langs/python.mjs"),
  sql: () => import("shiki/langs/sql.mjs"),
  yaml: () => import("shiki/langs/yaml.mjs"),
  java: () => import("shiki/langs/java.mjs"),
  c: () => import("shiki/langs/c.mjs"),
  cpp: () => import("shiki/langs/cpp.mjs"),
  csharp: () => import("shiki/langs/csharp.mjs"),
  go: () => import("shiki/langs/go.mjs"),
  rust: () => import("shiki/langs/rust.mjs"),
  php: () => import("shiki/langs/php.mjs"),
  ruby: () => import("shiki/langs/ruby.mjs"),
  kotlin: () => import("shiki/langs/kotlin.mjs"),
  swift: () => import("shiki/langs/swift.mjs"),
  diff: () => import("shiki/langs/diff.mjs"),
  toml: () => import("shiki/langs/toml.mjs"),
  dockerfile: () => import("shiki/langs/dockerfile.mjs"),
}
// Unique sentinel colors encode roles; actual colors belong exclusively to CSS.
const scopes = syntaxRoles.map(role => syntaxRoleScopes[role])
const roleColors = syntaxRoles.map((_, index) => `#0000${(index + 1).toString(16).padStart(2, "0")}`)
const theme = { name: "honest-roles", colors: { "editor.foreground": roleColors[0], "editor.background": "#ffffff" }, settings: scopes.map((scope, index) => ({ scope, settings: { foreground: roleColors[index], fontStyle: "" } })) }

export function createHighlighter(options: HighlighterOptions = {}) {
  const loaders = { ...languageLoaders, ...options.languages } as Record<string, () => Promise<LanguageInput>>
  let instance: Promise<HighlighterCore> | undefined
  let disposed = false
  const loading = new Map<string, Promise<void>>()
  const sessions = new Map<string, { language: string; prefix: string; lines: SyntaxToken[][]; state?: GrammarState }>()
  const diagnostic = (reason: SyntaxDiagnostic["reason"], language: string) => options.onDiagnostic?.({ reason, language })
  async function highlight(code: string, { language: input, session }: SyntaxOptions = {}): Promise<SyntaxResult> {
    if (disposed) throw new Error("Highlighter has been disposed.")
    const language = normalizeLanguage(input)
    if (new TextEncoder().encode(code).length > (options.maxBytes ?? 200_000)) { diagnostic("too-large", language); return plainResult(code) }
    if (language === "plaintext" || !language) return plainResult(code)
    if (!Object.hasOwn(loaders, language)) { diagnostic("unknown-language", language); return plainResult(code) }
    try {
      instance ??= createHighlighterCore({ themes: [theme], langs: [], engine: createOnigurumaEngine(import("shiki/wasm")) }).catch(error => { instance = undefined; throw error })
      const highlighter = await instance
      if (disposed) return plainResult(code)
      if (!loading.has(language)) {
        const promise = loaders[language]().then(grammar => highlighter.loadLanguage(grammar))
        loading.set(language, promise)
        promise.catch(() => loading.delete(language))
      }
      await loading.get(language)
      if (disposed) return plainResult(code)
      const previous = session ? sessions.get(session) : undefined
      const reusable = previous?.language === language && code.startsWith(previous.prefix) ? previous : undefined
      const prefixLength = reusable?.prefix.length ?? 0
      const split = code.lastIndexOf("\n") + 1
      const convert = (text: string, grammarState?: GrammarState) => {
        const tokens = highlighter.codeToTokensBase(text, { lang: language, theme: "honest-roles", grammarState })
        // Shiki normalizes CRLF. Restore carriage returns so text round-trips exactly.
        const sourceLines = text.split("\n")
        const lines = tokens.map((line, index) => {
          const converted: SyntaxToken[] = line.map(token => ({ text: token.content, role: syntaxRoles[Math.max(0, roleColors.indexOf(token.color ?? ""))] }))
          if (sourceLines[index]?.endsWith("\r") && !converted.map(t => t.text).join("").endsWith("\r")) converted.push({ text: "\r", role: "plain" })
          return converted
        })
        return { lines, state: highlighter.getLastGrammarState(tokens) }
      }
      const complete = split > prefixLength ? convert(code.slice(prefixLength, split), reusable?.state) : undefined
      const lines = [...(reusable?.lines ?? []), ...(complete?.lines.slice(0, -1) ?? [])]
      const state = complete?.state ?? reusable?.state
      const tail = convert(code.slice(split), state)
      if (session) {
        sessions.delete(session)
        sessions.set(session, { language, prefix: code.slice(0, split), lines, state })
        if (sessions.size > 32) sessions.delete(sessions.keys().next().value!)
      }
      const result = { lines: [...lines, ...tail.lines], highlighted: true }
      // A grammar must never be allowed to alter source text.
      if (result.lines.map(line => line.map(t => t.text).join("")).join("\n") !== code) return plainResult(code)
      return result
    } catch {
      diagnostic("load-failed", language)
      return plainResult(code)
    }
  }
  return {
    highlight,
    async toHtml(code: string, options?: SyntaxOptions) {
      return `<pre class="honest-syntax" tabindex="0" aria-label="Code"><code>${renderTokens(await highlight(code, options))}</code></pre>`
    },
    release(session: string) { sessions.delete(session) },
    dispose() { disposed = true; sessions.clear(); loading.clear(); void instance?.then(value => value.dispose()).catch(() => undefined) },
  }
}

import { createSyntaxClient } from "@/lib/prose-syntax-client"
import type { SyntaxClientOptions } from "@/lib/prose-syntax-client"

export function createBrowserHighlighter(options?: SyntaxClientOptions) {
  const client = createSyntaxClient(options)
  const sessions = new WeakMap<HTMLElement, string>()
  const versions = new WeakMap<HTMLElement, number>()
  let sequence = 0
  async function highlightElement(element: HTMLElement) {
    const code = element.matches("code") ? element : element.querySelector("code")
    if (!(code instanceof HTMLElement)) return
    const source = code.textContent ?? ""
    const version = ++sequence
    versions.set(code, version)
    const language = code.dataset.language ?? /(?:^|\s)language-(\S+)/.exec(code.className)?.[1]
    const session = sessions.get(code) ?? `element-${version}`
    sessions.set(code, session)
    const result = await client.highlight(source, { language, session })
    if (versions.get(code) !== version || code.textContent !== source) return
    // Do not destroy an active selection to apply an optional enhancement.
    const selection = code.ownerDocument.getSelection()
    if (selection && !selection.isCollapsed && selection.containsNode(code, true)) return
    const fragment = document.createDocumentFragment()
    result.lines.forEach((line, index) => {
      if (index) fragment.append(document.createTextNode("\n"))
      for (const token of line) {
        const span = document.createElement("span")
        span.className = `prose-syntax-${token.role}`
        span.textContent = token.text
        fragment.append(span)
      }
    })
    code.replaceChildren(fragment)
    const pre = code.closest("pre")
    if (pre) { pre.classList.add("honest-syntax"); if (!pre.hasAttribute("tabindex")) pre.tabIndex = 0; if (!pre.hasAttribute("aria-label")) pre.setAttribute("aria-label", "Code") }
  }
  return {
    highlightElement,
    async highlightAll(root: ParentNode = document) { await Promise.all(Array.from(root.querySelectorAll<HTMLElement>("pre[data-honest-syntax] > code")).map(highlightElement)) },
    dispose: client.dispose,
  }
}
let defaultHighlighter: ReturnType<typeof createBrowserHighlighter> | undefined
export function highlightElement(element: HTMLElement) { return (defaultHighlighter ??= createBrowserHighlighter()).highlightElement(element) }
export function highlightAll(root: ParentNode = document) { return (defaultHighlighter ??= createBrowserHighlighter()).highlightAll(root) }
export function dispose() { defaultHighlighter?.dispose(); defaultHighlighter = undefined }

import { plainResult } from "@/lib/prose-syntax-shared"
import type { SyntaxDiagnostic, SyntaxResult } from "@/lib/prose-syntax-shared"

export type SyntaxClientOptions = {
  workerFactory?: () => Worker
  maxBytes?: number
  timeoutMs?: number
  onDiagnostic?: (diagnostic: SyntaxDiagnostic) => void
}
type Job = { id: number; session: string; code: string; language?: string; resolve: (value: SyntaxResult) => void }

/** One worker and one in-flight request; pending updates coalesce per block. */
export function createSyntaxClient(options: SyntaxClientOptions = {}) {
  let worker: Worker | undefined
  let active: Job | undefined
  let timer: ReturnType<typeof setTimeout> | undefined
  let sequence = 0
  let disposed = false
  const pending = new Map<string, Job>()
  function finish(result: SyntaxResult) {
    clearTimeout(timer)
    active?.resolve(result)
    active = undefined
    pump()
  }
  function fail(reason: "timeout" | "worker-failed") {
    worker?.terminate()
    worker = undefined
    options.onDiagnostic?.({ reason, language: active?.language })
    if (active) finish(plainResult(active.code))
  }
  function pump() {
    if (active || disposed || !pending.size) return
    active = pending.values().next().value!
    pending.delete(active.session)
    try {
      if (!worker) {
        worker = options.workerFactory?.() ?? new Worker(new URL("./prose-syntax-worker.ts", import.meta.url), { type: "module" })
        worker.postMessage({ configure: { maxBytes: options.maxBytes } })
        worker.onmessage = ({ data }) => {
          if (data.id !== active?.id) return
          for (const diagnostic of data.diagnostics ?? []) options.onDiagnostic?.(diagnostic)
          if (data.error) { fail("worker-failed"); return }
          finish(data.result)
        }
        worker.onerror = () => fail("worker-failed")
      }
      const { id, code, language, session } = active
      timer = setTimeout(() => fail("timeout"), options.timeoutMs ?? 1000)
      worker.postMessage({ id, code, language, session })
    } catch { fail("worker-failed") }
  }
  return {
    highlight(code: string, { language, session = "default" }: { language?: string; session?: string } = {}): Promise<SyntaxResult> {
      if (disposed) return Promise.resolve(plainResult(code))
      if (new TextEncoder().encode(code).length > (options.maxBytes ?? 200_000)) {
        options.onDiagnostic?.({ reason: "too-large", language })
        return Promise.resolve(plainResult(code))
      }
      return new Promise(resolve => {
        pending.get(session)?.resolve(plainResult(pending.get(session)!.code))
        pending.set(session, { id: ++sequence, code, language, session, resolve })
        pump()
      })
    },
    release(session: string) {
      const job = pending.get(session)
      if (job) { job.resolve(plainResult(job.code)); pending.delete(session) }
      worker?.postMessage({ release: session })
    },
    dispose() {
      disposed = true
      clearTimeout(timer)
      worker?.terminate()
      active?.resolve(plainResult(active.code))
      active = undefined
      for (const job of pending.values()) job.resolve(plainResult(job.code))
      pending.clear()
    },
  }
}

import { Decoration, EditorView, ViewPlugin, type DecorationSet, type ViewUpdate } from "@codemirror/view"
import { StateEffect, StateField, type Extension, type Range, type Text } from "@codemirror/state"
import { HighlightStyle, syntaxHighlighting, syntaxTree } from "@codemirror/language"
import { tags as t, type Tag } from "@lezer/highlight"
import { semanticTokenRoles, type EditorSyntaxRole, type SyntaxPalette } from "@/lib/prose-syntax-shared"

export { semanticTokenRoles, type EditorSyntaxRole }

/**
 * Which CodeMirror highlight tags take each role. Colors come from
 * `prose-syntax-theme.css` through the `prose-syntax-*` classes, so palettes,
 * themes, and `--prose-syntax-*` overrides apply exactly as they do in Prose.
 */
// Grammars cannot tell a parameter from another variable; parameters come from semantic tokens.
export const codeMirrorRoleTags: Record<Exclude<EditorSyntaxRole, "plain" | "parameter">, Tag[]> = {
  comment: [t.comment, t.lineComment, t.blockComment, t.docComment],
  keyword: [t.keyword, t.controlKeyword, t.definitionKeyword, t.moduleKeyword, t.operatorKeyword, t.modifier, t.self, t.heading],
  string: [t.string, t.special(t.string), t.regexp, t.character, t.link, t.url],
  constant: [t.number, t.integer, t.float, t.bool, t.null, t.atom, t.escape, t.unit, t.color, t.constant(t.variableName), t.labelName],
  function: [t.function(t.variableName), t.function(t.propertyName), t.function(t.definition(t.variableName)), t.macroName, t.annotation, t.meta],
  type: [t.typeName, t.className, t.namespace, t.standard(t.typeName)],
  property: [t.propertyName, t.definition(t.propertyName), t.attributeName],
  tag: [t.tagName],
  punctuation: [t.punctuation, t.separator, t.bracket, t.angleBracket, t.squareBracket, t.paren, t.brace],
  variable: [t.variableName, t.definition(t.variableName), t.local(t.variableName)],
  operator: [t.operator, t.derefOperator, t.arithmeticOperator, t.logicOperator, t.bitwiseOperator, t.compareOperator, t.updateOperator, t.definitionOperator, t.typeOperator, t.controlOperator],
  invalid: [t.invalid],
}

const honestHighlightStyle = HighlightStyle.define([
  ...Object.entries(codeMirrorRoleTags).map(([role, tag]) => ({ tag, class: `prose-syntax-${role}` })),
  // Markup carries meaning in its weight and style, not in a color.
  { tag: t.strong, fontWeight: "600" },
  { tag: t.emphasis, fontStyle: "italic" },
  { tag: t.strikethrough, textDecoration: "line-through" },
  { tag: t.link, textDecoration: "underline" },
])

const role = (name: EditorSyntaxRole) => `var(--prose-syntax-${name}, var(--_syntax-${name}))`
const surface = "var(--prose-syntax-background, var(--_syntax-background))"
const highlight = "var(--prose-syntax-highlight, var(--_syntax-highlight))"
const rule = "var(--prose-syntax-rule, var(--_syntax-rule))"

// Editor chrome, drawn from the same variables as the code so one override restyles both.
const honestEditorTheme = EditorView.theme({
  // The editor scrolls inside `.cm-scroller`, not on its root.
