/** A token from a language server or another analysis, in document positions. */
export type SemanticToken = { from: number; to: number; type: string; modifiers?: readonly string[] }
export type SemanticTokensLegend = { tokenTypes: readonly string[]; tokenModifiers: readonly string[] }


/**
 * Decodes a language server's `textDocument/semanticTokens` result. Each token
 * is five integers: line delta, start delta (from the previous token on the
 * same line), length, type index, and a modifier bit set. Positions are UTF-16
 * code units, as in CodeMirror. Tokens outside the document are dropped.
 */
export function decodeSemanticTokens(data: ArrayLike<number>, legend: SemanticTokensLegend, doc: Text): SemanticToken[] {
  const tokens: SemanticToken[] = []
  let line = 0
  let character = 0
  for (let index = 0; index + 4 < data.length; index += 5) {
    const deltaLine = data[index]
    line += deltaLine
    character = deltaLine === 0 ? character + data[index + 1] : data[index + 1]
    if (line >= doc.lines) break
    const type = legend.tokenTypes[data[index + 3]]
    const docLine = doc.line(line + 1)
    const from = docLine.from + character
    const to = Math.min(docLine.to, from + data[index + 2])
    if (!type || from >= to) continue
    const modifiers = legend.tokenModifiers.filter((_, bit) => data[index + 4] & (1 << bit))
    tokens.push({ from, to, type, modifiers })
  }
  return tokens
}

/** Replaces the editor's semantic tokens. Send it whenever the analysis finishes; edits in between keep tokens in place. */
export const setSemanticTokens = StateEffect.define<readonly SemanticToken[]>()

function semanticDecorations(tokens: readonly SemanticToken[], length: number) {
  const ranges: Range<Decoration>[] = []
  for (const token of tokens) {
    const tokenRole = Object.hasOwn(semanticTokenRoles, token.type) ? semanticTokenRoles[token.type] : undefined
    const classes = [tokenRole && `prose-syntax-${tokenRole}`, token.modifiers?.includes("deprecated") && "prose-syntax-deprecated"].filter(Boolean)
    if (classes.length === 0 || token.from < 0 || token.to > length || token.from >= token.to) continue
    // `prose-syntax-semantic` lets the stylesheet color the grammar spans nested inside it.
    ranges.push(Decoration.mark({ class: ["prose-syntax-semantic", ...classes].join(" ") }).range(token.from, token.to))
  }
  return Decoration.set(ranges, true)
}

const semanticTokenField = StateField.define<DecorationSet>({
  create: () => Decoration.none,
  update(decorations, transaction) {
    let next = decorations.map(transaction.changes)
    for (const effect of transaction.effects) {
      if (effect.is(setSemanticTokens)) next = semanticDecorations(effect.value, transaction.state.doc.length)
    }
    return next
  },
  provide: field => EditorView.decorations.from(field),
})

const invalidMark = Decoration.mark({ class: "prose-syntax-invalid" })

// Marks the grammar's own error nodes in the visible ranges. An error node is
// often empty, so it marks the character beside it to stay visible.
function parseErrorDecorations(view: EditorView) {
  const ranges: Range<Decoration>[] = []
  const { doc } = view.state
  for (const { from, to } of view.visibleRanges) {
    syntaxTree(view.state).iterate({
      from,
      to,
      enter: node => {
        if (!node.type.isError) return
        let start = node.from
        let end = node.to
        if (start === end) {
          const line = doc.lineAt(start)
          if (end < line.to) end += 1
          else if (start > line.from) start -= 1
          else return
        }
        ranges.push(invalidMark.range(start, end))
      },
    })
  }
  return Decoration.set(ranges, true)
}

const parseErrors = ViewPlugin.fromClass(class {
  decorations: DecorationSet
  constructor(view: EditorView) {
    this.decorations = parseErrorDecorations(view)
  }
  update(update: ViewUpdate) {
    if (update.docChanged || update.viewportChanged || syntaxTree(update.startState) !== syntaxTree(update.state)) {
      this.decorations = parseErrorDecorations(update.view)
    }
  }
}, { decorations: plugin => plugin.decorations })

export type HonestCodeMirrorOptions = {
  /** Token palette. Defaults to the stylesheet's default, Violet. */
  palette?: SyntaxPalette
  /** Pins light or dark. Without it, the editor follows `.light`, `.dark`, or the system scheme. */
  theme?: "light" | "dark"
  /** Marks code the grammar cannot parse as invalid. Defaults to true. */
  parseErrors?: boolean
}

/**
 * Honest Prose Syntax colors for a CodeMirror 6 editor. Import
 * `prose-syntax-theme.css` once; this extension maps CodeMirror's tags onto it
 * and styles the gutter, cursor, selection, panels, and lint underlines to match.
 * Send `setSemanticTokens` to color parameters and other semantic types.
 */
export function honestCodeMirror(options: HonestCodeMirrorOptions = {}): Extension {
  const attributes: Record<string, string> = { class: "honest-syntax" }
  if (options.palette) attributes["data-syntax-palette"] = options.palette
  if (options.theme) attributes["data-syntax-theme"] = options.theme
  return [
    EditorView.editorAttributes.of(attributes),
    honestEditorTheme,
    syntaxHighlighting(honestHighlightStyle),
    semanticTokenField,
    options.parseErrors === false ? [] : parseErrors,
  ]
}

"use client"

import * as React from "react"
import { createSyntaxClient } from "@/lib/prose-syntax-client"
import type { SyntaxClientOptions } from "@/lib/prose-syntax-client"
import { plainResult } from "@/lib/prose-syntax-shared"
import type { SyntaxResult, SyntaxToken } from "@/lib/prose-syntax-shared"

let sharedClient: ReturnType<typeof createSyntaxClient> | undefined
let subscribers = 0

export function SyntaxLine({ tokens }: { tokens: SyntaxToken[] }) {
  return tokens.map((token, index) => <span key={index} className={`prose-syntax-${token.role}`}>{token.text}</span>)
}

/** Source stays visible during loading. Results belong to an exact source version. */
export function useSyntax(code: string, language?: string, enabled = true, options?: SyntaxClientOptions) {
  const session = React.useId()
  const [snapshot, setSnapshot] = React.useState<{ code: string; language?: string; result: SyntaxResult }>()
  const client = React.useRef<ReturnType<typeof createSyntaxClient> | undefined>(undefined)
  React.useEffect(() => {
    if (!enabled || !language) return
    const instance = options ? createSyntaxClient(options) : (sharedClient ??= createSyntaxClient())
    if (!options) subscribers++
    client.current = instance
    return () => {
      instance.release(session)
      if (options) instance.dispose()
      else if (--subscribers === 0) { sharedClient?.dispose(); sharedClient = undefined }
      client.current = undefined
    }
  }, [enabled, language, options, session])
  React.useEffect(() => {
    if (!enabled || !language || !client.current) return
    let current = true
    let ready: SyntaxResult | undefined
    const apply = () => {
      if (current && ready && (!document.getSelection() || document.getSelection()!.isCollapsed)) setSnapshot({ code, language, result: ready })
    }
    document.addEventListener("selectionchange", apply)
    void client.current.highlight(code, { language, session }).then(result => { ready = result; apply() })
    return () => { current = false; document.removeEventListener("selectionchange", apply) }
  }, [code, language, enabled, session, options])
  if (!enabled || !snapshot || snapshot.language !== language) return undefined
  if (snapshot.code === code) return snapshot.result
  // Keep completed lines colored while an appended suffix is being processed.
  if (code.startsWith(snapshot.code)) {
    const boundary = snapshot.code.lastIndexOf("\n") + 1
    const count = snapshot.code.slice(0, boundary).split("\n").length - 1
    return { lines: [...snapshot.result.lines.slice(0, count), ...plainResult(code.slice(boundary)).lines], highlighted: snapshot.result.highlighted }
  }
  return undefined
}

export function SyntaxCode({ code, language, ...props }: { code: string; language?: string } & React.ComponentProps<"pre">) {
  const result = useSyntax(code, language)
  return <pre tabIndex={0} aria-label="Code" {...props} className={`honest-syntax ${props.className ?? ""}`}><code>{result ? result.lines.map((tokens, index) => <React.Fragment key={index}>{index > 0 && "\n"}<SyntaxLine tokens={tokens} /></React.Fragment>) : code}</code></pre>
}

export type SyntaxPalette = "violet" | "graphite"
export const syntaxRoles = ["plain", "comment", "keyword", "string", "constant", "function", "type", "property", "tag", "punctuation"] as const
export type SyntaxRole = (typeof syntaxRoles)[number]
/** Roles an editor needs beyond reading: names, parameters, operators, and code that does not parse. */
export type EditorSyntaxRole = SyntaxRole | "variable" | "parameter" | "operator" | "invalid"
/** Language Server Protocol token types, by role. Unlisted types keep the grammar's color. */
export const semanticTokenRoles: Record<string, EditorSyntaxRole> = {
  namespace: "type", type: "type", class: "type", enum: "type", interface: "type", struct: "type", typeParameter: "type",
  parameter: "parameter", variable: "variable", property: "property", enumMember: "constant", event: "property",
  function: "function", method: "function", macro: "function", decorator: "function",
  keyword: "keyword", modifier: "keyword", comment: "comment", string: "string", number: "constant", regexp: "string", operator: "operator",
}
/** The TextMate scopes each role colors. Shared by the Shiki engine and the VS Code theme. */
export const syntaxRoleScopes: Record<SyntaxRole, string[]> = {
  plain: [],
  comment: ["comment"],
  keyword: ["keyword", "storage"],
  string: ["string"],
  constant: ["constant"],
  function: ["entity.name.function", "support.function"],
  type: ["entity.name.type", "entity.name.class", "support.type", "support.class"],
  property: ["variable.other.property", "support.type.property-name", "entity.other.attribute-name"],
  tag: ["entity.name.tag"],
  punctuation: ["punctuation"],
}
export type SyntaxToken = { text: string; role: SyntaxRole }
export type SyntaxResult = { lines: SyntaxToken[][]; highlighted: boolean }
export type SyntaxDiagnostic = { reason: "unknown-language" | "load-failed" | "too-large" | "timeout" | "worker-failed"; language?: string }
export type SyntaxOptions = { language?: string; session?: string }

// Short names people write in fences, and the grammar each one means.
const aliases: Record<string, string> = { js: "javascript", ts: "typescript", sh: "bash", shell: "bash", zsh: "bash", py: "python", yml: "yaml", md: "markdown", text: "plaintext", txt: "plaintext", "c++": "cpp", cc: "cpp", h: "c", hpp: "cpp", cs: "csharp", "c#": "csharp", golang: "go", rs: "rust", rb: "ruby", kt: "kotlin", kts: "kotlin", patch: "diff", docker: "dockerfile" }
export function normalizeLanguage(language = "plaintext") {
  const value = language.trim().toLowerCase()
  return Object.hasOwn(aliases, value) ? aliases[value] : value
}

// How people write each language's name. Shell aliases keep their own name, since `zsh` is not Bash.
const displayNames: Record<string, string> = {
  javascript: "JavaScript", typescript: "TypeScript", jsx: "JSX", tsx: "TSX", html: "HTML", css: "CSS", json: "JSON",
  markdown: "Markdown", bash: "Bash", sh: "Shell", shell: "Shell", zsh: "Zsh", python: "Python", sql: "SQL", yaml: "YAML",
  java: "Java", c: "C", cpp: "C++", csharp: "C#", go: "Go", rust: "Rust", php: "PHP", ruby: "Ruby", kotlin: "Kotlin",
  swift: "Swift", diff: "Diff", toml: "TOML", dockerfile: "Dockerfile", plaintext: "Text",
}

/** A fence's language as people write it, such as "C++" for `cpp`. Unknown languages are returned as written. */
export function languageDisplayName(language: string) {
  const value = language.trim().toLowerCase()
  if (Object.hasOwn(displayNames, value)) return displayNames[value]
  const canonical = normalizeLanguage(value)
  return Object.hasOwn(displayNames, canonical) ? displayNames[canonical] : language.trim()
}

export function plainResult(code: string): SyntaxResult {
  return { lines: code.split("\n").map(text => [{ text, role: "plain" }]), highlighted: false }
}
export function escapeHtml(text: string) {
  return text.replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;").replaceAll("'", "&#39;")
}
export function renderTokens(result: SyntaxResult) {
  return result.lines.map(line => line.map(token => `<span class="prose-syntax-${token.role}">${escapeHtml(token.text)}</span>`).join("")).join("\n")
}

