  --_syntax-palette-invalid-dark: #f97066;
  --_syntax-palette-parameter-dark: #c8b4cc;
}
.honest-syntax .prose-syntax-plain { color: var(--prose-syntax-plain, var(--_syntax-plain)); }
.honest-syntax .prose-syntax-comment { color: var(--prose-syntax-comment, var(--_syntax-comment)); }
.honest-syntax .prose-syntax-keyword { color: var(--prose-syntax-keyword, var(--_syntax-keyword)); }
.honest-syntax .prose-syntax-string { color: var(--prose-syntax-string, var(--_syntax-string)); }
.honest-syntax .prose-syntax-constant { color: var(--prose-syntax-constant, var(--_syntax-constant)); }
.honest-syntax .prose-syntax-function { color: var(--prose-syntax-function, var(--_syntax-function)); }
.honest-syntax .prose-syntax-type { color: var(--prose-syntax-type, var(--_syntax-type)); }
.honest-syntax .prose-syntax-property { color: var(--prose-syntax-property, var(--_syntax-property)); }
.honest-syntax .prose-syntax-tag { color: var(--prose-syntax-tag, var(--_syntax-tag)); }
.honest-syntax .prose-syntax-punctuation { color: var(--prose-syntax-punctuation, var(--_syntax-punctuation)); }
/* Editor roles, used by the editor themes. Parameters are italic and invalid code is underlined, so neither is marked by color alone. */
.honest-syntax .prose-syntax-variable { color: var(--prose-syntax-variable, var(--_syntax-variable)); }
.honest-syntax .prose-syntax-operator { color: var(--prose-syntax-operator, var(--_syntax-operator)); }
.honest-syntax .prose-syntax-parameter { color: var(--prose-syntax-parameter, var(--_syntax-parameter)); font-style: italic; }
/* A semantic modifier from a language server, layered on a role. */
.honest-syntax .prose-syntax-deprecated { text-decoration: line-through; }
/* A semantic token knows more than the grammar, so grammar spans nested inside it take its color. */
.honest-syntax .prose-syntax-semantic [class*="prose-syntax-"]:not(.prose-syntax-invalid) { color: inherit; }
.honest-syntax .prose-syntax-invalid { color: var(--prose-syntax-invalid, var(--_syntax-invalid)); text-decoration: underline wavy; text-decoration-skip-ink: none; }
.honest-syntax [data-highlighted-line] { background: var(--prose-syntax-highlight, var(--_syntax-highlight)); }
.honest-syntax ::selection { color: HighlightText; background: Highlight; }
.honest-syntax:focus-visible { outline: 2px solid currentColor; outline-offset: -2px; }
@media (forced-colors: active) {
  .honest-syntax { color: CanvasText; background: Canvas; border-color: CanvasText; box-shadow: none; }
  .honest-syntax [class*="prose-syntax-"] { color: CanvasText; }
  .honest-syntax [data-highlighted-line] { outline: 1px solid Highlight; }
}

import { syntaxPaletteColors } from "@/lib/prose-syntax-palettes"
import { semanticTokenRoles, syntaxRoleScopes, syntaxRoles, type EditorSyntaxRole, type SyntaxPalette } from "@/lib/prose-syntax-shared"

export type SyntaxMode = "light" | "dark"
type Colors = Record<EditorSyntaxRole | "background" | "highlight" | "frame" | "rule", string>

const paletteLabels: Record<SyntaxPalette, string> = { violet: "Violet", graphite: "Graphite" }

function colorsFor(palette: SyntaxPalette, mode: SyntaxMode): Colors {
  return syntaxPaletteColors[palette][mode]
}

// The stylesheet mixes selection and the active line with CSS; editors that
// take literal colors get the same mixes, in sRGB, with alpha where they allow it.
function mix(color: string, base: string, weight: number) {
  const channel = (hex: string, index: number) => parseInt(hex.slice(1 + index * 2, 3 + index * 2), 16)
  return `#${[0, 1, 2].map(index => Math.round(channel(color, index) * weight + channel(base, index) * (1 - weight)).toString(16).padStart(2, "0")).join("")}`
}

function chrome(colors: Colors) {
  return {
    "editor.background": colors.background,
    "editor.foreground": colors.plain,
    "editorCursor.foreground": colors.plain,
    "editor.selectionBackground": mix(colors.keyword, colors.background, 0.28),
    "editor.lineHighlightBackground": `${colors.highlight}8c`,
    "editorLineNumber.foreground": colors.comment,
    "editorLineNumber.activeForeground": colors.plain,
    "editorGutter.background": colors.background,
    "editorBracketMatch.background": colors.highlight,
    "editorBracketMatch.border": colors.rule,
    "editorIndentGuide.background1": colors.rule,
    "editorWhitespace.foreground": colors.rule,
    "editorWidget.background": colors.background,
    "editorWidget.border": colors.rule,
    "editorError.foreground": colors.invalid,
    "editorWarning.foreground": colors.constant,
    "editorInfo.foreground": colors.function,
  }
}

type SemanticStyle = string | { foreground?: string; italic?: boolean; strikethrough?: boolean }

export type VSCodeTheme = {
  name: string
  type: SyntaxMode
  semanticHighlighting: true
  colors: Record<string, string>
  tokenColors: { scope: string[]; settings: { foreground?: string; fontStyle?: string } }[]
  semanticTokenColors: Record<string, SemanticStyle>
}

/** A VS Code color theme, for an extension's `contributes.themes`. Semantic highlighting colors parameters. */
export function vscodeTheme(palette: SyntaxPalette = "violet", mode: SyntaxMode = "light"): VSCodeTheme {
  const colors = colorsFor(palette, mode)
  return {
    name: `Honest ${paletteLabels[palette]} ${mode === "light" ? "Light" : "Dark"}`,
    type: mode,
    semanticHighlighting: true,
    colors: chrome(colors),
    // TextMate picks the most specific matching scope, so order here does not matter.
    tokenColors: [
      ...syntaxRoles.filter(role => role !== "plain").map(role => ({ scope: syntaxRoleScopes[role], settings: { foreground: colors[role] } })),
      { scope: ["variable"], settings: { foreground: colors.variable } },
      { scope: ["variable.parameter"], settings: { foreground: colors.parameter, fontStyle: "italic" } },
      { scope: ["keyword.operator"], settings: { foreground: colors.operator } },
      { scope: ["invalid", "invalid.illegal"], settings: { foreground: colors.invalid, fontStyle: "underline" } },
      { scope: ["markup.bold"], settings: { fontStyle: "bold" } },
      { scope: ["markup.italic"], settings: { fontStyle: "italic" } },
      { scope: ["markup.strikethrough"], settings: { fontStyle: "strikethrough" } },
    ],
    semanticTokenColors: {
      ...Object.fromEntries(Object.entries(semanticTokenRoles).map(([type, role]) => [type, role === "parameter" ? { foreground: colors.parameter, italic: true } : colors[role]])),
      "*.deprecated": { strikethrough: true },
    },
  }
}

// Monaco's built-in (Monarch) grammars name tokens differently from TextMate.
const monacoTokens: Partial<Record<EditorSyntaxRole, string[]>> = {
  comment: ["comment"],
  keyword: ["keyword"],
  string: ["string", "attribute.value", "regexp"],
  constant: ["number", "constant"],
  function: ["predefined", "annotation"],
  type: ["type", "type.identifier"],
  property: ["attribute.name", "key"],
  tag: ["tag", "metatag"],
  punctuation: ["delimiter"],
  variable: ["identifier", "variable"],
  operator: ["operator", "operators"],
  invalid: ["invalid"],
}

/** Data for `monaco.editor.defineTheme`. Enable `"semanticHighlighting.enabled"` to color parameters from a language service. */
export function monacoTheme(palette: SyntaxPalette = "violet", mode: SyntaxMode = "light") {
  const colors = colorsFor(palette, mode)
  const foreground = (role: EditorSyntaxRole) => colors[role].slice(1)
  return {
    base: mode === "light" ? "vs" : "vs-dark",
    inherit: true,
    rules: [
      { token: "", foreground: foreground("plain"), background: colors.background.slice(1) },
      ...Object.entries(monacoTokens).flatMap(([role, tokens]) => tokens.map(token => ({ token, foreground: foreground(role as EditorSyntaxRole), ...(role === "invalid" ? { fontStyle: "underline" } : {}) }))),
      // Semantic token types, as Monaco names them when semantic highlighting is on.
      ...Object.entries(semanticTokenRoles).map(([type, role]) => ({ token: type, foreground: foreground(role), ...(role === "parameter" ? { fontStyle: "italic" } : {}) })),
    ],
    colors: chrome(colors),
  } as const
}

import { createHighlighter } from "@/lib/prose-syntax"
import type { SyntaxDiagnostic } from "@/lib/prose-syntax-shared"

const scope = globalThis as unknown as {
  onmessage: ((event: MessageEvent) => void) | null
  postMessage: (message: unknown) => void
}
const diagnostics: SyntaxDiagnostic[] = []
let highlighter = createHighlighter({ onDiagnostic: diagnostic => diagnostics.push(diagnostic) })
let queue = Promise.resolve()
scope.onmessage = ({ data }) => {
  queue = queue.then(async () => {
    if (data.configure) { highlighter.dispose(); highlighter = createHighlighter({ maxBytes: data.configure.maxBytes, onDiagnostic: diagnostic => diagnostics.push(diagnostic) }); return }
    if (data.release) { highlighter.release(data.release); return }
    const { id, code, language, session } = data
    diagnostics.length = 0
    const result = await highlighter.highlight(code, { language, session })
    scope.postMessage({ id, result, diagnostics: [...diagnostics] })
  }).catch(() => scope.postMessage({ id: data.id, error: true }))
}

"use client"

import * as React from "react"
import {
  CircleAlert as CircleAlertIcon,
  CircleCheck as CircleCheckIcon,
  LoaderCircle as LoaderCircleIcon,
} from "honestui/icons"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import {
  Collapsible,
  CollapsiblePanel,
  CollapsibleTrigger,
} from "@/components/ui/collapsible"

export type RecommendationOption = {
  id: string
  /** The recommendation in full, shown while this option is selected. */
  body: React.ReactNode
  /** One line for the list of alternatives. */
  summary: string
  /** How strong the evidence is, from 0 (none) to 3 (high). */
  confidence: 0 | 1 | 2 | 3
  /** The confidence in words, such as "High confidence". Always shown beside the meter. */
  confidenceLabel: string
  /** The accept button's text for this option. */
  actionLabel: string
}

export type RecommendationCardLabels = {
  alternatives: string
  otherOptions: string
  accepting: string
  accepted: string
  error: string
}

export const defaultRecommendationCardLabels: RecommendationCardLabels = {
  alternatives: "Alternatives",
  otherOptions: "Other options",
  accepting: "Working…",
  accepted: "Accepted.",
  error: "This was not accepted. Try again.",
}

const smallText =
  "[font-size:var(--hui-font-size-small)] [letter-spacing:var(--hui-letter-spacing-small)] [line-height:var(--hui-line-height-small)]"

function ConfidenceMeter({ level }: { level: number }) {
  return (
    <span aria-hidden="true" className="flex shrink-0 items-end gap-0.5">
      {[1, 2, 3].map((bar) => (
        <span
          key={bar}
          className={cn(
            "h-2.5 w-1 rounded-full",
            bar <= level
              ? "bg-[var(--hui-color-foreground-base-primary)]"
              : "bg-[var(--hui-color-border-base-secondary)]"
          )}
        />
      ))}
    </span>
  )
}

export type RecommendationCardProps = Omit<React.ComponentProps<"div">, "children" | "title"> & {
  /** The question the agent is asking, such as "Place this restock order?". */
  title: string
  /** The first option is the recommendation. The rest are alternatives. */
  options: RecommendationOption[]
  /**
   * Receives the chosen option. Return a promise to show progress; if it
   * rejects, the card shows an error and the choice can be made again.
   */
  onAccept: (option: RecommendationOption) => void | Promise<void>
  labels?: Partial<RecommendationCardLabels>
}

/**
 * One recommended action with its confidence stated, and the alternatives a
 * press away. Nothing happens until the person accepts an option.
 */
function RecommendationCard({
  title,
  options,
  onAccept,
  labels: labelsProp,
  className,
  ...props
}: RecommendationCardProps) {
  const labels = React.useMemo(
    () => ({ ...defaultRecommendationCardLabels, ...labelsProp }),
    [labelsProp]
  )
  const [selectedId, setSelectedId] = React.useState(options[0]?.id)
  const [phase, setPhase] = React.useState<"idle" | "accepting" | "accepted" | "error">("idle")
  const selected = options.find((option) => option.id === selectedId) ?? options[0]
  const others = options.filter((option) => option !== selected)
  const isLocked = phase === "accepting" || phase === "accepted"

  if (!selected) return null

  const accept = async () => {
    setPhase("accepting")
    try {
      await onAccept(selected)
      setPhase("accepted")
    } catch {
      setPhase("error")
    }
  }

  return (
    <div
      data-slot="recommendation-card"
      data-phase={phase}
      className={cn(
        "w-full min-w-0 overflow-hidden rounded-[var(--hui-radius-4)] border-[0.5px] border-[var(--hui-color-border-base-primary)] bg-[var(--hui-color-background-base-primary)] text-[var(--hui-color-foreground-base-primary)] shadow-[var(--hui-shadow-soft)]",
        smallText,
        className
      )}
      {...props}
    >
      <Collapsible>
        <div className="flex flex-col gap-[var(--hui-space-3)] p-[var(--hui-space-5)]">
          <p className="m-0 break-words [font-size:var(--hui-font-size-regular)] [font-weight:var(--hui-font-weight-medium)] [letter-spacing:var(--hui-letter-spacing-regular)] [line-height:var(--hui-line-height-regular)]">
            {title}
          </p>
          <div
            aria-live="polite"
            className="break-words text-[var(--hui-color-foreground-base-secondary)] [line-height:var(--hui-line-height-regular)]"
          >
            {selected.body}
          </div>
          <p className="m-0 flex items-center gap-[var(--hui-space-3)] text-[var(--hui-color-foreground-base-secondary)]">
            <ConfidenceMeter level={selected.confidence} />
            {selected.confidenceLabel}
          </p>
        </div>

        {others.length > 0 && (
          <CollapsiblePanel>
            <div className="border-t-[0.5px] border-[var(--hui-color-border-base-primary)] p-[var(--hui-space-3)]">
              <p className="m-0 px-[var(--hui-space-2)] pb-[var(--hui-space-2)] text-[var(--hui-color-foreground-base-secondary)] [font-size:var(--hui-font-size-mini)]">
                {labels.otherOptions}
              </p>
              <ul role="list" className="m-0 flex list-none flex-col p-0">
                {others.map((option) => (
                  <li key={option.id}>
                    <button
                      type="button"
                      disabled={isLocked}
                      onClick={() => {
                        setSelectedId(option.id)
                        setPhase("idle")
                      }}
                      className="flex w-full cursor-pointer items-center gap-[var(--hui-space-3)] rounded-[var(--hui-radius-2)] border-0 bg-transparent px-[var(--hui-space-2)] py-[var(--hui-space-3)] text-left outline-none motion-safe:[transition:var(--hui-transition-interactive)] hover:bg-[var(--hui-color-background-base-primary-hover)] focus-visible:[outline:var(--hui-focus-ring)] disabled:cursor-not-allowed disabled:opacity-50"
                    >
                      <ConfidenceMeter level={option.confidence} />
                      <span className="min-w-0 flex-1 break-words">{option.summary}</span>
                      <span className="shrink-0 text-[var(--hui-color-foreground-base-secondary)] [font-size:var(--hui-font-size-mini)]">
                        {option.confidenceLabel}
                      </span>
                    </button>
                  </li>
                ))}
              </ul>
            </div>
          </CollapsiblePanel>
        )}

        <div className="flex flex-wrap items-center justify-end gap-[var(--hui-space-3)] border-t-[0.5px] border-[var(--hui-color-border-base-primary)] px-[var(--hui-space-5)] py-[var(--hui-space-3)]">
          <p
            role={phase === "error" ? "alert" : "status"}
            className="m-0 me-auto flex min-w-0 items-center gap-[var(--hui-space-2)]"
          >
            {phase === "accepted" && (
              <>
                <CircleCheckIcon
                  aria-hidden="true"
                  className="size-3.5 shrink-0 text-[var(--hui-color-foreground-success-primary)]"
                />
                {labels.accepted}
              </>
            )}
            {phase === "error" && (
              <>
                <CircleAlertIcon strokeWidth={1.5} strokeLinecap="round"
                  aria-hidden="true"
                  className="size-3.5 shrink-0 text-[var(--hui-color-foreground-danger-primary)]"
                />
                {labels.error}
              </>
            )}
          </p>
          {others.length > 0 && (
            <CollapsibleTrigger render={<Button variant="secondary" size="sm" />}>
              {labels.alternatives}
            </CollapsibleTrigger>
          )}
          <Button size="sm" disabled={isLocked} onClick={() => void accept()}>
            {phase === "accepting" && (
              <LoaderCircleIcon aria-hidden="true" className="size-3.5 motion-safe:animate-spin" />
            )}
            {phase === "accepting" ? labels.accepting : selected.actionLabel}
          </Button>
        </div>
      </Collapsible>
    </div>
  )
}

export { RecommendationCard }

"use client"

import * as React from "react"
import {
  CircleAlert as CircleAlertIcon,
  LoaderCircle as LoaderCircleIcon,
  Sparkles as SparklesIcon,
} from "honestui/icons"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"

export type RecordsTableColumn = {
  id: string
  header: string
  /** Marks a column whose cells an agent fills in. */
  isGenerated?: boolean
}

export type GeneratedCell =
  | { status: "queued" }
  | { status: "running" }
  | { status: "done"; value: React.ReactNode }
  | { status: "error"; message?: string }

export type RecordsTableRow = {
  id: string
  /** Names the row in button labels, such as the record's title. */
  name: string
  /** The cell for each ordinary column `id`. */
  cells: Record<string, React.ReactNode>
  /** The state of each generated column `id`. A missing entry reads as queued. */
  generated?: Record<string, GeneratedCell>
}

export type RecordsTableLabels = {
  generated: string
  queued: string
  running: string
  failed: string
  retry: string
  retryCell: (column: string, row: string) => string
  progress: (done: number, total: number) => string
}

export const defaultRecordsTableLabels: RecordsTableLabels = {
  generated: "Generated",
  queued: "Queued",
  running: "Working…",
  failed: "Failed",
  retry: "Retry",
  retryCell: (column, row) => `Retry ${column} for ${row}`,
  progress: (done, total) => `${done} of ${total} generated cells done`,
}

export type RecordsTableProps = {
  /** Names the table for screen readers. */
  label: string
  columns: RecordsTableColumn[]
  rows: RecordsTableRow[]
  /** Passing it shows Retry in every failed cell. */
  onRetry?: (rowId: string, columnId: string) => void
  labels?: Partial<RecordsTableLabels>
  className?: string
}

/**
 * A table of records where some columns are filled in by an agent, cell by
 * cell. Each generated cell shows the state you pass for it: queued, running,
 * done with a value, or failed.
 */
function RecordsTable({
  label,
  columns,
  rows,
  onRetry,
  labels: labelsProp,
  className,
}: RecordsTableProps) {
  const labels = { ...defaultRecordsTableLabels, ...labelsProp }
  const generatedColumns = columns.filter((column) => column.isGenerated)
  const total = generatedColumns.length * rows.length
  const done = rows.reduce(
    (count, row) =>
      count +
      generatedColumns.filter((column) => row.generated?.[column.id]?.status === "done").length,
    0
  )

  return (
    <div data-slot="records-table" className={cn("flex w-full min-w-0 flex-col gap-[var(--hui-space-3)]", className)}>
      <Table variant="surface" aria-label={label}>
        <TableHeader>
          <TableRow>
            {columns.map((column) => (
              <TableHead key={column.id} scope="col">
                <span className="flex items-center gap-[var(--hui-space-2)]">
                  {column.isGenerated && (
                    <>
                      <SparklesIcon aria-hidden="true" className="size-3.5 shrink-0" />
                      <span className="sr-only">{labels.generated}: </span>
                    </>
                  )}
                  {column.header}
                </span>
              </TableHead>
            ))}
          </TableRow>
        </TableHeader>
        <TableBody>
          {rows.map((row) => (
            <TableRow key={row.id}>
              {columns.map((column) => (
                <TableCell key={column.id} data-generated={column.isGenerated ? "" : undefined}>
                  {column.isGenerated ? (
                    <GeneratedCellContent
                      cell={row.generated?.[column.id] ?? { status: "queued" }}
                      labels={labels}
                      retryLabel={labels.retryCell(column.header, row.name)}
                      onRetry={onRetry ? () => onRetry(row.id, column.id) : undefined}
                    />
                  ) : (
                    row.cells[column.id]
                  )}
                </TableCell>
              ))}
            </TableRow>
          ))}
        </TableBody>
      </Table>
      {total > 0 && (
        // Announced as the count changes, so progress is heard without reading every cell.
        <p
          role="status"
          className="m-0 text-[var(--hui-color-foreground-base-secondary)] [font-size:var(--hui-font-size-small)] [line-height:var(--hui-line-height-small)]"
        >
          {labels.progress(done, total)}
        </p>
      )}
    </div>
  )
}

function GeneratedCellContent({
  cell,
  labels,
  retryLabel,
  onRetry,
}: {
  cell: GeneratedCell
  labels: RecordsTableLabels
  retryLabel: string
  onRetry?: () => void
}) {
  if (cell.status === "done") return <>{cell.value}</>

  if (cell.status === "error") {
    return (
      <span className="flex min-w-0 flex-wrap items-center gap-[var(--hui-space-2)]">
        <CircleAlertIcon strokeWidth={1.5} strokeLinecap="round"
          aria-hidden="true"
          className="size-3.5 shrink-0 text-[var(--hui-color-foreground-danger-primary)]"
        />
        <span className="min-w-0 break-words">{cell.message ?? labels.failed}</span>
        {onRetry && (
          <Button variant="secondary" size="xs" aria-label={retryLabel} onClick={onRetry}>
            {labels.retry}
          </Button>
        )}
      </span>
    )
  }

  return (
    <span className="flex items-center gap-[var(--hui-space-2)] text-[var(--hui-color-foreground-base-secondary)]">
      {cell.status === "running" && (
        <LoaderCircleIcon aria-hidden="true" className="size-3.5 shrink-0 motion-safe:animate-spin" />
      )}
      {cell.status === "running" ? labels.running : labels.queued}
    </span>
  )
}

export { RecordsTable }

const FENCE = /^ {0,3}(`{3,}|~{3,})/

// A link or image whose target has not finished arriving: `[label](https://exa`.
const PARTIAL_LINK = /(!?)\[([^\]\n]*)\]\([^)\s]*$/

const isSpace = (char: string | undefined) => char === undefined || /\s/.test(char)
const isWordCharacter = (char: string | undefined) => char !== undefined && /[\p{L}\p{N}]/u.test(char)

/** Reads one block's inline syntax and reports what is still open at its end. */
function scanInline(text: string) {
  // Emphasis markers waiting for their closer, outermost first.
  const open: string[] = []
  let codeMarker: string | null = null
  let codeStart = 0
  const codeSpans: [start: number, end: number][] = []
  // Where a marker that ends the text, and closes nothing, begins.
  let danglingAt = -1

  let index = 0
  while (index < text.length) {
    const char = text[index]

    if (char === "`") {
      let end = index
      while (text[end] === "`") end += 1
      const run = text.slice(index, end)
      if (codeMarker === null) {
        codeMarker = run
        codeStart = index
      } else if (codeMarker === run) {
        codeMarker = null
        codeSpans.push([codeStart, end])
      }
      index = end
      continue
    }

    if (codeMarker !== null) {
      index += 1
      continue
    }

    if (char === "\\") {
      index += 2
      continue
    }

    if (char === "*" || char === "_" || char === "~") {
      let end = index
      while (text[end] === char) end += 1
      const length = end - index
      const before = text[index - 1]
      const after = text[end]
      // An underscore inside a word, as in snake_case, is not emphasis.
      const canOpen = !isSpace(after) && !(char === "_" && isWordCharacter(before))
      const canClose = !isSpace(before) && !(char === "_" && isWordCharacter(after))
      const markers =
        char === "~"
          ? length === 2 ? ["~~"] : []
          : length === 1 ? [char] : length === 2 ? [char + char] : [char + char, char]

      let closedAny = false
      for (const marker of markers) {
        const position = canClose ? open.lastIndexOf(marker) : -1
        if (position !== -1) {
          // Markers opened after this one were never closed, so they are literal.
          open.length = position
          closedAny = true
        } else if (canOpen) {
          open.push(marker)
        }
      }
      if (after === undefined && !closedAny) danglingAt = index
      index = end
      continue
    }

    index += 1
  }

  return { open, codeMarker, codeStart, codeSpans, danglingAt }
}

/** Closes the inline syntax a block has opened but not yet finished. */
function closeInline(block: string) {
  let text = block
  let state = scanInline(text)

  if (state.codeMarker !== null) {
    const opener = state.codeStart + state.codeMarker.length
    // Backticks with nothing after them yet would only flash as literal text.
    if (opener >= text.length) return text.slice(0, state.codeStart)
    // Drop a closer that has half arrived, then close the span.
    return text.replace(/`+$/, "") + state.codeMarker
  }

  const link = PARTIAL_LINK.exec(text)
  if (link && !state.codeSpans.some(([start, end]) => link.index >= start && link.index < end)) {
    // An image has nothing to show yet. A link can already show its label.
    text = text.slice(0, link.index) + (link[1] ? "" : link[2])
    state = scanInline(text)
  }

  if (state.danglingAt !== -1) text = text.slice(0, state.danglingAt)
  if (state.open.length === 0) return text

  // A closer after a space does not close, so it goes before any trailing space.
  const body = text.trimEnd()
  return body + [...state.open].reverse().join("") + text.slice(body.length)
}

/**
 * Makes Markdown that is still arriving parse the way it will once it is
 * whole. Only the last block can be unfinished, so only it is changed: open
 * bold, italic, strikethrough, and inline code are closed, and a link or image
 * whose target has not arrived yet is held back. Finished text is not touched.
 */
export function repairMarkdown(source: string) {
  const lines = source.split("\n")
  let fenceMarker: string | null = null
  let lastBlockStart = 0

  lines.forEach((line, index) => {
    const marker = FENCE.exec(line)?.[1]
    if (marker && fenceMarker === null) {
      fenceMarker = marker
      lastBlockStart = index + 1
    } else if (
      marker &&
      fenceMarker !== null &&
      marker[0] === fenceMarker[0] &&
      marker.length >= fenceMarker.length &&
      line.trim() === marker
    ) {
      fenceMarker = null
      lastBlockStart = index + 1
    } else if (fenceMarker === null && line.trim() === "") {
      lastBlockStart = index + 1
    }
  })

  // An open code fence runs to the end of the text, which is how a parser reads it too.
  if (fenceMarker !== null || lastBlockStart >= lines.length) return source

  const finished = lines.slice(0, lastBlockStart)
  const lastBlock = lines.slice(lastBlockStart).join("\n")
  return [...finished, closeInline(lastBlock)].join("\n")
}

