export type SelectionAction = {
  id: string
  label: string
  icon?: React.ReactNode
}

export type SelectionActionsStatus = "idle" | "working" | "result" | "error"

export type SelectionActionsLabels = {
  toolbar: string
  prompt: string
  promptPlaceholder: string
  send: string
  working: string
  keep: string
  discard: string
  retry: string
  error: string
}

export const defaultSelectionActionsLabels: SelectionActionsLabels = {
  toolbar: "Edit selection",
  prompt: "Describe an edit",
  promptPlaceholder: "Describe an edit…",
  send: "Send",
  working: "Working…",
  keep: "Keep",
  discard: "Discard",
  retry: "Try again",
  error: "The edit did not finish.",
}

const smallText =
  "[font-size:var(--hui-font-size-small)] [letter-spacing:var(--hui-letter-spacing-small)] [line-height:var(--hui-line-height-small)]"

export type SelectionActionsProps = Omit<React.ComponentProps<"div">, "children"> & {
  /** One button each, such as Improve and Shorten. */
  actions: SelectionAction[]
  /** Where the edit stands. Your application sets it. */
  status?: SelectionActionsStatus
  onAction: (actionId: string) => void
  /** Passing it adds a field for a typed instruction. */
  onPrompt?: (instruction: string) => void
  /** Accepts the result. */
  onKeep: () => void
  /** Rejects the result, or dismisses an error. */
  onDiscard: () => void
  /** Passing it offers another attempt on a result or an error. */
  onRetry?: () => void
  labels?: Partial<SelectionActionsLabels>
}

/**
 * A bar of AI edits for a piece of selected text. It offers the actions,
 * shows progress, and then asks the person to keep or discard the result.
 * Tracking the selection, placing the bar, and making the edit are yours.
 */
function SelectionActions({
  actions,
  status = "idle",
  onAction,
  onPrompt,
  onKeep,
  onDiscard,
  onRetry,
  labels: labelsProp,
  className,
  ...props
}: SelectionActionsProps) {
  const labels = { ...defaultSelectionActionsLabels, ...labelsProp }
  const [instruction, setInstruction] = React.useState("")
  const trimmed = instruction.trim()

  return (
    <div
      role="toolbar"
      aria-label={labels.toolbar}
      data-slot="selection-actions"
      data-status={status}
      className={cn(
        "inline-flex w-fit max-w-full min-w-0 flex-wrap items-center gap-[var(--hui-space-2)] rounded-[var(--hui-radius-4)] border-[0.5px] border-[var(--hui-color-border-base-primary)] bg-[var(--hui-color-background-base-primary)] p-[var(--hui-space-2)] text-[var(--hui-color-foreground-base-primary)] shadow-[var(--hui-shadow-lifted)]",
        smallText,
        className
      )}
      {...props}
    >
      {/* Always mounted, so each change of status is announced. */}
      <span role="status" className={cn(status === "working" || status === "error" ? "contents" : "sr-only")}>
        {status === "working" && (
          <TextShimmer duration={1.6} className="px-[var(--hui-space-3)] py-[var(--hui-space-2)] [font-weight:var(--hui-font-weight-medium)]">
            {labels.working}
          </TextShimmer>
        )}
        {status === "error" && (
          <span className="flex items-center gap-[var(--hui-space-2)] px-[var(--hui-space-3)] py-[var(--hui-space-2)]">
            <CircleAlertIcon strokeWidth={1.5} strokeLinecap="round"
              aria-hidden="true"
              className="size-3.5 shrink-0 text-[var(--hui-color-foreground-danger-primary)]"
            />
            {labels.error}
          </span>
        )}
      </span>

      {status === "idle" && (
        <>
          {actions.map((action) => (
            <Button key={action.id} variant="link" size="sm" onClick={() => onAction(action.id)}>
              {action.icon}
              {action.label}
            </Button>
          ))}
          {onPrompt && (
            <form
              className="flex min-w-0 items-center gap-[var(--hui-space-2)]"
              onSubmit={(event) => {
                event.preventDefault()
                if (trimmed === "") return
                onPrompt(trimmed)
                setInstruction("")
              }}
            >
              <input
                value={instruction}
                onChange={(event) => setInstruction(event.target.value)}
                aria-label={labels.prompt}
                placeholder={labels.promptPlaceholder}
                className={cn(
                  "h-[var(--hui-space-7)] w-40 min-w-0 rounded-[var(--hui-radius-2)] border-[0.5px] border-[var(--hui-color-border-base-tertiary)] bg-transparent px-[var(--hui-space-3)] text-[var(--hui-color-foreground-base-primary)] outline-none placeholder:text-[var(--hui-color-foreground-base-tertiary)] focus:border-[var(--hui-color-border-accent-emphasis)]",
                  smallText
                )}
              />
              <Button type="submit" size="icon-sm" disabled={trimmed === ""} aria-label={labels.send}>
                <ArrowUpIcon aria-hidden="true" strokeWidth={2} />
              </Button>
            </form>
          )}
        </>
      )}

      {(status === "result" || status === "error") && (
        <>
          {status === "result" && (
            <Button size="sm" onClick={onKeep}>
              {labels.keep}
            </Button>
          )}
          <Button variant="secondary" size="sm" onClick={onDiscard}>
            {labels.discard}
          </Button>
          {onRetry && (
            <Button variant="link" size="sm" onClick={onRetry}>
              {labels.retry}
            </Button>
          )}
        </>
      )}
    </div>
  )
}

export { SelectionActions }

"use client"

import * as React from "react"
import {
  PanelLeft as PanelLeftIcon,
  Search as SearchIcon,
  SquarePen as SquarePenIcon,
} from "honestui/icons"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"

export type SidebarNavItem = {
  id: string
  label: string
  icon: React.ReactNode
  /** A short count or state shown at the end of the row. */
  badge?: string
}

export type SidebarNavThread = {
  id: string
  title: string
}

export type SidebarNavLabels = {
  navigation: string
  collapse: string
  expand: string
  newChat: string
  threads: string
  searchThreads: string
  searchPlaceholder: string
  noThreads: string
  noMatches: (query: string) => string
}

export const defaultSidebarNavLabels: SidebarNavLabels = {
  navigation: "Workspace",
  collapse: "Collapse sidebar",
  expand: "Expand sidebar",
  newChat: "New chat",
  threads: "Chats",
  searchThreads: "Search chats",
  searchPlaceholder: "Search chats…",
  noThreads: "No chats yet.",
  noMatches: (query) => `No chats match “${query}”.`,
}

const rowText =
  "[font-size:var(--hui-font-size-small)] [letter-spacing:var(--hui-letter-spacing-small)] [line-height:var(--hui-line-height-small)]"

const row =
  "flex min-h-[var(--hui-space-9)] w-full min-w-0 cursor-pointer items-center gap-[var(--hui-space-3)] rounded-[var(--hui-radius-2)] border-0 bg-transparent px-[var(--hui-space-3)] text-left text-[var(--hui-color-foreground-base-primary)] outline-none motion-safe:[transition:var(--hui-transition-interactive)] hover:bg-[var(--hui-color-background-base-primary-hover)] focus-visible:[outline:var(--hui-focus-ring)] aria-[current]:bg-[var(--hui-color-background-neutral-secondary)] [&_svg]:size-4 [&_svg]:shrink-0"

export type SidebarNavProps = Omit<React.ComponentProps<"nav">, "children"> & {
  /** Shown at the top, such as a workspace name or switcher. Hidden when collapsed. */
  header?: React.ReactNode
  items: SidebarNavItem[]
  /** The `id` of the item for the current page. */
  activeItemId?: string
  onNavigate: (itemId: string) => void
  /** Past conversations, newest first. */
  threads: SidebarNavThread[]
  activeThreadId?: string
  onThreadSelect: (threadId: string) => void
  /** Passing it adds the New chat button. */
  onNewChat?: () => void
  /** Shown at the bottom. Hidden when collapsed. */
  footer?: React.ReactNode
  collapsed?: boolean
  defaultCollapsed?: boolean
  onCollapsedChange?: (collapsed: boolean) => void
  labels?: Partial<SidebarNavLabels>
}

/**
 * Navigation for a chat product: primary destinations, a searchable list of
 * past conversations, and a collapse to an icon rail.
 */
function SidebarNav({
  header,
  items,
  activeItemId,
  onNavigate,
  threads,
  activeThreadId,
  onThreadSelect,
  onNewChat,
  footer,
  collapsed: collapsedProp,
  defaultCollapsed = false,
  onCollapsedChange,
  labels: labelsProp,
  className,
  ...props
}: SidebarNavProps) {
  const labels = { ...defaultSidebarNavLabels, ...labelsProp }
  const [uncontrolledCollapsed, setUncontrolledCollapsed] = React.useState(defaultCollapsed)
  const isCollapsed = collapsedProp ?? uncontrolledCollapsed
  const [query, setQuery] = React.useState("")
  const threadsId = React.useId()

  const normalizedQuery = query.trim().toLowerCase()
  const visibleThreads = normalizedQuery
    ? threads.filter((thread) => thread.title.toLowerCase().includes(normalizedQuery))
    : threads

  const toggleCollapsed = () => {
    if (collapsedProp === undefined) setUncontrolledCollapsed(!isCollapsed)
    onCollapsedChange?.(!isCollapsed)
  }

  return (
    <nav
      aria-label={labels.navigation}
      data-slot="sidebar-nav"
      data-collapsed={isCollapsed ? "" : undefined}
      className={cn(
        "flex h-full min-h-0 shrink-0 flex-col gap-[var(--hui-space-3)] border-e-[0.5px] border-[var(--hui-color-border-base-primary)] bg-[var(--hui-color-background-base-secondary)] p-[var(--hui-space-3)] text-[var(--hui-color-foreground-base-primary)] motion-safe:transition-[width] motion-safe:duration-200",
        rowText,
        isCollapsed ? "w-[calc(var(--hui-space-9)+var(--hui-space-3)*2)]" : "w-60",
        className
      )}
      {...props}
    >
      <div className="flex min-w-0 items-center gap-[var(--hui-space-2)]">
        {!isCollapsed && header && <div className="min-w-0 flex-1 truncate">{header}</div>}
        <Button
          variant="link"
          size="icon"
          className={cn("shrink-0", !isCollapsed && "ms-auto")}
          aria-expanded={!isCollapsed}
          aria-label={isCollapsed ? labels.expand : labels.collapse}
          onClick={toggleCollapsed}
        >
          <PanelLeftIcon aria-hidden="true" />
        </Button>
      </div>

      <ul role="list" className="m-0 flex list-none flex-col gap-[var(--hui-space-1)] p-0">
        {onNewChat && (
          <li>
            <button
              type="button"
              className={row}
              aria-label={isCollapsed ? labels.newChat : undefined}
              onClick={onNewChat}
            >
              <SquarePenIcon aria-hidden="true" />
              {!isCollapsed && <span className="min-w-0 truncate">{labels.newChat}</span>}
            </button>
          </li>
        )}
        {items.map((item) => (
          <li key={item.id}>
            <button
              type="button"
              className={row}
              aria-current={item.id === activeItemId ? "page" : undefined}
              aria-label={isCollapsed ? item.label : undefined}
              onClick={() => onNavigate(item.id)}
            >
              <span aria-hidden="true" className="flex shrink-0">
                {item.icon}
              </span>
              {!isCollapsed && (
                <>
                  <span className="min-w-0 flex-1 truncate">{item.label}</span>
                  {item.badge && (
                    <span className="shrink-0 tabular-nums text-[var(--hui-color-foreground-base-secondary)]">
                      {item.badge}
                    </span>
                  )}
                </>
              )}
            </button>
          </li>
        ))}
      </ul>

      {/* The rail has no room for titles, so the thread list is left out when collapsed. */}
      {!isCollapsed && (
        <div className="flex min-h-0 flex-1 flex-col gap-[var(--hui-space-2)]">
          <p
            id={threadsId}
            className="m-0 px-[var(--hui-space-3)] text-[var(--hui-color-foreground-base-secondary)] [font-size:var(--hui-font-size-mini)] [font-weight:var(--hui-font-weight-medium)]"
          >
            {labels.threads}
          </p>
          {threads.length > 0 && (
            <label className="flex min-h-[var(--hui-space-9)] items-center gap-[var(--hui-space-3)] rounded-[var(--hui-radius-2)] border-[0.5px] border-[var(--hui-color-border-base-tertiary)] bg-[var(--hui-color-background-base-primary)] px-[var(--hui-space-3)] focus-within:border-[var(--hui-color-border-accent-emphasis)]">
              <SearchIcon
                aria-hidden="true"
                className="size-3.5 shrink-0 text-[var(--hui-color-foreground-base-secondary)]"
              />
              <input
                type="search"
                value={query}
                onChange={(event) => setQuery(event.target.value)}
                aria-label={labels.searchThreads}
                placeholder={labels.searchPlaceholder}
                className={cn(
                  "min-w-0 flex-1 border-0 bg-transparent text-[var(--hui-color-foreground-base-primary)] outline-none placeholder:text-[var(--hui-color-foreground-base-tertiary)]",
                  rowText
                )}
              />
            </label>
          )}
          {visibleThreads.length > 0 ? (
            <ul
              role="list"
              aria-labelledby={threadsId}
              className="m-0 flex min-h-0 list-none flex-col gap-[var(--hui-space-1)] overflow-y-auto p-0"
            >
              {visibleThreads.map((thread) => (
                <li key={thread.id}>
                  <button
                    type="button"
                    className={row}
                    aria-current={thread.id === activeThreadId ? "true" : undefined}
                    onClick={() => onThreadSelect(thread.id)}
                  >
                    <span className="min-w-0 truncate">{thread.title}</span>
                  </button>
                </li>
              ))}
            </ul>
          ) : (
            <p role="status" className="m-0 px-[var(--hui-space-3)] text-[var(--hui-color-foreground-base-secondary)]">
              {threads.length === 0 ? labels.noThreads : labels.noMatches(query.trim())}
            </p>
          )}
        </div>
      )}

      {!isCollapsed && footer && <div className="mt-auto min-w-0">{footer}</div>}
    </nav>
  )
}

export { SidebarNav }

