  LoaderCircle as LoaderCircleIcon,
  Search as SearchIcon,
  Sparkles as SparklesIcon,
} from "honestui/icons"

import { cn } from "@/lib/utils"
import { TextShimmer } from "@/components/animated/text-shimmer"
