} from "@/components/ui/collapsible"

export type ThinkingStatus = "running" | "done" | "error"

const labelText =
  "[font-size:var(--hui-font-size-small)] [font-weight:var(--hui-font-weight-medium)] [letter-spacing:var(--hui-letter-spacing-small)] [line-height:var(--hui-line-height-small)]"

const rowText =
  "[font-size:var(--hui-font-size-small)] [letter-spacing:var(--hui-letter-spacing-small)] [line-height:var(--hui-line-height-small)]"

/** New rows fade in as the trace grows. Skipped when motion is reduced. */
const rowEnter =
  "motion-safe:transition-[opacity,translate] motion-safe:duration-300 motion-safe:starting:translate-y-1 motion-safe:starting:opacity-0"

const statusTone: Record<ThinkingStatus, string> = {
  running: "text-[var(--hui-color-foreground-base-secondary)]",
  done: "text-[var(--hui-color-foreground-base-tertiary)]",
  error: "text-[var(--hui-color-foreground-danger-primary)]",
}

export type ThinkingStateProps = Omit<React.ComponentProps<"div">, "children"> & {
  /** What the agent is doing now. Drives the header treatment and the default open state. */
  status: ThinkingStatus
  /** The header text, such as "Thinking" or "Thought for 4 seconds". */
  label: string
  /** Replaces the header icon. */
  icon?: React.ReactNode
  /** Controls whether the trace is shown. */
  open?: boolean
  /** The initial open state. Without it, the trace is open while `status` is "running". */
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  /** The trace: `ThinkingStep`, `ThinkingText`, `ThinkingQuery`, and `ThinkingSource`. */
  children?: React.ReactNode
}

/**
 * A header that says what the agent is doing, with the trace behind it. The
 * trace follows `status` (open while running, closed once settled) until the
 * person opens or closes it, and their choice then stays.
 */
function ThinkingState({
  status,
  label,
  icon,
  open: openProp,
  defaultOpen,
  onOpenChange,
  children,
  className,
  ...props
}: ThinkingStateProps) {
  const [chosenOpen, setChosenOpen] = React.useState(defaultOpen)
  const open = openProp ?? chosenOpen ?? status === "running"
  const hasTrace = React.Children.count(children) > 0

  // Announce the label only when it changes, so the first render is not read twice.
  const [announcement, setAnnouncement] = React.useState("")
  const previousLabel = React.useRef(label)
  React.useEffect(() => {
    if (previousLabel.current === label) return
    previousLabel.current = label
    setAnnouncement(label)
  }, [label])

  const header = (
    <>
      <span aria-hidden="true" className={cn("flex shrink-0 [&_svg]:size-4", statusTone[status])}>
        {status === "error" ? <CircleAlertIcon strokeWidth={1.5} strokeLinecap="round" /> : (icon ?? <SparklesIcon />)}
      </span>
      {status === "running" ? (
        <TextShimmer duration={1.6} className={labelText}>
          {label}
        </TextShimmer>
      ) : (
        <span
          className={cn(
            labelText,
            // The alert icon carries the danger color. The label keeps a text color that stays readable.
            status === "error"
              ? "text-[var(--hui-color-foreground-base-primary)]"
              : "text-[var(--hui-color-foreground-base-secondary)]"
          )}
        >
          {label}
        </span>
      )}
    </>
  )

  return (
    <div
      data-slot="thinking-state"
      data-status={status}
      className={cn("flex w-full min-w-0 flex-col", className)}
      {...props}
    >
      <span role="status" className="sr-only">
        {announcement}
      </span>
      {hasTrace ? (
        <Collapsible
          open={open}
          onOpenChange={(nextOpen) => {
            setChosenOpen(nextOpen)
            onOpenChange?.(nextOpen)
          }}
        >
          <CollapsibleTrigger
            data-slot="thinking-state-trigger"
            className="group/thinking -mx-[var(--hui-space-2)] flex w-fit max-w-full items-center gap-[var(--hui-space-3)] rounded-[var(--hui-radius-2)] border-0 bg-transparent px-[var(--hui-space-2)] py-[var(--hui-space-2)] text-left outline-none motion-safe:[transition:var(--hui-transition-interactive)] hover:bg-[var(--hui-color-background-base-primary-hover)] focus-visible:[outline:var(--hui-focus-ring)]"
          >
            {header}
            <ChevronDownIcon
              aria-hidden="true"
              className="size-3.5 shrink-0 text-[var(--hui-color-foreground-base-tertiary)] motion-safe:transition-transform motion-safe:duration-200 group-data-panel-open/thinking:rotate-180"
            />
          </CollapsibleTrigger>
          <CollapsiblePanel>
            <ul
              role="list"
              data-slot="thinking-state-trace"
              className="m-0 ms-[var(--hui-space-3)] mt-[var(--hui-space-2)] flex list-none flex-col gap-[var(--hui-space-2)] border-s border-[var(--hui-color-border-base-primary)] py-[var(--hui-space-2)] ps-[var(--hui-space-4)]"
            >
              {children}
            </ul>
          </CollapsiblePanel>
        </Collapsible>
      ) : (
        <div className="flex items-center gap-[var(--hui-space-3)] py-[var(--hui-space-2)]">{header}</div>
      )}
    </div>
  )
}

export type ThinkingStepProps = React.ComponentProps<"li"> & {
  /** Defaults to "done". */
  status?: ThinkingStatus
  /** Secondary text after the step, such as a count or a file name. */
  detail?: React.ReactNode
  /** Sets `detail` in the monospace face, for file names and commands. */
  detailIsCode?: boolean
  /** Replaces the words read for the step's status. */
  statusLabel?: string
}

const defaultStepStatusLabel: Record<ThinkingStatus, string> = {
  running: "In progress",
  done: "Done",
  error: "Failed",
}

/** One step of work, with an icon and words for whether it is running, done, or failed. */
function ThinkingStep({
  status = "done",
  detail,
  detailIsCode = false,
  statusLabel,
  className,
  children,
  ...props
}: ThinkingStepProps) {
  const Icon =
    status === "running" ? LoaderCircleIcon : status === "error" ? CircleAlertIcon : CheckIcon

  return (
    <li
      data-slot="thinking-step"
      data-status={status}
      className={cn(
        "flex min-w-0 items-start gap-[var(--hui-space-3)]",
        rowText,
        rowEnter,
        className
      )}
      {...props}
    >
      <Icon
        strokeWidth={1.5}
        strokeLinecap="round"
        aria-hidden="true"
        className={cn(
          "mt-px size-3.5 shrink-0",
          statusTone[status],
          status === "running" && "motion-safe:animate-spin"
        )}
      />
      <span className="min-w-0 break-words text-[var(--hui-color-foreground-base-primary)] [font-weight:var(--hui-font-weight-medium)]">
        {children}
        <span className="sr-only"> ({statusLabel ?? defaultStepStatusLabel[status]})</span>
      </span>
      {detail !== undefined && (
        <span
          className={cn(
            "min-w-0 truncate text-[var(--hui-color-foreground-base-secondary)]",
            detailIsCode && "font-mono [font-size:var(--hui-font-size-mono-mini)]"
          )}
        >
          {detail}
        </span>
      )}
    </li>
  )
}

/** A paragraph of reasoning. */
function ThinkingText({ className, ...props }: React.ComponentProps<"li">) {
  return (
    <li
      data-slot="thinking-text"
      className={cn(
        "min-w-0 break-words text-[var(--hui-color-foreground-base-secondary)] [font-size:var(--hui-font-size-small)] [letter-spacing:var(--hui-letter-spacing-small)] [line-height:var(--hui-line-height-regular)]",
        rowEnter,
        className
      )}
      {...props}
    />
  )
}

export type ThinkingQueryProps = React.ComponentProps<"li"> & {
  /** Read before the query, so the row is not just a bare phrase. */
  prefix?: string
}

/** The search the agent ran. */
function ThinkingQuery({ prefix = "Searched for", className, children, ...props }: ThinkingQueryProps) {
  return (
    <li
      data-slot="thinking-query"
      className={cn(
        "flex min-w-0 items-start gap-[var(--hui-space-3)] text-[var(--hui-color-foreground-base-secondary)]",
        rowText,
        rowEnter,
        className
      )}
      {...props}
    >
      <SearchIcon
        aria-hidden="true"
        className="mt-px size-3.5 shrink-0 text-[var(--hui-color-foreground-base-tertiary)]"
      />
      <span className="min-w-0 break-words">
        <span className="sr-only">{prefix} </span>
        {children}
      </span>
    </li>
  )
}

export type ThinkingSourceProps = Omit<React.ComponentProps<"a">, "title"> & {
  href: string
  /** The page or site name. */
  title: React.ReactNode
  /** The host, shown after the title. */
  domain?: string
}

/** A page the agent read, as a link. Other anchor props pass through. */
function ThinkingSource({ title, domain, className, ...props }: ThinkingSourceProps) {
  return (
    <li data-slot="thinking-source" className={cn("min-w-0", rowEnter)}>
      <a
        className={cn(
          "group/source -mx-[var(--hui-space-2)] flex min-w-0 items-center gap-[var(--hui-space-3)] rounded-[var(--hui-radius-2)] px-[var(--hui-space-2)] py-[var(--hui-space-1)] no-underline outline-none motion-safe:[transition:var(--hui-transition-interactive)] hover:bg-[var(--hui-color-background-base-primary-hover)] focus-visible:[outline:var(--hui-focus-ring)]",
          rowText,
          className
        )}
        {...props}
      >
        <GlobeIcon
          aria-hidden="true"
          className="size-3.5 shrink-0 text-[var(--hui-color-foreground-base-tertiary)]"
        />
        <span className="min-w-0 truncate text-[var(--hui-color-foreground-base-primary)] underline decoration-[var(--hui-color-border-base-secondary)] underline-offset-2 [font-weight:var(--hui-font-weight-medium)] group-hover/source:decoration-current">
          {title}
        </span>
        {domain && (
          <span className="shrink-0 text-[var(--hui-color-foreground-base-secondary)]">{domain}</span>
        )}
      </a>
    </li>
  )
}

export { ThinkingState, ThinkingStep, ThinkingText, ThinkingQuery, ThinkingSource }

"use client"

import * as React from "react"
import {
  ChevronDown as ChevronDownIcon,
  CircleAlert as CircleAlertIcon,
  LoaderCircle as LoaderCircleIcon,
  Wrench as WrenchIcon,
} from "honestui/icons"

import { cn } from "@/lib/utils"
import {
  Collapsible,
  CollapsiblePanel,
  CollapsibleTrigger,
} from "@/components/ui/collapsible"
import { Popover, PopoverPopup, PopoverTrigger } from "@/components/ui/popover"

export type ToolLine = {
  text: string
  /** Defaults to "context". */
  kind?: "context" | "added" | "removed"
}

export type ToolCall = {
  id: string
  /** What the tool did, such as "Read image" or "Write 204 lines". */
  label: string
  /** The object of the call: a file name, a command, or a short note. */
  detail?: string
  /** Sets `detail` in the monospace face. */
  detailIsCode?: boolean
  /** Defaults to "done". */
  status?: "running" | "done" | "error"
  icon?: React.ReactNode
  /** What the call returned. A call with output can be expanded. */
  output?: ToolLine[]
  /** Sets `output` in the monospace face. */
  outputIsCode?: boolean
}

export type FileChange = {
  path: string
  added: number
  removed: number
  /** The diff. A change with lines shows them on hover, focus, or press. */
  lines?: ToolLine[]
}

export type ToolChipsLabels = {
  running: string
  failed: string
  changes: string
  showMoreChanges: (hiddenCount: number) => string
  diffFor: (path: string) => string
  added: (count: number) => string
  removed: (count: number) => string
}

export const defaultToolChipsLabels: ToolChipsLabels = {
  running: "Running",
  failed: "Failed",
  changes: "Files changed",
  showMoreChanges: (hiddenCount) => `Show ${hiddenCount} more`,
  diffFor: (path) => `Changes to ${path}`,
  added: (count) => `${count} added`,
  removed: (count) => `${count} removed`,
}

const rowText =
  "[font-size:var(--hui-font-size-small)] [letter-spacing:var(--hui-letter-spacing-small)] [line-height:var(--hui-line-height-small)]"

const codeText = "font-mono [font-size:var(--hui-font-size-mono-mini)]"

const interactiveRow =
  "border-0 bg-transparent outline-none motion-safe:[transition:var(--hui-transition-interactive)] hover:bg-[var(--hui-color-background-base-primary-hover)] focus-visible:[outline:var(--hui-focus-ring)]"

const rowEnter =
  "motion-safe:transition-[opacity,translate] motion-safe:duration-300 motion-safe:starting:translate-y-1 motion-safe:starting:opacity-0"

// Changed lines keep the primary text color on a tint. The success and danger
// foregrounds are too light for small text on their own tints.
const lineTone: Record<NonNullable<ToolLine["kind"]>, string> = {
  context: "text-[var(--hui-color-foreground-base-secondary)]",
  added: "bg-[var(--hui-color-background-success-primary)] text-[var(--hui-color-foreground-base-primary)]",
  removed: "bg-[var(--hui-color-background-danger-primary)] text-[var(--hui-color-foreground-base-primary)]",
}

// The `-hover` foregrounds are the theme's darker text step, which small counts need.
const addedCountTone = "text-[var(--hui-color-foreground-success-primary-hover)]"
const removedCountTone = "text-[var(--hui-color-foreground-danger-primary-hover)]"

const lineSign: Record<NonNullable<ToolLine["kind"]>, string> = {
  context: " ",
  added: "+",
  removed: "−",
}

export type ToolChipsProps = Omit<React.ComponentProps<"div">, "children"> & {
  /** The header text, such as "4 tool calls". */
  summary: string
  calls: ToolCall[]
  /** Files the run edited, shown as chips under the calls. */
  changes?: FileChange[]
  /** How many file chips to show before the rest move behind a button. */
  maxVisibleChanges?: number
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  labels?: Partial<ToolChipsLabels>
}

/**
 * An agent run as a list of tool calls, followed by the files it changed.
 * The list shows whatever `calls` holds, so append to the array as calls
 * arrive and update each call's `status` as it settles.
 */
function ToolChips({
  summary,
  calls,
  changes = [],
  maxVisibleChanges = 3,
  open,
  defaultOpen = true,
  onOpenChange,
  labels: labelsProp,
  className,
  ...props
}: ToolChipsProps) {
  const labels = React.useMemo(
    () => ({ ...defaultToolChipsLabels, ...labelsProp }),
    [labelsProp]
  )
  const [showAllChanges, setShowAllChanges] = React.useState(false)
  const visibleChanges = showAllChanges ? changes : changes.slice(0, maxVisibleChanges)
  const hiddenCount = changes.length - visibleChanges.length

  return (
    <div
      data-slot="tool-chips"
      className={cn(
        "flex w-full min-w-0 flex-col text-[var(--hui-color-foreground-base-primary)]",
        rowText,
        className
      )}
      {...props}
    >
      <Collapsible open={open} defaultOpen={defaultOpen} onOpenChange={onOpenChange}>
        <CollapsibleTrigger
          data-slot="tool-chips-trigger"
          className={cn(
            "group/summary -mx-[var(--hui-space-2)] flex w-fit max-w-full items-center gap-[var(--hui-space-2)] rounded-[var(--hui-radius-2)] px-[var(--hui-space-2)] py-[var(--hui-space-2)] text-left text-[var(--hui-color-foreground-base-secondary)]",
            interactiveRow
          )}
        >
          <ChevronDownIcon
            aria-hidden="true"
            className="size-3.5 shrink-0 -rotate-90 motion-safe:transition-transform motion-safe:duration-200 group-data-panel-open/summary:rotate-0"
          />
          <span className="min-w-0 truncate">{summary}</span>
        </CollapsibleTrigger>
        <CollapsiblePanel>
          <ul
            role="list"
            data-slot="tool-chips-calls"
            className="m-0 flex list-none flex-col gap-[var(--hui-space-1)] p-0 pt-[var(--hui-space-2)]"
          >
            {calls.map((call) => (
              <ToolCallRow key={call.id} call={call} labels={labels} />
            ))}
          </ul>
          {changes.length > 0 && (
            <div
              role="group"
              aria-label={labels.changes}
              data-slot="tool-chips-changes"
              className="mt-[var(--hui-space-3)] flex min-w-0 flex-wrap items-center gap-[var(--hui-space-2)] border-t border-[var(--hui-color-border-base-primary)] pt-[var(--hui-space-3)]"
            >
              {visibleChanges.map((change) => (
                <FileChangeChip key={change.path} change={change} labels={labels} />
              ))}
              {hiddenCount > 0 && (
                <button
                  type="button"
                  onClick={() => setShowAllChanges(true)}
                  className={cn(
                    "rounded-[var(--hui-radius-2)] px-[var(--hui-space-2)] py-[var(--hui-space-2)] text-[var(--hui-color-foreground-base-secondary)] underline underline-offset-2",
                    interactiveRow
                  )}
                >
                  {labels.showMoreChanges(hiddenCount)}
                </button>
              )}
            </div>
          )}
        </CollapsiblePanel>
      </Collapsible>
    </div>
  )
}

function ToolCallRow({ call, labels }: { call: ToolCall; labels: ToolChipsLabels }) {
  const status = call.status ?? "done"
  const hasOutput = Boolean(call.output?.length)

  const summary = (
    <>
      <span
        aria-hidden="true"
        className={cn(
          "flex size-4 shrink-0 items-center justify-center [&_svg]:size-3.5",
          status === "error"
            ? "text-[var(--hui-color-foreground-danger-primary)]"
            : "text-[var(--hui-color-foreground-base-tertiary)]"
        )}
      >
        {status === "running" ? (
          <LoaderCircleIcon className="motion-safe:animate-spin" />
        ) : status === "error" ? (
          <CircleAlertIcon strokeWidth={1.5} strokeLinecap="round" />
        ) : (
          (call.icon ?? <WrenchIcon />)
        )}
      </span>
      <span className="shrink-0 [font-weight:var(--hui-font-weight-medium)]">
        {call.label}
        {status !== "done" && (
          <span className="sr-only"> ({status === "running" ? labels.running : labels.failed})</span>
        )}
      </span>
      {call.detail && (
        <span
          className={cn(
            "min-w-0 truncate rounded-[var(--hui-radius-2)] bg-[var(--hui-color-background-base-secondary)] px-[var(--hui-space-2)] py-[var(--hui-space-1)] text-[var(--hui-color-foreground-base-secondary)]",
            call.detailIsCode && codeText
          )}
        >
          {call.detail}
        </span>
      )}
    </>
  )

  const rowLayout =
    "flex w-full min-w-0 items-center gap-[var(--hui-space-3)] rounded-[var(--hui-radius-2)] px-[var(--hui-space-2)] py-[var(--hui-space-2)] text-left"

  if (!hasOutput) {
    return (
      <li data-slot="tool-call" data-status={status} className={cn(rowLayout, rowEnter)}>
        {summary}
      </li>
    )
  }

  return (
    <li data-slot="tool-call" data-status={status} className={cn("min-w-0", rowEnter)}>
      <Collapsible>
        <CollapsibleTrigger className={cn("group/call", rowLayout, interactiveRow)}>
          {summary}
          <ChevronDownIcon
            aria-hidden="true"
            className="ms-auto size-3.5 shrink-0 -rotate-90 text-[var(--hui-color-foreground-base-tertiary)] motion-safe:transition-transform motion-safe:duration-200 group-data-panel-open/call:rotate-0"
          />
        </CollapsibleTrigger>
        <CollapsiblePanel>
          <ToolLines
            lines={call.output ?? []}
            isCode={call.outputIsCode}
            className="ms-[var(--hui-space-4)] mt-[var(--hui-space-1)] mb-[var(--hui-space-2)] border-s border-[var(--hui-color-border-base-primary)] ps-[var(--hui-space-3)]"
          />
        </CollapsiblePanel>
      </Collapsible>
    </li>
  )
}

function ToolLines({
  lines,
  isCode = false,
  className,
}: {
  lines: ToolLine[]
  isCode?: boolean
  className?: string
}) {
  const hasChanges = lines.some((line) => line.kind === "added" || line.kind === "removed")

  return (
    <div className={cn("flex min-w-0 flex-col overflow-x-auto", isCode && codeText, className)}>
      {lines.map((line, index) => {
        const kind = line.kind ?? "context"
        return (
          <div
            key={index}
            className={cn(
              "flex gap-[var(--hui-space-3)] px-[var(--hui-space-2)] [line-height:var(--hui-line-height-regular)]",
              isCode ? "whitespace-pre" : "break-words",
              lineTone[kind]
            )}
          >
            {/* The sign carries the meaning, so the tint is never the only cue. */}
            {hasChanges && <span className="w-[1ch] shrink-0 select-none">{lineSign[kind]}</span>}
            <span className="min-w-0">{line.text}</span>
          </div>
        )
      })}
    </div>
  )
}

function FileChangeChip({ change, labels }: { change: FileChange; labels: ToolChipsLabels }) {
  const chipLayout = cn(
    "inline-flex max-w-full items-center gap-[var(--hui-space-3)] rounded-[var(--hui-radius-2)] border-[0.5px] border-[var(--hui-color-border-base-secondary)] bg-[var(--hui-color-background-base-primary)] px-[var(--hui-space-3)] py-[var(--hui-space-2)] text-[var(--hui-color-foreground-base-primary)]",
    codeText
  )
  const counts = (
    <>
      <span className="min-w-0 truncate">{change.path}</span>
      <span className={cn("shrink-0 tabular-nums", addedCountTone)}>
        <span aria-hidden="true">+{change.added}</span>
        <span className="sr-only">{labels.added(change.added)}</span>
      </span>
      {change.removed > 0 && (
        <span className={cn("shrink-0 tabular-nums", removedCountTone)}>
          <span aria-hidden="true">−{change.removed}</span>
          <span className="sr-only">{labels.removed(change.removed)}</span>
        </span>
      )}
    </>
  )

  if (!change.lines?.length) {
    return (
      <span data-slot="tool-chips-change" className={chipLayout}>
        {counts}
      </span>
    )
  }

  return (
    <Popover>
      <PopoverTrigger
        openOnHover
        delay={150}
        data-slot="tool-chips-change"
        className={cn(
          chipLayout,
          "cursor-pointer outline-none motion-safe:[transition:var(--hui-transition-interactive)] hover:bg-[var(--hui-color-background-base-primary-hover)] focus-visible:[outline:var(--hui-focus-ring)] data-popup-open:bg-[var(--hui-color-background-base-primary-hover)]"
        )}
      >
        {counts}
      </PopoverTrigger>
      <PopoverPopup
        align="start"
        aria-label={labels.diffFor(change.path)}
        className="w-80 max-w-[calc(100vw-2rem)] p-0"
      >
        <ToolLines lines={change.lines} isCode className="py-[var(--hui-space-2)]" />
      </PopoverPopup>
    </Popover>
  )
}

export { ToolChips }
